function deepLearningTrackSummary(){let mastered=0,total=0,cycles=[];for(const [cat] of examPlan()){const source=allQuestions().filter(q=>q.category===cat),bucket=fortyExposureBucket(cat,source);mastered+=source.filter(q=>progressFor(q.id).status==='known').length;total+=source.length;cycles.push(Number(bucket.cycle)||1)}return{mastered,total,cycle:cycles.length?Math.min(...cycles):1}}
function fortyExposureBucket(cat,source){const st=userState(),valid=new Set(source.map(q=>String(q.id))),existing=st.fortyQuestionExposure[cat],seen=new Set(Array.isArray(existing?.seen)?existing.seen.map(String).filter(id=>valid.has(id)):[]);if(existing?.version!==3){for(const session of st.sessions){if(!['exam','guided-exam'].includes(session?.type)||!Array.isArray(session.review))continue;for(const row of session.review)if(row?.category===cat&&valid.has(String(row.id)))seen.add(String(row.id))}for(const [key,rotation] of Object.entries(st.quizRotation)){if(!key.endsWith(`:${cat}`)||!Array.isArray(rotation?.seen))continue;rotation.seen.map(String).filter(id=>valid.has(id)).forEach(id=>seen.add(id))}for(const [key,bucket] of Object.entries(st.deepLearning.tracks)){if(!key.endsWith(`:${cat}`)||!Array.isArray(bucket?.servedWeak))continue;bucket.servedWeak.map(String).filter(id=>valid.has(id)).forEach(id=>seen.add(id))}}const bucket={version:3,cycle:Math.max(1,Number(existing?.cycle)||1),seen:[...seen],size:source.length,updatedAt:existing?.updatedAt||new Date().toISOString()};st.fortyQuestionExposure[cat]=bucket;return bucket}
