function timerMarkup(){return `<div class="exam-timer" data-exam-timer role="timer" aria-label="Tempo rimasto: ${formatTime(quiz.remaining)}"><span class="exam-timer-label">Tempo rimasto</span><strong data-exam-time>${formatTime(quiz.remaining)}</strong><span class="exam-timer-note">La prova termina automaticamente a 00:00</span></div>`}
