function requestDeliveryConfirmation(onConfirm){document.querySelector('.delivery-confirm')?.remove();const missing=unansweredCount(),overlay=document.createElement('div');overlay.className='delivery-confirm';overlay.innerHTML=`<div class="delivery-confirm-card" role="dialog" aria-modal="true" aria-labelledby="deliveryConfirmTitle"><div class="eyebrow">Consegna prova</div><h2 id="deliveryConfirmTitle">Sei sicuro di voler chiudere?</h2><p>${missing?`Hai ancora <strong>${missing}</strong> ${missing===1?'domanda non risposta':'domande non risposte'}. Puoi annullare e aprirle dalla panoramica.`:'Hai risposto a tutte le 40 domande.'}</p><div class="quiz-actions"><button class="ghost" type="button" data-cancel-delivery>Continua la prova</button><button class="primary" type="button" data-confirm-delivery>Consegna e chiudi</button></div></div>`;document.body.append(overlay);const close=()=>{document.removeEventListener('keydown',onKey);overlay.remove()},onKey=e=>{if(e.key==='Escape')close()};overlay.querySelector('[data-cancel-delivery]').onclick=close;overlay.querySelector('[data-confirm-delivery]').onclick=()=>{close();onConfirm()};overlay.onclick=e=>{if(e.target===overlay)close()};document.addEventListener('keydown',onKey);overlay.querySelector('[data-cancel-delivery]').focus()}
