function discardActiveQuiz(){clearInterval(timerHandle);if(quiz?.exposureBefore)userState().fortyQuestionExposure=JSON.parse(JSON.stringify(quiz.exposureBefore));clearActiveQuiz();quiz=null}
function guardQuizMenuNavigation(event){const link=event.target.closest('.bottom-nav a,.brand');if(!link||!isTimedFortyQuiz()||quiz.finished)return;const target=link.getAttribute('href');if(!target?.startsWith('#')||target===location.hash)return;event.preventDefault();event.stopImmediatePropagation();requestAbandonQuizConfirmation(()=>{discardActiveQuiz();if(location.hash===target)router();else location.hash=target})}

function nav(route){const menu=document.querySelector('.bottom-nav');document.querySelectorAll('.bottom-nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===route));const active=menu?.querySelector('a.active:not(.hidden)');if(active&&window.matchMedia('(max-width:560px)').matches){const left=Math.max(0,active.offsetLeft-menu.clientWidth+active.offsetWidth);menu.scrollTo({left,behavior:'smooth'})}window.scrollTo({top:0,behavior:'instant'})}
function setHeader(){const top=document.querySelector('.topbar'),isAdmin=currentUser?.role==='admin';document.querySelectorAll('[data-admin-nav]').forEach(link=>link.classList.toggle('hidden',!isAdmin));top.querySelectorAll('.account').forEach(x=>x.remove());if(currentUser){const wrap=document.createElement('div');wrap.className='account';wrap.innerHTML=`<span>${esc(currentUser.name)}${isAdmin?' · Admin':''}</span>${cloudMode?`<span class="header-version" title="Versione software installata">v${esc(runtimeConfig.version||'—')}</span>`:''}<button class="ghost compact theme-button" data-theme-cycle title="Cambia tema">◐ <span data-theme-label>${themeLabel(userState().theme)}</span></button>${cloudMode?'<a class="button ghost compact" href="#account">Account</a>':'<button class="ghost compact update-check-button" data-update-check>Aggiornamenti</button>'}<button class="ghost compact" data-logout>Esci</button>`;top.append(wrap);wrap.querySelector('[data-theme-cycle]')?.addEventListener('click',cycleTheme);wrap.querySelector('[data-update-check]')?.addEventListener('click',()=>checkForUpdates(true));wrap.querySelector('[data-logout]').onclick=logout;applyTheme()}}
function routeTo(h){location.hash=h}
function loginView(){nav('home');setHeader();document.querySelector('.bottom-nav').classList.add('hidden');if(cloudMode){app.innerHTML=`<section class="auth-shell"><div class="auth-copy"><img class="auth-logo" data-brand-logo src="${esc(runtimeConfig.logoUrl||'logo-vvf.jpg')}" alt="Logo del portale"><div class="eyebrow">${esc(runtimeConfig.siteName||'Quiz 400 VVF 2026')}</div><h1>Bentornato</h1><p>Accedi per ritrovare progressi, domande da ripetere e simulazioni su tutti i tuoi dispositivi.</p>${amateurDisclaimerMarkup()}</div><form class="card auth-card" id="authForm"><label>Nome utente<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" minlength="8" required></label><button class="primary" type="submit">Accedi</button><div class="auth-links"><a href="#forgot-password">Password dimenticata?</a>${runtimeConfig.registrationEnabled?'<a href="#register">Crea un account</a>':''}</div><p class="meta">${esc(runtimeConfig.privacyNotice||'')}</p></form></section>`;app.querySelector('#authForm').onsubmit=login;return}const first=!users.length;app.innerHTML=`<section class="auth-shell"><div class="auth-copy"><img class="auth-logo" data-brand-logo src="logo-vvf.jpg" alt="Logo del portale"><div class="eyebrow">Quiz 400 VVF 2026</div><h1>${first?'Crea il primo amministratore':'Bentornato'}</h1><p>${first?'Il primo account gestirà gli utenti. I dati restano su questo dispositivo.':'Accedi per ritrovare progressi, domande da ripetere e simulazioni.'}</p>${amateurDisclaimerMarkup()}</div><form class="card auth-card" id="authForm"><label>Nome utente<input name="username" autocomplete="username" required></label>${first?'<label>Nome visualizzato<input name="name" required></label>':''}<label>Password<input name="password" type="password" autocomplete="current-password" minlength="6" required></label><button class="primary" type="submit">${first?'Crea amministratore':'Accedi'}</button><p class="meta">${first?'La password deve avere almeno 6 caratteri.':'Gli account sono creati da un amministratore.'}</p></form></section>`;app.querySelector('#authForm').onsubmit=first?bootstrapAdmin:login}
async function bootstrapAdmin(e){e.preventDefault();const f=new FormData(e.currentTarget),username=String(f.get('username')).trim().toLowerCase();if(!username)return;const u={id:crypto.randomUUID(),username,name:String(f.get('name')).trim(),role:'admin',passwordHash:await hash(String(f.get('password'))),createdAt:new Date().toISOString(),active:true,state:{progress:{},sessions:[],categoryCursor:{},examCursor:{},examCount:0,deepLearning:{enabled:false,tracks:{}}}};users=[u];saveUsers();signIn(u)}
async function login(e){e.preventDefault();const f=new FormData(e.currentTarget);if(cloudMode){try{const result=await cloudApi('./api/auth/login',{method:'POST',body:JSON.stringify({username:String(f.get('username')).trim(),password:String(f.get('password'))})});examConfig=result.config||examConfig;signIn(result.user)}catch(error){notify(error.message)}return}const u=users.find(x=>x.username===String(f.get('username')).trim().toLowerCase());if(!u||!u.active||u.passwordHash!==await hash(String(f.get('password'))))return notify('Credenziali non valide');signIn(u)}
function signIn(u){if(cloudMode)users=[u];currentUser={id:u.id,name:u.name,username:u.username,email:u.email,role:u.role,mustChangePassword:Boolean(u.mustChangePassword)};updatePromptedVersion=null;if(!cloudMode)sessionStorage.setItem(SESSION,u.id);applyTheme();document.querySelector('.bottom-nav').classList.remove('hidden');setHeader();routeTo(currentUser.mustChangePassword?'change-password':'home');router();startAutomaticUpdateChecks();setTimeout(maybeShowReleaseNotes,500)}
async function logout(){clearInterval(timerHandle);clearInterval(updateCheckTimer);quiz=null;if(cloudMode){try{await portableSync();await cloudApi('./api/auth/logout',{method:'POST'})}catch{}}currentUser=null;users=cloudMode?[]:users;updateCheckedFor=null;updatePromptedVersion=null;sessionStorage.removeItem(SESSION);location.hash='login';loginView()}

function showUpdateNotice(info){document.querySelector('[data-update-dialog]')?.remove();const dialog=document.createElement('div');dialog.className='update-dialog-backdrop';dialog.dataset.updateDialog='';dialog.innerHTML=`<section class="card update-dialog" role="dialog" aria-modal="true" aria-labelledby="updateTitle"><div class="eyebrow">Aggiornamento disponibile</div><h2 id="updateTitle">Quiz 400 VVF 2026 ${esc(info.latestVersion)}</h2><p>È disponibile una versione più recente della ${esc(info.currentVersion)} installata.</p><p><b>I tuoi dati non andranno persi:</b> prima dell’installazione viene creato un backup automatico e la cartella <i>portable-data</i> resta intatta.</p><div class="quiz-actions"><button class="primary" data-update-now>Aggiorna ora</button><button class="ghost" data-update-close>Più tardi</button>${info.releaseUrl?`<a class="button ghost" href="${esc(info.releaseUrl)}" target="_blank" rel="noopener">Note della release</a>`:''}</div></section>`;document.body.append(dialog);dialog.querySelector('[data-update-now]').onclick=()=>startInAppUpdate(info,dialog);dialog.querySelector('[data-update-close]').onclick=()=>dialog.remove();dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.remove()})}
async function startInAppUpdate(info,dialog){const panel=dialog.querySelector('.update-dialog');panel.innerHTML=`<div class="update-spinner" aria-hidden="true"></div><div class="eyebrow">Aggiornamento in corso</div><h2>Installazione della versione ${esc(info.latestVersion)}</h2><p>Non chiudere questa pagina. L’app crea il backup, installa la nuova versione e si riavvia automaticamente.</p><p class="meta" data-update-progress>Avvio dell’aggiornamento…</p>`;try{const response=await fetch('./api/update-start',{method:'POST',cache:'no-store'});if(response.status===409){panel.querySelector('[data-update-progress]').textContent='L’app risulta già aggiornata. Ricarico la pagina…';setTimeout(()=>location.reload(),900);return}if(!response.ok)throw Error();panel.querySelector('[data-update-progress]').textContent='Download e installazione in corso…';await waitForUpdatedApp(info.latestVersion,panel)}catch{panel.innerHTML=`<div class="eyebrow">Aggiornamento non avviato</div><h2>Riprova tra poco</h2><p>Controlla la connessione oppure usa il file Aggiorna incluso nella cartella dell’app.</p><div class="quiz-actions"><button class="primary" data-update-close>Chiudi</button></div>`;panel.querySelector('[data-update-close]').onclick=()=>dialog.remove()}}
async function waitForUpdatedApp(expectedVersion,panel){const deadline=Date.now()+300000;while(Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,1800));try{const response=await fetch(`./api/update-check?t=${Date.now()}`,{cache:'no-store'});if(!response.ok)continue;const status=await response.json();if(status.currentVersion===expectedVersion&&!status.updateAvailable){panel.innerHTML=`<div class="eyebrow">Aggiornamento completato</div><h2>Versione ${esc(expectedVersion)} installata</h2><p>I dati personali sono al sicuro. Ora svuota la vecchia cache e carica i file nuovi.</p><div class="quiz-actions"><button class="primary" data-refresh-updated-app>Ricarica e aggiorna cache</button></div>`;panel.querySelector('[data-refresh-updated-app]').onclick=()=>refreshApplicationCache(panel);return}}catch{}}throw Error('timeout')}
async function refreshApplicationCache(panel){const button=panel.querySelector('[data-refresh-updated-app]');if(button){button.disabled=true;button.textContent='Aggiornamento cache…'}try{if('caches'in window){const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith('quiz400vvf-')).map(key=>caches.delete(key)))}if('serviceWorker'in navigator){const registration=await navigator.serviceWorker.getRegistration();await registration?.update()}}catch{}const target=new URL('./',location.href);target.searchParams.set('updated',Date.now());target.hash='home';location.replace(target.href)}
async function checkForUpdates(manual=false,periodic=false){if(!currentUser)return;if(cloudMode){if(currentUser.role==='admin')await checkPortalUpdate(manual,periodic);return}if(!manual&&!periodic&&updateCheckedFor===currentUser.id)return;if(periodic&&Date.now()-lastUpdateCheckAt<300000)return;if(!manual&&!periodic)updateCheckedFor=currentUser.id;lastUpdateCheckAt=Date.now();if(manual)notify('Controllo aggiornamenti…');try{const response=await fetch(`./api/update-check?t=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw Error();const info=await response.json();if(info.updateAvailable){if(manual||updatePromptedVersion!==info.latestVersion){updatePromptedVersion=info.latestVersion;showUpdateNotice(info)}}else if(manual)notify(`Versione ${info.currentVersion}: l’app è aggiornata`)}catch{if(manual)notify('Controllo aggiornamenti non disponibile')}}
function startAutomaticUpdateChecks(){clearInterval(updateCheckTimer);if(!currentUser)return;checkForUpdates(false);updateCheckTimer=setInterval(()=>checkForUpdates(false,true),15*60*1000)}

function summary(){const vals=Object.values(userState().progress);return {answered:vals.filter(x=>x.attempts).length,known:vals.filter(x=>x.status==='known').length,review:vals.filter(x=>x.status==='review').length,unknown:vals.filter(x=>x.status==='unknown').length}}
function categoryMetrics(category='all'){
 const questions=categoryQuestionPool(category),counts={known:0,review:0,unknown:0,unanswered:0};let attempts=0,correctAttempts=0,wrongAttempts=0,skipped=0;
 for(const q of questions){const p=progressFor(q.id),status=['known','review','unknown'].includes(p.status)?p.status:'unanswered';counts[status]++;attempts+=Number(p.attempts)||0;correctAttempts+=Number(p.correct)||0;wrongAttempts+=Number(p.wrong)||0;skipped+=Number(p.skipped)||0}
 const answered=counts.known+counts.review+counts.unknown,graded=correctAttempts+wrongAttempts;
 return {category,total:questions.length,...counts,answered,toDo:counts.unanswered,attempts,correctAttempts,wrongAttempts,skipped,coverage:questions.length?Math.round(answered/questions.length*100):0,accuracy:graded?Math.round(correctAttempts/graded*100):null};
}
const coverageLabel=metrics=>metrics.answered&&metrics.coverage===0?'Meno dell’1%':`${metrics.coverage}%`;
function pieChartMarkup(metrics,title='Situazione domande'){
 const total=Math.max(1,metrics.total),known=metrics.known/total*100,review=metrics.review/total*100,unknown=metrics.unknown/total*100,toDo=metrics.toDo/total*100;
 return `<section class="card mastery-summary"><div class="mastery-copy"><div class="eyebrow">${esc(title)}</div><h2>${coverageLabel(metrics)} completato</h2><p>${metrics.accuracy===null?'Completa le prime domande per calcolare la precisione.':`Precisione sulle risposte date: <strong>${metrics.accuracy}%</strong>.`}</p><div class="mastery-legend"><span><i class="known"></i><b>${metrics.known}</b> Le so</span><span><i class="review"></i><b>${metrics.review}</b> Da ripetere</span><span><i class="unknown"></i><b>${metrics.unknown}</b> Non le so</span><span><i class="unanswered"></i><b>${metrics.toDo}</b> Da fare</span></div></div><div class="mastery-pie" role="img" aria-label="${metrics.known} note, ${metrics.review} da ripetere, ${metrics.unknown} non note, ${metrics.toDo} da fare" style="--pie-known:${known}%;--pie-review:${known+review}%;--pie-unknown:${known+review+unknown}%;--pie-todo:${known+review+unknown+toDo}%"><span><b>${metrics.answered}</b><small>su ${metrics.total}</small></span></div></section>`;
}
function rowsByCategory(rows){const result={};for(const row of rows){const q=row.q||row,category=macroCategoryId(q.category||row.category);if(!category)continue;const bucket=result[category]??={correct:0,wrong:0,blank:0,total:0};bucket.total++;if(row.blank)bucket.blank++;else if(row.correct)bucket.correct++;else bucket.wrong++}for(const bucket of Object.values(result)){const answered=bucket.correct+bucket.wrong;bucket.accuracy=answered?Math.round(bucket.correct/answered*100):null}return result}
function recordSession(type,rows,extra={}){const correct=rows.filter(row=>row.correct).length,wrong=rows.filter(row=>!row.correct&&!row.blank).length,blank=rows.filter(row=>row.blank).length,answered=correct+wrong,perCategory=rowsByCategory(rows),category=Object.keys(perCategory).length===1?Object.keys(perCategory)[0]:null,review=rows.map(row=>{const q=row.q||row;return{id:String(q.id),category:q.category||row.category||null,choiceText:row.blank?null:String(q.answers?.[row.choice]??''),correctText:String(q.answers?.[q.correct]??''),blank:Boolean(row.blank),correct:Boolean(row.correct)}}),session={id:crypto.randomUUID(),type,at:new Date().toISOString(),correct,wrong,blank,score:scoreFor(correct,wrong),accuracy:answered?Math.round(correct/answered*100):null,questionCount:rows.length,category,perCategory,review,...extra},sessions=userState().sessions;sessions.push(session);sessions.filter(item=>Array.isArray(item.review)).slice(0,-5).forEach(item=>delete item.review);return session}
const sessionTypeLabel=type=>({study:'Quiz ordinato per materia',guided:'Quiz guidato per materia',tutor:'Tutor','guided-exam':'Prova guidata 40',exam:'Simulazione ufficiale 40','daily-challenge':'Sfida del giorno'}[type]||'Quiz');
function categorySessions(category){return userState().sessions.map(session=>{const keys=category==='logica'?['logica','brani','insiemi']:[category],parts=keys.map(key=>session.perCategory?.[key]).filter(Boolean);if(parts.length){const result=parts.reduce((sum,item)=>({correct:sum.correct+(Number(item.correct)||0),wrong:sum.wrong+(Number(item.wrong)||0),blank:sum.blank+(Number(item.blank)||0),total:sum.total+(Number(item.total)||0)}),{correct:0,wrong:0,blank:0,total:0}),answered=result.correct+result.wrong;return{...session,...result,accuracy:answered?Math.round(result.correct/answered*100):null,score:scoreFor(result.correct,result.wrong),category}}if(macroCategoryId(session.category)===category)return{...session,category};return null}).filter(Boolean)}
function sessionSummary(types){const rows=userState().sessions.filter(session=>types.includes(session.type)),accuracies=rows.map(session=>Number(session.accuracy)).filter(Number.isFinite),scores=rows.map(session=>Number(session.score)).filter(Number.isFinite);return {count:rows.length,averageAccuracy:accuracies.length?Math.round(accuracies.reduce((sum,value)=>sum+value,0)/accuracies.length):null,bestScore:scores.length?Math.max(...scores):null,rows}}
function weaknessInsights(){return categories.map(category=>{const metrics=categoryMetrics(category.id),graded=metrics.correctAttempts+metrics.wrongAttempts,errorRate=graded?metrics.wrongAttempts/graded:0,weakKnown=metrics.known+metrics.review+metrics.unknown,weakRate=weakKnown?(metrics.review+metrics.unknown)/weakKnown:0,priority=Math.round(errorRate*55+weakRate*35+(metrics.toDo/Math.max(1,metrics.total))*10),target=metrics.unknown?'unknown':metrics.review?'review':'unanswered';return {category,metrics,priority,target}}).filter(item=>item.metrics.attempts>0&&item.priority>0).sort((a,b)=>b.priority-a.priority)}
function targetedRecommendationsMarkup(limit=3){const items=weaknessInsights().slice(0,limit);if(!items.length)return `<div class="card targeted-empty"><h3>Esercitazioni mirate</h3><p class="meta">Completa qualche quiz: l’app confronterà errori, precisione e livello di padronanza per individuare le materie da rinforzare.</p></div>`;return `<section class="targeted-section"><div class="section-head"><div><div class="eyebrow">Analisi automatica</div><h2>Esercitazioni consigliate</h2></div></div><div class="targeted-grid">${items.map((item,index)=>`<article class="card targeted-card"><span class="priority-badge">Priorità ${index+1}</span><h3>${esc(item.category.name)}</h3><p><b>${item.metrics.accuracy??0}%</b> di precisione · ${item.metrics.review} da ripetere · ${item.metrics.unknown} non note</p><a class="button ${index?'ghost':'primary'}" href="#targeted/${item.category.id}:${item.target}">Esercitazione mirata</a></article>`).join('')}</div></section>`}
function sessionHistoryMarkup(rows,empty='Nessun quiz completato.'){if(!rows.length)return`<div class="card meta">${empty}</div>`;return`<p class="meta history-help">Puoi aprire e rivedere tutte le domande degli ultimi 5 quiz completati.</p>${rows.slice(-8).reverse().map(session=>{const reviewable=Array.isArray(session.review)&&session.review.length&&session.id;return`<article class="card history quiz-history"><div class="history-title"><b>${esc(sessionTypeLabel(session.type))}</b><small>${session.category?`${esc(catName(session.category))} · `:''}${new Date(session.at).toLocaleString('it')}</small></div><div class="history-summary"><div class="history-score"><strong>${session.accuracy??'—'}%</strong><span>Precisione</span><strong>${Number(session.score||0).toLocaleString('it')} pt</strong></div><div class="history-counts"><span class="correct"><b>${session.correct||0}</b> Giuste</span><span class="wrong"><b>${session.wrong||0}</b> Sbagliate</span><span class="blank"><b>${session.blank||0}</b> Non risposte</span></div>${reviewable?`<a class="button ghost compact history-review" href="#session/${encodeURIComponent(session.id)}">Rivedi domande</a>`:''}</div></article>`}).join('')}`}
function explanationMarkup(text){return `<details class="explanation-details"><summary><span>Mostra spiegazione</span><span class="explanation-chevron" aria-hidden="true">⌄</span></summary><div class="explanation-copy">${text?esc(text):'Spiegazione non disponibile per questo quesito.'}</div></details>`}
function home(){nav('home');const s=summary();app.innerHTML=`<section class="hero"><div class="eyebrow">400 Vigili del Fuoco · 11.070 quesiti</div><h1>Studia tutto. Ricorda meglio.</h1><p>Segui ogni materia nell’ordine originale, riprendi da dove eri arrivato e concentra il ripasso sui punti deboli.</p><div class="hero-actions"><a class="button secondary" href="#categories">Continua un argomento</a><a class="button ghost light" href="#simulation">Prova 40/40</a></div></section><div class="section-head"><h2>La tua preparazione</h2></div><div class="stat-row four"><div class="card stat"><strong>${s.answered}</strong><span class="meta">Fatte</span></div><div class="card stat"><strong>${s.known}</strong><span class="meta">Le so</span></div><div class="card stat"><strong>${s.review}</strong><span class="meta">Ripetere</span></div><div class="card stat"><strong>${s.unknown}</strong><span class="meta">Non so</span></div></div><div class="quick-grid"><a class="card quick" href="#review/review"><b>Da ripetere</b><span>Rivedi quelle incerte</span></a><a class="card quick" href="#review/unknown"><b>Non le so</b><span>Lavora sugli errori</span></a><a class="card quick" href="#review/unanswered"><b>Non risposte</b><span>Completa la banca dati</span></a><a class="card quick accent" href="#simulation"><b>Simulazione</b><span>40 domande · 40 minuti</span></a></div>${targetedRecommendationsMarkup(1)}${currentUser.role==='admin'?'<div class="section-head"><h2>Amministrazione</h2></div><div class="quick-grid"><a class="card quick" href="#users"><b>Utenti e statistiche</b><span>Gestisci account e consulta i risultati.</span></a><a class="card quick" href="#settings"><b>Impostazioni</b><span>Configura portale, prove, backup e servizi.</span></a></div>':''}`}
function categoryCards(){return `<div class="grid">${categories.map(c=>{const qs=categoryQuestionPool(c.id),done=qs.filter(q=>progressFor(q.id).attempts).length,p=Math.round(done/qs.length*100);return `<a class="card category" href="#category/${c.id}"><div class="cat-icon">${c.icon}</div><h3>${c.name}</h3><div class="meta">${done.toLocaleString('it')}/${qs.length.toLocaleString('it')} completate</div><div class="progress"><span style="width:${p}%"></span></div><small>${p}% · riprendi dalla n. ${Math.min(done+1,qs.length)}</small></a>`}).join('')}</div>`}
function categoriesView(){nav('categories');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Percorso completo e ordinato</div><h1>Tutte le materie</h1></div></div>${categoryCards()}`}
function categoryView(id){nav('categories');const c=categories.find(x=>x.id===id);if(!c)return categoriesView();const metrics=categoryMetrics(id),sessions=categorySessions(id);app.innerHTML=`<div class="section-head"><div><div class="eyebrow">${metrics.answered}/${metrics.total} classificate</div><h1>${c.name}</h1></div></div>${pieChartMarkup(metrics,`Statistiche ${c.name}`)}<div class="card"><h2>Percorso completo</h2><p>Le domande vengono presentate nell’ordine originale. Puoi interrompere e riprendere dalla prima non risposta.</p><div class="quiz-actions"><button class="primary" data-resume>${metrics.toDo<metrics.total?'Riprendi dalla prima non fatta':'Inizia dalla domanda 1'}</button><button class="ghost" data-start>Ricomincia dalla n. 1</button></div></div><div class="card guided-card"><div class="mode-title"><span class="mode-icon">✓</span><div><h2>Quiz guidato</h2><p>Stile quiz ufficiale, con esito, risposta corretta e spiegazione subito dopo ogni risposta. Ogni errore entra subito in “Da ripetere”.</p></div></div><div class="guided-options"><button class="secondary" data-guided="15">15 domande</button><button class="secondary" data-guided="30">30 domande</button><button class="secondary" data-guided="50">50 domande</button></div></div><div class="filter-row"><button class="status-chip known" data-filter="known">Le so (${metrics.known})</button><button class="status-chip review" data-filter="review">Da ripetere (${metrics.review})</button><button class="status-chip unknown" data-filter="unknown">Non le so (${metrics.unknown})</button><button class="status-chip unanswered" data-filter="unanswered">Da fare (${metrics.toDo})</button></div><div class="section-head"><h2>Risultati dei quiz di ${c.name}</h2></div>${sessionHistoryMarkup(sessions,'Non hai ancora completato quiz in questa materia.')}`;app.querySelector('[data-resume]').onclick=()=>startCategory(id,'resume');app.querySelector('[data-start]').onclick=()=>startCategory(id,'start');app.querySelectorAll('[data-guided]').forEach(b=>b.onclick=()=>startGuided(id,+b.dataset.guided));app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>startFiltered(id,b.dataset.filter))}
function startCategory(cat,mode){const pool=categoryQuestionPool(cat);let index=0;if(mode==='resume'){const found=pool.findIndex(q=>progressFor(q.id).status==='unanswered');index=found<0?0:found}quiz={kind:'study',pool,index,history:{},selected:null,sourceCategory:cat};renderQuestion()}
function startGuided(cat,count){const seed=createQuizSeed(`guided-${cat}`),source=categoryQuestionPool(cat),selected=takeRotating(source,count,'guided-category',cat,seed),pool=shuffleWithSeed(selected,`${seed}|questions`).map(q=>shuffleGuidedAnswers(q,`${seed}|answers|${q.id}`));persist();quiz={kind:'guided',pool,index:0,history:{},selected:null,sourceCategory:cat,generatedAt:new Date().toISOString()};renderGuided()}
function shuffleGuidedAnswers(q,seed=`${Date.now()}|${q.id}`){const indexed=shuffleWithSeed(q.answers.map((text,index)=>({text,index})),seed);return {...q,answers:indexed.map(x=>x.text),correct:indexed.findIndex(x=>x.index===q.correct)}}
function renderGuided(){const q=quiz.pool[quiz.index],h=quiz.history[q.id],selected=h?.choice??(quiz.mode==='guided-exam'?quiz.selected:null),completed=h&&!h.blank,last=quiz.index===quiz.pool.length-1;app.innerHTML=`<div class="trainer-title">Esercitazione in modalità Trainer</div>${quiz.mode==='guided-exam'?timerMarkup()+questionOverviewMarkup():''}<div class="quiz-head"><strong>Domanda n.${quiz.index+1} di ${quiz.pool.length} - ${catName(q.category)}</strong><span>${quiz.index+1}/${quiz.pool.length}</span></div><h1 class="question">${esc(q.text)}</h1>${q.image?`<img class="question-image" src="${esc(q.image)}" alt="Diagramma del quesito">`:''}<div class="answers">${q.answers.map((a,i)=>`<button class="answer ${completed?(i===q.correct?'correct':i===selected?'wrong':''):selected===i?'picked':''}" data-guided-answer="${i}" ${completed?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(a)}</span></button>`).join('')}</div>${completed?`<div class="feedback trainer-feedback"><strong>${h.correct?'Risposta ESATTA!':`Risposta SBAGLIATA! La risposta corretta era la ${String.fromCharCode(65+q.correct)}.`}</strong>${explanationMarkup(q.explanation)}</div>`:''}<div class="quiz-actions nav-actions">${quiz.mode==='guided-exam'&&!last?'<button class="ghost danger-text" data-finish-now>Termina prova</button>':''}${quiz.index>0?'<button class="ghost" data-guided-prev>← Indietro</button>':''}${!completed?`<button class="ghost" data-guided-skip>${last&&quiz.mode==='guided-exam'?'Consegna senza risposta':'Tralascia domanda'}</button>`:''}${!completed&&quiz.mode==='guided-exam'&&selected!==null?'<button class="primary" data-guided-confirm>Continua →</button>':''}${completed?`<button class="primary" data-guided-next>${last&&quiz.mode==='guided-exam'?'Consegna prova':last?'Termina':'Continua →'}</button>`:''}</div>`;app.querySelectorAll('[data-guided-answer]').forEach(b=>b.onclick=()=>guidedAnswer(+b.dataset.guidedAnswer));app.querySelector('[data-finish-now]')?.addEventListener('click',finishCurrentQuiz);app.querySelector('[data-guided-prev]')?.addEventListener('click',guidedPrevious);app.querySelector('[data-guided-skip]')?.addEventListener('click',guidedSkip);app.querySelector('[data-guided-confirm]')?.addEventListener('click',guidedConfirmAnswer);app.querySelector('[data-guided-next]')?.addEventListener('click',guidedNext);bindQuestionOverview()}
function guidedAnswer(choice){const q=quiz.pool[quiz.index],ok=choice===q.correct;if(isTimedFortyQuiz()){quiz.selected=choice;setGuidedPendingAnswer(quiz,quiz.index,choice);saveActiveQuiz()}else{quiz.history[q.id]={choice,blank:false,correct:ok,q};userState().progress[q.id]=applyLearningOutcome(progressFor(q.id),{correct:ok});persist()}renderGuided()}
function guidedConfirmAnswer(){const q=quiz.pool[quiz.index],choice=quiz.selected;if(choice===null)return;quiz.history[q.id]={choice,blank:false,correct:choice===q.correct,q};if(quiz.mode==='guided-exam')setGuidedPendingAnswer(quiz,quiz.index,null);quiz.selected=null;saveActiveQuiz();renderGuided()}
function guidedSkip(){const q=quiz.pool[quiz.index],alreadyBlank=quiz.history[q.id]?.blank;quiz.selected=null;if(quiz.mode==='guided-exam')setGuidedPendingAnswer(quiz,quiz.index,null);quiz.history[q.id]={choice:null,blank:true,correct:false,q};if(isTimedFortyQuiz())saveActiveQuiz();else{const p=progressFor(q.id);if(!alreadyBlank)p.skipped++;if(!p.attempts)p.status='unanswered';p.lastAt=new Date().toISOString();userState().progress[q.id]=p;persist()}guidedNext()}
function guidedPrevious(){if(quiz.index>0){let previousSelection=null;if(quiz.mode==='guided-exam'){setGuidedPendingAnswer(quiz,quiz.index,quiz.selected);previousSelection=guidedPendingAnswerAt(quiz,quiz.index-1)}quiz.index--;quiz.selected=quiz.mode==='guided-exam'?previousSelection:null;saveActiveQuiz();renderGuided()}}
function guidedNext(){if(quiz.mode==='guided-exam')setGuidedPendingAnswer(quiz,quiz.index,quiz.selected);quiz.selected=null;if(quiz.index===quiz.pool.length-1){if(quiz.mode==='guided-exam'){saveActiveQuiz();requestDeliveryConfirmation(finishGuided);return}return finishGuided()}quiz.index++;if(quiz.mode==='guided-exam')quiz.selected=guidedPendingAnswerAt(quiz,quiz.index);saveActiveQuiz();renderGuided()}
function finishGuided(){if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.mode==='guided-exam'?guidedResultRows(quiz):quiz.pool.map(q=>quiz.history[q.id]||{choice:null,blank:true,correct:false,q}),correct=rows.filter(x=>x.correct).length,wrong=rows.filter(x=>!x.correct&&!x.blank).length,blank=rows.filter(x=>x.blank).length,score=scoreFor(correct,wrong);userState().sessions.push({type:'guided',at:new Date().toISOString(),correct,wrong,blank,score});persist();app.innerHTML=resultCard('Prova guidata completata',correct,wrong,blank,'<a class="button primary" href="#simulation">Nuova prova</a><a class="button ghost" href="#stats">Statistiche</a>')+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})}
const subjectCursorKey=(cat,status)=>`filtered:${cat}:${status}`;
function subjectFilterCursor(cat,status,bank){const st=userState(),key=subjectCursorKey(cat,status),saved=st.categoryCursor[key];if(saved?.version===2)return{key,cursor:saved};let latestAt='',position=-1,lastId=null;bank.forEach((q,index)=>{const p=progressFor(q.id),at=String(p.lastAt||'');if(p.status===status&&at>latestAt){latestAt=at;position=index;lastId=String(q.id)}});const cursor={version:2,lastId,position,size:bank.length,updatedAt:latestAt||new Date().toISOString()};st.categoryCursor[key]=cursor;return{key,cursor}}
function rememberSubjectCursor(q){if(!quiz?.subjectCursorKey)return;const bank=allQuestions().filter(item=>!quiz.sourceCategory||macroCategoryId(item.category)===quiz.sourceCategory),position=bank.findIndex(item=>String(item.id)===String(q.id));if(position<0)return;userState().categoryCursor[quiz.subjectCursorKey]={version:2,lastId:String(q.id),position,size:bank.length,updatedAt:new Date().toISOString()}}
function startFiltered(cat,status){const sourceCategory=cat==='all'?null:cat,bank=allQuestions().filter(q=>!sourceCategory||macroCategoryId(q.category)===sourceCategory),{key,cursor}=subjectFilterCursor(cat,status,bank),pool=selectOrderedQuestions(bank,cursor,q=>progressFor(q.id).status===status);if(!pool.length)return notify('Nessuna domanda in questo gruppo');quiz={kind:'study',pool,index:0,history:{},selected:null,filter:status,sourceCategory,subjectCursorKey:key};persist();renderQuestion()}
function reviewView(status){nav('stats');startFiltered('all',status)}
function targetedView(param){nav('stats');const [category,status]=String(param||'').split(':');if(!categories.some(item=>item.id===category)||!['known','review','unknown','unanswered'].includes(status))return statsView();startFiltered(category,status)}

function renderQuestion(){const q=quiz.pool[quiz.index],p=progressFor(q.id),selected=quiz.selected,isStudy=quiz.kind==='study',last=quiz.index===quiz.pool.length-1;app.innerHTML=`${!isStudy?timerMarkup()+questionOverviewMarkup():''}<div class="quiz-head"><div><span class="meta">${isStudy?'Studio ordinato':'Simulazione a tempo'}</span><br><strong>${catName(q.category)}</strong></div><strong>${quiz.index+1}/${quiz.pool.length}</strong></div><div class="progress"><span style="width:${(quiz.index+1)/quiz.pool.length*100}%"></span></div><h1 class="question">${esc(q.text)}</h1>${q.image?`<img class="question-image" src="${esc(q.image)}" alt="Diagramma del quesito">`:''}<div class="answers">${q.answers.map((a,i)=>`<button class="answer ${selected!==null&&isStudy?(i===q.correct?'correct':i===selected?'wrong':''):selected===i?'picked':''}" data-answer="${i}" ${selected!==null&&isStudy?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(a)}</span></button>`).join('')}</div>${selected!==null&&isStudy?`<div class="feedback"><strong>${selected===q.correct?'Risposta corretta':'Risposta errata · aggiunta a Da ripetere'}</strong>${explanationMarkup(q.explanation)}<p>Come la consideri?</p><div class="mastery"><button class="status-chip known" data-status="known">La so</button><button class="status-chip review" data-status="review">Da ripetere</button><button class="status-chip unknown" data-status="unknown">Non la so</button></div></div>`:''}<div class="quiz-actions nav-actions">${!isStudy&&!last?'<button class="ghost danger-text" data-finish-now>Termina prova</button>':''}${quiz.index>0?'<button class="ghost" data-prev>← Indietro</button>':''}<button class="ghost" data-skip>${isStudy?'Segna non risposta':'Lascia in bianco'}</button>${selected!==null&&isStudy?'<button class="primary" data-next>Prossima →</button>':''}${!isStudy?`<button class="primary" data-exam-next>${last?'Consegna prova':'Conferma e avanti →'}</button>`:''}</div><div class="question-state">Stato attuale: <b>${statusLabel(p.status)}</b></div>`;app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>selectAnswer(+b.dataset.answer));app.querySelector('[data-finish-now]')?.addEventListener('click',finishCurrentQuiz);app.querySelector('[data-prev]')?.addEventListener('click',previous);app.querySelector('[data-skip]').onclick=skip;app.querySelector('[data-next]')?.addEventListener('click',next);app.querySelector('[data-exam-next]')?.addEventListener('click',examNext);app.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>markStatus(b.dataset.status));bindQuestionOverview()}
function selectAnswer(choice){if(quiz.kind==='study'){quiz.selected=choice;recordStudy(choice);renderQuestion()}else{quiz.selected=choice;app.querySelectorAll('.answer').forEach((b,i)=>b.classList.toggle('picked',i===choice));refreshQuestionOverview();saveActiveQuiz()}}
function recordStudy(choice){const q=quiz.pool[quiz.index],p=progressFor(q.id),ok=choice===q.correct,firstAttempt=!quiz.history[q.id];userState().progress[q.id]=applyLearningOutcome(p,{correct:ok},firstAttempt);quiz.history[q.id]={choice,blank:false,correct:ok,q};rememberSubjectCursor(q);persist()}
function markStatus(status){const q=quiz.pool[quiz.index],p=progressFor(q.id);p.status=status;userState().progress[q.id]=p;rememberSubjectCursor(q);persist();notify(`Segnata: ${statusLabel(status)}`);next()}
function skip(){const q=quiz.pool[quiz.index];if(quiz.kind==='study'){const p=progressFor(q.id);if(!quiz.history[q.id])p.skipped++;p.status='unanswered';p.lastAt=new Date().toISOString();userState().progress[q.id]=p;quiz.history[q.id]={choice:null,blank:true,correct:false,q};rememberSubjectCursor(q);persist();next()}else{quiz.selected=null;examNext()}}
function previous(){if(quiz.index<=0)return;if(quiz.kind==='exam')quiz.answers[quiz.index]=quiz.selected;quiz.index--;const q=quiz.pool[quiz.index];quiz.selected=quiz.kind==='exam'?quiz.answers[quiz.index]:(quiz.history[q.id]?.choice??null);saveActiveQuiz();renderQuestion()}
function next(){quiz.index++;quiz.selected=null;if(quiz.index>=quiz.pool.length)return finishStudy();const q=quiz.pool[quiz.index];quiz.selected=quiz.history[q.id]?.choice??null;renderQuestion()}
function finishStudy(){if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.pool.map(q=>quiz.history[q.id]||{choice:null,blank:true,correct:false,q}),correct=rows.filter(x=>x.correct).length,wrong=rows.filter(x=>!x.correct&&!x.blank).length,blank=rows.filter(x=>x.blank).length,score=scoreFor(correct,wrong);userState().sessions.push({type:'study',at:new Date().toISOString(),correct,wrong,blank,score});persist();app.innerHTML=resultCard('Quiz completato',correct,wrong,blank,'<a class="button primary" href="#categories">Materie</a><a class="button ghost" href="#stats">Progressi</a>')+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})}
const statusLabel=s=>({known:'La so',review:'Da ripetere',unknown:'Non la so',unanswered:'Non risposta'}[s]||'Non risposta');

function simulationView(){nav('simulation');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Prove da 40 domande</div><h1>Scegli la modalità</h1></div></div><div class="card"><h2>Simulazione a tempo</h2><p>40 domande in 40 minuti. Nessuna correzione durante la prova.</p><div class="exam-rule"><strong>+1</strong><span>Corretta</span></div><div class="exam-rule"><strong>−0,33</strong><span>Errata</span></div><div class="exam-rule"><strong>0</strong><span>Non data</span></div><button class="primary exam-start" data-start-exam>Avvia simulazione 40/40</button></div><div class="card composition guided-exam-card"><h2>Prova guidata con spiegazioni</h2><p>Stesse 40 domande e stessa composizione, ma dopo ogni risposta vedi subito esito, soluzione corretta e spiegazione.</p><button class="secondary" data-start-guided-exam>Avvia prova guidata da 40</button></div><div class="card composition"><h2>Composizione identica per entrambe</h2><p><b>8</b> Storia · <b>11</b> Logica · <b>1</b> Insiemi · <b>6</b> Fisica · <b>6</b> Chimica · <b>4</b> Informatica · <b>4</b> Inglese</p></div>`;app.querySelector('[data-start-exam]').onclick=startExam;app.querySelector('[data-start-guided-exam]').onclick=startGuidedExam}
function startGuidedExam(){const exposureBefore=fortyExposureSnapshot(),seed=createQuizSeed('guided-exam'),plan=examPlan(),deepLearning=deepLearningSettings().enabled,selected=plan.flatMap(([cat,count])=>takePersonalizedForty(allQuestions().filter(q=>q.category===cat),count,cat,seed,'guided')),pool=shuffleWithSeed(selected,`${seed}|questions`).map(q=>shuffleGuidedAnswers(q,`${seed}|answers|${q.id}`));userState().examCount++;persist();quiz={kind:'guided',mode:'guided-exam',deepLearning,pool,index:0,history:{},pendingAnswers:Array(pool.length).fill(null),selected:null,exposureBefore,remaining:EXAM_SECONDS,startedAt:Date.now(),generatedAt:new Date().toISOString()};saveActiveQuiz();renderGuided();startFortyMinuteTimer()}
function takeGuidedComposition(cat,count,seed){return takeRotating(guidedCompositionSource(cat,count),count,'guided-exam',cat,seed)}
function startExam(){const exposureBefore=fortyExposureSnapshot(),seed=createQuizSeed('exam'),plan=examPlan(),deepLearning=deepLearningSettings().enabled,selected=plan.flatMap(([cat,count])=>takePersonalizedForty(allQuestions().filter(q=>q.category===cat),count,cat,seed,'official')),pool=shuffleWithSeed(selected,`${seed}|questions`);userState().examCount++;persist();quiz={kind:'exam',deepLearning,pool,index:0,answers:Array(pool.length).fill(null),selected:null,exposureBefore,remaining:EXAM_SECONDS,startedAt:Date.now(),generatedAt:new Date().toISOString()};saveActiveQuiz();renderQuestion();startFortyMinuteTimer()}
function examNext(){quiz.answers[quiz.index]=quiz.selected;if(quiz.index===quiz.pool.length-1){saveActiveQuiz();requestDeliveryConfirmation(finishExam);return}quiz.index++;quiz.selected=null;saveActiveQuiz();renderQuestion()}
function finishExam(){clearInterval(timerHandle);if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.pool.map((q,i)=>({id:q.id,category:q.category,q,choice:quiz.answers[i],correct:quiz.answers[i]===q.correct,blank:quiz.answers[i]===null}));let correct=0,wrong=0,blank=0;for(const r of rows){const p=progressFor(r.id);if(r.blank){blank++;p.skipped++;if(!p.attempts)p.status='unanswered'}else{p.attempts++;if(r.correct){correct++;p.correct++;p.status=p.correct>=2&&p.wrong===0?'known':'review'}else{wrong++;p.wrong++;p.status='review'}}p.lastAt=new Date().toISOString();userState().progress[r.id]=p}const score=Math.round((correct-wrong*.33)*100)/100;userState().sessions.push({type:'exam',at:new Date().toISOString(),correct,wrong,blank,score});persist();app.innerHTML=`<div class="result-card card"><div class="eyebrow">Simulazione completata</div><h1>${score.toLocaleString('it')} punti</h1><div class="stat-row"><div class="stat"><strong>${correct}</strong><span>Corrette</span></div><div class="stat"><strong>${wrong}</strong><span>Errate</span></div><div class="stat"><strong>${blank}</strong><span>Non date</span></div></div><p class="meta">Calcolo: ${correct} − (${wrong} × 0,33) = ${score.toLocaleString('it')}</p><div class="quiz-actions"><a class="button primary" href="#simulation">Nuova prova</a><a class="button ghost" href="#stats">Statistiche</a></div></div>${reviewReport(rows)}`}
function reviewReport(rows){if(!rows.length)return'';const group=(type,label)=>{const list=rows.filter(r=>type==='correct'?r.correct:type==='wrong'?!r.correct&&!r.blank:r.blank);return `<section class="review-group"><div class="section-head"><h2>${label}</h2><span class="review-count">${list.length}</span></div>${list.length?list.map(r=>{const q=r.q,chosen=r.blank?'Non data':q.answers[r.choice],right=q.answers[q.correct];return `<details class="card review-item" ${type==='wrong'?'open':''}><summary><span class="review-badge ${type}">${type==='correct'?'✓':type==='wrong'?'✕':'—'}</span><span>${esc(q.text)}</span></summary>${q.image?`<img class="question-image mini" src="${esc(q.image)}" alt="Diagramma del quesito">`:''}<div class="review-answer"><span>La tua risposta</span><b>${esc(chosen)}</b></div><div class="review-answer correct-text"><span>Risposta corretta</span><b>${esc(right)}</b></div>${explanationMarkup(q.explanation)}</details>`}).join(''):'<div class="card meta">Nessuna domanda.</div>'}</section>`};return `<div class="review-report"><div class="section-head"><div><div class="eyebrow">Correzione completa</div><h1>Rivedi tutte le risposte</h1></div></div>${group('wrong','Risposte errate')}${group('blank','Non risposte')}${group('correct','Risposte corrette')}</div>`}
const formatTime=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;

function statsView(){nav('stats');const metrics=categoryMetrics(),officialStats=sessionSummary(['exam','daily-challenge']),guidedStats=sessionSummary(['guided','guided-exam']),subjectStats=sessionSummary(['study','guided','tutor']),sessions=userState().sessions;app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Profilo personale</div><h1>Progressi e risultati</h1></div></div>${pieChartMarkup(metrics,'Preparazione complessiva')}${targetedRecommendationsMarkup(3)}<div class="section-head"><h2>Risultati dei quiz</h2></div><div class="quiz-result-summary"><div class="card"><span>Simulazioni e sfide</span><strong>${officialStats.count}</strong><small>${officialStats.averageAccuracy===null?'Nessun risultato':`Precisione media ${officialStats.averageAccuracy}% · migliore ${officialStats.bestScore?.toLocaleString('it')??'—'} pt`}</small></div><div class="card"><span>Quiz guidati</span><strong>${guidedStats.count}</strong><small>${guidedStats.averageAccuracy===null?'Nessun risultato':`Precisione media ${guidedStats.averageAccuracy}%`}</small></div><div class="card"><span>Quiz per materia e Tutor</span><strong>${subjectStats.count}</strong><small>${subjectStats.averageAccuracy===null?'Nessun risultato':`Precisione media ${subjectStats.averageAccuracy}%`}</small></div></div><div class="section-head"><h2>Andamento per materia</h2></div><div class="subject-stat-list">${categories.map(c=>{const m=categoryMetrics(c.id);return `<a class="card subject-stat" href="#category/${c.id}"><div><b>${esc(c.name)}</b><span>${m.accuracy===null?'Precisione da calcolare':`${m.accuracy}% precisione`} · ${coverageLabel(m)} classificato</span></div><div class="subject-mini-stats"><span class="known">${m.known} so</span><span class="review">${m.review} ripeti</span><span class="unknown">${m.unknown} non so</span><span class="unanswered">${m.toDo} da fare</span></div><div class="progress"><span style="width:${m.coverage}%"></span></div></a>`}).join('')}</div><div class="section-head"><h2>Cronologia di tutti i quiz</h2></div>${sessionHistoryMarkup(sessions)}`}

function adminView(){if(currentUser.role!=='admin')return home();nav('admin');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Solo amministratori</div><h1>Gestione utenti</h1></div></div><form class="card admin-form" id="newUser"><h2>Crea utente</h2><label>Nome visualizzato<input name="name" required></label><label>Nome utente<input name="username" required></label><label>Password temporanea<input name="password" type="password" minlength="6" required></label><label>Ruolo<select name="role"><option value="user">Utente</option><option value="admin">Amministratore</option></select></label><button class="primary">Crea account</button></form><div class="section-head"><h2>Utenti (${users.length})</h2></div><div class="user-list">${users.map(u=>`<div class="card user-row"><div><b>${esc(u.name)}</b><span>@${esc(u.username)} · ${u.role}</span></div><button class="ghost compact" data-toggle="${u.id}" ${u.id===currentUser.id?'disabled':''}>${u.active?'Disattiva':'Riattiva'}</button></div>`).join('')}</div>`;app.querySelector('#newUser').onsubmit=createUser;app.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const u=users.find(x=>x.id===b.dataset.toggle);u.active=!u.active;saveUsers();adminView()})}
async function createUser(e){e.preventDefault();const f=new FormData(e.currentTarget),username=String(f.get('username')).trim().toLowerCase();if(cloudMode){try{await cloudApi('./api/admin/users',{method:'POST',body:JSON.stringify({username,name:String(f.get('name')).trim(),email:String(f.get('email')||'').trim()||null,password:String(f.get('password')),role:String(f.get('role'))})});notify('Utente creato');usersView()}catch(error){notify(error.message)}return}if(users.some(u=>u.username===username))return notify('Nome utente già esistente');users.push({id:crypto.randomUUID(),username,name:String(f.get('name')).trim(),role:String(f.get('role')),passwordHash:await hash(String(f.get('password'))),createdAt:new Date().toISOString(),active:true,state:{progress:{},sessions:[],categoryCursor:{},examCursor:{},examCount:0}});saveUsers();notify('Utente creato');usersView()}

function dataView(){nav('data');if(cloudMode){app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Dataset centralizzato</div><h1>Banca dati</h1></div></div><div class="card data-box"><p><b>${official.length.toLocaleString('it')} quesiti ufficiali</b> disponibili sul server.</p><p class="meta">Nella versione cloud la banca dati è uguale per tutti e viene aggiornata insieme all'applicazione dal server Linux.</p></div>`;return}app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Dataset locale</div><h1>Gestione dati</h1></div></div><div class="card data-box"><p><b>${official.length.toLocaleString('it')} quesiti ufficiali</b> caricati.</p><p class="meta">È possibile aggiungere un file JSON autorizzato con id, category, text, answers e correct.</p><input type="file" id="file" accept="application/json,.json"><button class="primary" data-import>Importa dataset</button><button class="ghost" data-clear>Rimuovi aggiunte (${imported.length})</button></div>`;app.querySelector('[data-import]').onclick=importFile;app.querySelector('[data-clear]').onclick=()=>{imported=[];localStorage.removeItem(DATA);notify('Aggiunte rimosse');dataView()}}
async function importFile(){const file=app.querySelector('#file').files[0];if(!file)return notify('Scegli un file JSON');try{const rows=JSON.parse(await file.text());if(!Array.isArray(rows)||!rows.every(q=>q.id&&categories.some(c=>c.id===q.category)&&q.text&&Array.isArray(q.answers)&&Number.isInteger(q.correct)))throw Error();imported=rows;localStorage.setItem(DATA,JSON.stringify(rows));notify(`${rows.length} quesiti importati`);dataView()}catch{notify('File non valido')}}

function enhanceTrainerCard(){app.querySelector('.guided-card')?.remove()}
const setHeaderBase=setHeader;
