async function closePortableApp(){if(!confirm('Vuoi chiudere Quiz 400 VVF 2026?'))return;try{await portableSync();const response=await fetch('./api/shutdown',{method:'POST'});if(!response.ok)throw Error();clearInterval(timerHandle);app.innerHTML='<div class="card result-card"><h1>App chiusa</h1><p>I dati sono stati salvati. Ora puoi chiudere questa scheda.</p></div>';document.querySelector('.bottom-nav').classList.add('hidden');setTimeout(()=>window.close(),500)}catch{notify('Chiusura automatica disponibile nella versione portatile')}}
const loginViewBase=loginView;
loginView=function(){loginViewBase();const label=app.querySelector('.auth-copy .eyebrow');if(label)label.textContent='Quiz 400 VVF 2026'};
function planSummary(plan){return EXAM_ORDER.map(id=>[id,normalizePlan(plan)[id]]).filter(([,count])=>count>0).map(([id,count])=>`${count} ${catName(id)}`).join(' · ')}
function presetManagerMarkup(){const st=userState(),active=activeExamPreset(),plan=normalizePlan(active?.plan||examConfig.examPlan||DEFAULT_EXAM_PLAN);return `<section class="card preset-manager"><div class="preset-title"><div><div class="eyebrow">Preferenze del tuo account</div><h2>Configurazioni quiz salvate</h2></div><span class="preset-active-badge">${active?esc(active.name):'Predefinita'}</span></div><p class="meta">Salva più composizioni da 40 domande e richiamale con un tocco. Restano separate per ogni utente e vengono incluse nei backup.</p><form id="personalExamPreset" class="personal-preset-form"><input type="hidden" name="presetId" value="${active?esc(active.id):''}"><label class="preset-name-field">Nome configurazione<input name="presetName" maxlength="40" placeholder="Es. Prova ufficiale" value="${active?esc(active.name):''}" required></label><div class="preset-fields">${categories.map(c=>`<label>${esc(c.name)}<input type="number" min="0" max="40" step="1" name="${c.id}" value="${plan[c.id]||0}"></label>`).join('')}</div><div class="settings-total">Totale: <strong data-preset-total>${planTotal(plan)}</strong>/40</div><div class="quiz-actions"><button class="primary" type="submit">${active?'Aggiorna e usa':'Salva e usa'}</button><button class="ghost" type="button" data-new-preset>Nuova configurazione</button><button class="ghost" type="button" data-use-default ${active?'':'disabled'}>Usa predefinita</button></div></form>${st.examPresets.length?`<div class="saved-presets"><h3>Le tue configurazioni</h3>${st.examPresets.map(item=>`<div class="preset-row ${item.id===st.activeExamPresetId?'active':''}"><div><b>${esc(item.name)}</b><span>${esc(planSummary(item.plan))}</span></div><div class="preset-row-actions"><button class="ghost compact" data-use-preset="${item.id}" ${item.id===st.activeExamPresetId?'disabled':''}>${item.id===st.activeExamPresetId?'In uso':'Usa'}</button><button class="ghost compact danger-text" data-delete-preset="${item.id}">Elimina</button></div></div>`).join('')}</div>`:''}</section>`}
function bindPresetManager(){const form=app.querySelector('#personalExamPreset');if(!form)return;const total=()=>[...form.querySelectorAll('.preset-fields input')].reduce((sum,input)=>sum+(Number(input.value)||0),0),refreshTotal=()=>app.querySelector('[data-preset-total]').textContent=total();form.querySelectorAll('.preset-fields input').forEach(input=>input.addEventListener('input',refreshTotal));form.onsubmit=event=>{event.preventDefault();const data=new FormData(form),name=String(data.get('presetName')).trim(),id=String(data.get('presetId')||''),plan=normalizePlan(Object.fromEntries(categories.map(c=>[c.id,data.get(c.id)]))),st=userState();if(!name)return notify('Inserisci un nome per la configurazione');if(planTotal(plan)!==40)return notify(`Il totale deve essere 40: ora è ${planTotal(plan)}`);if(st.examPresets.some(item=>item.id!==id&&item.name.toLowerCase()===name.toLowerCase()))return notify('Esiste già una configurazione con questo nome');const existing=st.examPresets.find(item=>item.id===id);if(existing){existing.name=name;existing.plan=plan;existing.updatedAt=new Date().toISOString();st.activeExamPresetId=existing.id}else{const created={id:crypto.randomUUID(),name,plan,createdAt:new Date().toISOString()};st.examPresets.push(created);st.activeExamPresetId=created.id}saveUsers();notify('Configurazione salvata');simulationView()};app.querySelector('[data-new-preset]').onclick=()=>{form.elements.presetId.value='';form.elements.presetName.value='';form.querySelector('[type="submit"]').textContent='Salva e usa';form.elements.presetName.focus()};app.querySelector('[data-use-default]').onclick=()=>{userState().activeExamPresetId=null;saveUsers();notify('Configurazione predefinita attivata');simulationView()};app.querySelectorAll('[data-use-preset]').forEach(button=>button.onclick=()=>{userState().activeExamPresetId=button.dataset.usePreset;saveUsers();notify('Configurazione attivata');simulationView()});app.querySelectorAll('[data-delete-preset]').forEach(button=>button.onclick=()=>{const st=userState(),item=st.examPresets.find(entry=>entry.id===button.dataset.deletePreset);if(!item||!confirm(`Eliminare la configurazione “${item.name}”?`))return;st.examPresets=st.examPresets.filter(entry=>entry.id!==item.id);if(st.activeExamPresetId===item.id)st.activeExamPresetId=null;saveUsers();notify('Configurazione eliminata');simulationView()})}
function deepLearningProgressMarkup(summary,label){const percent=summary.total?Math.round(summary.mastered/summary.total*100):0;return `<div class="deep-learning-progress"><div><b>${esc(label)}</b><span>${summary.mastered.toLocaleString('it')} classificate “Le so” su ${summary.total.toLocaleString('it')} · ciclo ${summary.cycle}</span></div><div class="progress" aria-label="${percent}% completato"><span style="width:${percent}%"></span></div></div>`}
function deepLearningMarkup(){const settings=deepLearningSettings(),officialSummary=deepLearningTrackSummary('exam'),guidedSummary=deepLearningTrackSummary('guided-exam');return `<section class="card deep-learning-card ${settings.enabled?'active':''}"><div class="deep-learning-head"><div><div class="eyebrow">Ripasso adattivo personale</div><h2>Deep learning</h2></div><label class="switch-row"><input type="checkbox" data-deep-learning-toggle ${settings.enabled?'checked':''}><span class="switch-control" aria-hidden="true"></span><b>${settings.enabled?'Attivo':'Disattivato'}</b></label></div><p><strong>Quando è attivo, una domanda risposta correttamente non viene riproposta nelle prove successive finché non hai completato tutte le domande della stessa materia.</strong> Quelle errate o non risposte restano disponibili e hanno quindi più possibilità di tornare.</p><div class="deep-learning-note"><b>Come funziona</b><span>La simulazione resta sempre di 40 domande e rispetta la composizione scelta. Quando una materia completa il proprio ciclo, l'app la ricomincia automaticamente. Simulazione ufficiale e prova guidata hanno cicli separati.</span><span>Non invia dati a servizi di intelligenza artificiale: è un metodo di ripasso adattivo calcolato soltanto dalle tue risposte.</span></div><div class="deep-learning-stats">${deepLearningProgressMarkup(officialSummary,'Simulazione ufficiale')}${deepLearningProgressMarkup(guidedSummary,'Prova guidata')}</div><div class="quiz-actions"><button class="ghost danger-text" type="button" data-reset-deep-learning ${officialSummary.mastered||guidedSummary.mastered?'':'disabled'}>Azzera solo i cicli</button></div></section>`}
function bindDeepLearningControls(){const toggle=app.querySelector('[data-deep-learning-toggle]'),reset=app.querySelector('[data-reset-deep-learning]');if(toggle)toggle.onchange=()=>{const settings=deepLearningSettings();settings.enabled=toggle.checked;saveUsers();notify(toggle.checked?'Deep learning attivato':'Deep learning disattivato');simulationView()};if(reset)reset.onclick=()=>{if(!confirm('Azzerare i cicli Deep learning? Le statistiche generali e le risposte svolte non verranno eliminate.'))return;deepLearningSettings().tracks={};saveUsers();notify('Cicli Deep learning azzerati');simulationView()}}
function deepLearningResultMarkup(rows,track){if(!quiz?.deepLearning)return'';const correct=rows.filter(row=>row.correct).length,remaining=rows.length-correct,summary=deepLearningTrackSummary(track);return `<aside class="card deep-learning-result"><div class="eyebrow">Ripasso adattivo aggiornato</div><h2>${correct} ${correct===1?'risposta corretta':'risposte corrette'}: ora “Le so”</h2><p>${remaining?`${remaining} ${remaining===1?'domanda resta':'domande restano'} tra “Da ripetere” o “Da fare”. Non torneranno subito se nella stessa materia ci sono ancora altre domande deboli da allenare.`:'Tutte le risposte di questa prova sono ora classificate “Le so”.'}</p>${deepLearningProgressMarkup(summary,'Percorso personale condiviso')}</aside>`}
deepLearningMarkup=function(){const settings=deepLearningSettings(),officialSummary=deepLearningTrackSummary('exam'),guidedSummary=deepLearningTrackSummary('guided-exam'),hasCycles=Object.keys(userState().fortyQuestionExposure||{}).length>0;return `<section class="card deep-learning-card ${settings.enabled?'active':''}"><div class="deep-learning-head"><div><div class="eyebrow">Ripasso adattivo personale</div><h2>Deep learning</h2></div><button class="switch-row" type="button" data-deep-learning-toggle aria-pressed="${settings.enabled}"><span class="switch-control" aria-hidden="true"></span><b>${settings.enabled?'Attivo':'Disattivato'}</b></button></div><p><strong>L'anti-ripetizione e la precedenza alle domande non note o mai fatte sono sempre attivi nelle due prove da 40.</strong> Attivando Deep learning la priorità diventa rigorosa: “Non le so”, “Da ripetere”, “Da fare” e infine “Le so”.</p><div class="deep-learning-note"><b>Usa tutto il tuo percorso di studio</b><span>Le classificazioni ottenute nei quiz per materia, nella simulazione ufficiale e nella prova guidata sono condivise. Per esempio, se in Storia ne sai già 900, il test privilegia le altre.</span><span>Simulazione e prova guidata condividono anche la memoria dei quesiti già mostrati: una domanda non rientra solo perché, dopo una risposta corretta, è passata a “Le so”.</span><span>La prova guidata usa ora l'intera banca dati; quando una spiegazione originale non è disponibile, viene indicato chiaramente senza inventarne una. La prova resta di 40 domande e rispetta la composizione scelta.</span></div><div class="deep-learning-stats">${deepLearningProgressMarkup(officialSummary,'Percorso condiviso · simulazione')}${deepLearningProgressMarkup(guidedSummary,'Percorso condiviso · prova guidata')}</div><div class="quiz-actions"><button class="ghost danger-text" type="button" data-reset-deep-learning ${hasCycles?'':'disabled'}>Azzera rotazione prove da 40</button></div></section>`};
bindDeepLearningControls=function(){const toggle=app.querySelector('[data-deep-learning-toggle]'),reset=app.querySelector('[data-reset-deep-learning]');if(toggle)toggle.onclick=()=>{const settings=deepLearningSettings();settings.enabled=!settings.enabled;saveUsers();notify(settings.enabled?'Deep learning attivato':'Deep learning disattivato');simulationView()};if(reset)reset.onclick=()=>{if(!confirm('Azzerare la rotazione delle prove da 40? Le statistiche e le classificazioni “Le so / Da ripetere / Non le so” resteranno intatte.'))return;const st=userState();st.fortyQuestionExposure={};deepLearningSettings().tracks={};for(const key of Object.keys(st.quizRotation))if(key.startsWith('adaptive-known:'))delete st.quizRotation[key];saveUsers();notify('Rotazione delle prove da 40 azzerata');simulationView()}};
const simulationViewBase=simulationView;
simulationView=function(){nav('simulation');if(resumeActiveQuiz())return;const composition=examPlan().map(([id,n])=>`<b>${n}</b> ${esc(catName(id))}`).join(' · '),active=activeExamPreset();app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Prove da 40 domande</div><h1>Scegli la modalità</h1></div></div><div class="card rotation-card"><h2>Estrazione sempre nuova</h2><p>Ogni prova usa data e ora correnti per mescolare le 40 domande. La rotazione viene salvata: anche dopo aver chiuso e riaperto l’app non riparte dallo stesso quiz e non ripete i quesiti già estratti finché la materia non completa il proprio ciclo.</p></div>${presetManagerMarkup()}<div class="card"><h2>Simulazione a tempo</h2><p>40 domande in 40 minuti, con cronometro sempre visibile, panoramica delle domande e consegna automatica allo scadere. Nessuna correzione durante la prova.</p><div class="exam-rule"><strong>+1</strong><span>Corretta</span></div><div class="exam-rule"><strong>−0,33</strong><span>Errata</span></div><div class="exam-rule"><strong>0</strong><span>Non data</span></div><button class="primary exam-start" data-start-exam>Avvia simulazione 40/40</button></div><div class="card composition guided-exam-card"><h2>Prova guidata con spiegazioni</h2><p>Stesse 40 domande, stesso cronometro e panoramica, con esito, soluzione e spiegazione immediati.</p><button class="secondary" data-start-guided-exam>Avvia prova guidata da 40</button></div><div class="card composition"><h2>Composizione attuale · ${active?esc(active.name):'Predefinita'}</h2><p>${composition}</p>${currentUser.role==='admin'?'<a class="button ghost" href="#settings">Modifica impostazione predefinita</a>':''}</div>`;bindPresetManager();app.querySelector('[data-start-exam]').onclick=startExam;app.querySelector('[data-start-guided-exam]').onclick=startGuidedExam};
function settingsView(){if(currentUser.role!=='admin')return home();nav('settings');const total=planTotal(examConfig.examPlan);app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Solo amministratori</div><h1>Impostazioni</h1></div></div><form class="card admin-form" id="examSettings"><h2>Composizione predefinita delle 40 domande</h2><p class="meta">Questa configurazione si applica agli utenti che non hanno selezionato una preferenza personale. Imposta 0 per togliere una materia; la somma deve essere esattamente 40.</p>${categories.map(c=>`<label>${esc(c.name)}<input type="number" min="0" max="40" step="1" name="${c.id}" value="${Number(examConfig.examPlan?.[c.id])||0}"></label>`).join('')}<div class="settings-total">Totale attuale: <strong data-settings-total>${total}</strong>/40</div><div class="quiz-actions"><button class="primary" type="submit">Salva composizione predefinita</button><button class="ghost" type="button" data-reset-plan>Ripristina predefinita</button></div></form>`;const form=app.querySelector('#examSettings'),update=()=>app.querySelector('[data-settings-total]').textContent=[...form.querySelectorAll('input')].reduce((s,x)=>s+(Number(x.value)||0),0);form.querySelectorAll('input').forEach(x=>x.addEventListener('input',update));form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(categories.map(c=>[c.id,Math.max(0,Math.floor(Number(new FormData(form).get(c.id))||0))])),sum=Object.values(values).reduce((a,b)=>a+b,0);if(sum!==40)return notify(`Il totale deve essere 40: ora è ${sum}`);examConfig={...examConfig,examPlan:values};localStorage.setItem(CONFIG,JSON.stringify(examConfig));portableSync();notify('Composizione predefinita salvata');routeTo('simulation')};app.querySelector('[data-reset-plan]').onclick=()=>{examConfig={...examConfig,examPlan:{...DEFAULT_EXAM_PLAN}};localStorage.setItem(CONFIG,JSON.stringify(examConfig));portableSync();settingsView()}};
simulationView=function(){nav('simulation');if(resumeActiveQuiz())return;const composition=examPlan().map(([id,n])=>`<b>${n}</b> ${esc(catName(id))}`).join(' · '),active=activeExamPreset(),deepLearning=deepLearningSettings().enabled,deepBadge=deepLearning?'<span class="mode-deep-badge">Deep learning attivo</span>':'';app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Prove da 40 domande</div><h1>Scegli la modalità</h1></div></div><div class="card rotation-card"><h2>Estrazione sempre nuova</h2><p>Ogni prova usa data e ora correnti per mescolare le 40 domande. La rotazione viene salvata: anche dopo aver chiuso e riaperto l’app non riparte dallo stesso quiz.</p></div>${deepLearningMarkup()}${presetManagerMarkup()}<div class="simulation-mode-grid"><div class="card simulation-mode-card"><div class="mode-card-title"><h2>Simulazione a tempo</h2>${deepBadge}</div><p>40 domande in 40 minuti, con cronometro sempre visibile, panoramica delle domande e consegna automatica allo scadere. Nessuna correzione durante la prova.</p><div class="exam-rule"><strong>+1</strong><span>Corretta</span></div><div class="exam-rule"><strong>−0,33</strong><span>Errata</span></div><div class="exam-rule"><strong>0</strong><span>Non data</span></div><button class="primary exam-start" data-start-exam>Avvia simulazione 40/40</button></div><div class="card simulation-mode-card guided-exam-card"><div class="mode-card-title"><h2>Prova guidata con spiegazioni</h2>${deepBadge}</div><p>Stesse 40 domande, stesso cronometro e panoramica, con esito, soluzione e spiegazione immediati.</p><button class="secondary" data-start-guided-exam>Avvia prova guidata da 40</button></div></div><div class="card composition"><h2>Composizione attuale · ${active?esc(active.name):'Predefinita'}</h2><p>${composition}</p>${currentUser.role==='admin'?'<a class="button ghost" href="#settings">Modifica impostazione predefinita</a>':''}</div>`;bindDeepLearningControls();bindPresetManager();app.querySelector('[data-start-exam]').onclick=startExam;app.querySelector('[data-start-guided-exam]').onclick=startGuidedExam};
const settingsViewBase=settingsView;
function userSettingsMarkup(){if(cloudMode)return cloudUserSettingsMarkup();return `<section class="settings-users"><div class="section-head"><div><div class="eyebrow">Percorsi personali separati</div><h1>Utenti e statistiche</h1></div><span class="review-count">${users.length}</span></div><div class="card user-privacy-note"><b>Ogni utente ha il proprio percorso</b><p class="meta">Domande svolte, classificazione “La so / Da ripetere / Non la so”, rotazione dei quiz, simulazioni e punteggi sono salvati separatamente per ogni account.</p></div><form class="card admin-form" id="settingsNewUser"><h2>Crea utente</h2><label>Nome visualizzato<input name="name" required></label><label>Nome utente<input name="username" required></label><label>Password temporanea<input name="password" type="password" minlength="6" required></label><label>Ruolo<select name="role"><option value="user">Utente</option><option value="admin">Amministratore</option></select></label><button class="primary">Crea account</button></form><div class="user-list settings-user-list">${users.map(u=>{const progress=Object.values(u.state?.progress||{}),answered=progress.filter(item=>item.attempts).length,known=progress.filter(item=>item.status==='known').length,exams=(u.state?.sessions||[]).filter(item=>item.type==='exam').length;return `<div class="card user-row settings-user-row"><div><b>${esc(u.name)} ${u.id===currentUser.id?'<small class="current-user-label">Account attuale</small>':''}</b><span>@${esc(u.username)} · ${u.role==='admin'?'Amministratore':'Utente'} · ${u.active?'Attivo':'Disattivato'}</span><span class="user-progress-line"><strong>${answered}</strong> svolte · <strong>${known}</strong> conosciute · <strong>${exams}</strong> simulazioni</span></div><button class="ghost compact" data-settings-toggle="${u.id}" ${u.id===currentUser.id?'disabled':''}>${u.active?'Disattiva':'Riattiva'}</button></div>`}).join('')}</div></section>`}
settingsView=function(){settingsViewBase();if(currentUser.role!=='admin')return;const backupDescription=cloudMode?'Esporta account, progressi, statistiche e impostazioni del portale in un unico file protetto.':'Esporta utenti, progressi, statistiche, impostazioni e dataset importati in un unico file.';app.querySelector('#examSettings')?.insertAdjacentHTML('afterend',`<div class="card backup-card"><h2>Backup e ripristino</h2><p class="meta">${backupDescription}</p><div class="quiz-actions"><button class="secondary" type="button" data-export-backup>Scarica backup</button><label class="button ghost backup-file">Ripristina backup<input type="file" accept="application/json,.json" data-restore-backup hidden></label></div></div>`);app.querySelector('[data-export-backup]')?.addEventListener('click',exportBackup);app.querySelector('[data-restore-backup]')?.addEventListener('change',restoreBackup)};

function usersView(){if(currentUser?.role!=='admin')return home();nav('users');app.innerHTML=userSettingsMarkup();app.querySelector('#settingsNewUser')?.addEventListener('submit',createUser);if(cloudMode){loadCloudAdminUsers();return}app.querySelectorAll('[data-settings-toggle]').forEach(button=>button.onclick=()=>{const user=users.find(item=>item.id===button.dataset.settingsToggle);if(!user)return;user.active=!user.active;saveUsers();usersView()})}
function exportBackup(){if(cloudMode){location.href='./api/admin/backup';notify('Preparazione backup cloud…');return}const payload={app:'Quiz 400 VVF 2026',version:1,createdAt:new Date().toISOString(),users,imported,config:examConfig},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`quiz-400-vvf-2026-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup creato')}
async function restoreBackup(e){const file=e.target.files?.[0];if(!file)return;if(cloudMode){if(!confirm('Il ripristino cloud sostituirà TUTTI gli utenti, progressi e impostazioni. Continuare?')){e.target.value='';return}if(prompt('Scrivi RIPRISTINA per confermare')!=='RIPRISTINA'){e.target.value='';return}try{await cloudApi('./api/admin/restore',{method:'POST',headers:{'X-Confirm-Restore':'RESTORE'},body:await file.text()});alert('Backup cloud ripristinato. Devi accedere nuovamente.');location.reload()}catch(error){e.target.value='';notify(error.message)}return}try{const backup=JSON.parse(await file.text()),plan=backup.config?.examPlan,total=plan&&Object.values(plan).reduce((s,n)=>s+(Number(n)||0),0);if(backup.app!=='Quiz 400 VVF 2026'||!Array.isArray(backup.users)||!Array.isArray(backup.imported)||!plan||total!==40)throw Error();if(!confirm('Il ripristino sostituirà utenti, progressi, statistiche e impostazioni attuali. Continuare?')){e.target.value='';return}users=backup.users;imported=backup.imported;examConfig=backup.config;localStorage.setItem(USERS,JSON.stringify(users));localStorage.setItem(DATA,JSON.stringify(imported));localStorage.setItem(CONFIG,JSON.stringify(examConfig));await portableSync();alert('Backup ripristinato correttamente. L’app verrà ricaricata.');location.reload()}catch{e.target.value='';notify('Backup non valido o danneggiato')}}
const adminViewBase=adminView;
adminView=function(){if(currentUser.role!=='admin')return home();routeTo('settings')};

const amateurDisclaimerMarkup=()=>`<aside class="amateur-disclaimer" role="note"><b>Piattaforma gratuita e non ufficiale</b><span>Progetto puramente amatoriale creato a fini di studio. Non rappresenta, non è affiliato e non è approvato dal Ministero dell’Interno, dal Corpo Nazionale dei Vigili del Fuoco o da altri enti del concorso.</span></aside>`;
function publicAuthShell(title,copy,form){nav('home');setHeader();document.querySelector('.bottom-nav').classList.add('hidden');app.innerHTML=`<section class="auth-shell"><div class="auth-copy"><img class="auth-logo" data-brand-logo src="${esc(runtimeConfig.logoUrl||'logo-vvf.jpg')}" alt="Logo del portale"><div class="eyebrow">${esc(runtimeConfig.siteName||'Quiz 400 VVF 2026')}</div><h1>${esc(title)}</h1><p>${esc(copy)}</p>${amateurDisclaimerMarkup()}</div>${form}</section>`}
function registerView(){if(!cloudMode||!runtimeConfig.registrationEnabled)return loginView();publicAuthShell('Crea il tuo account','Registrati per mantenere progressi e statistiche sincronizzati nel cloud.',`<form class="card auth-card" id="registerForm"><label>Nome visualizzato<input name="name" autocomplete="name" minlength="2" required></label><label>Nome utente<input name="username" autocomplete="username" minlength="3" pattern="[a-zA-Z0-9._-]+" required></label><label>Email per recupero password<input name="email" type="email" autocomplete="email" required></label><p class="meta">Serve per ricevere il link se dimentichi la password.</p><label>Password<input name="password" type="password" autocomplete="new-password" minlength="10" required></label><label>Ripeti password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="10" required></label><button class="primary">Registrati</button><a class="button ghost" href="#login">Hai già un account? Accedi</a><p class="meta">${esc(runtimeConfig.privacyNotice||'')}</p></form>`);app.querySelector('#registerForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);if(f.get('password')!==f.get('confirmPassword'))return notify('Le password non coincidono');try{const result=await cloudApi('./api/auth/register',{method:'POST',body:JSON.stringify({name:String(f.get('name')).trim(),username:String(f.get('username')).trim(),email:String(f.get('email')).trim(),password:String(f.get('password'))})});notify(result.message);location.hash='login'}catch(error){notify(error.message)}}}
function forgotPasswordView(){if(!cloudMode)return loginView();if(!runtimeConfig.emailResetEnabled){publicAuthShell('Password dimenticata','Il recupero tramite email non è ancora disponibile.',`<div class="card auth-card"><div class="smtp-status warning"><b>Email non configurata</b><span>Nessun messaggio può essere inviato finché l’amministratore non configura il server SMTP. Contatta l’amministratore per ricevere una password temporanea.</span></div><a class="button primary" href="#login">Torna all'accesso</a></div>`);return}publicAuthShell('Password dimenticata','Inserisci nome utente o email. La risposta non rivelerà se un account esiste.',`<form class="card auth-card" id="forgotForm"><label>Nome utente o email<input name="account" autocomplete="username" required></label><button class="primary">Invia istruzioni</button><a class="button ghost" href="#login">Torna all'accesso</a><p class="meta">Se l’account ha un indirizzo email associato riceverai un link temporaneo.</p></form>`);app.querySelector('#forgotForm').onsubmit=async event=>{event.preventDefault();try{const result=await cloudApi('./api/auth/forgot-password',{method:'POST',body:JSON.stringify({account:String(new FormData(event.currentTarget).get('account')).trim()})});app.querySelector('#forgotForm').innerHTML=`<h2>Richiesta ricevuta</h2><p>${esc(result.message)}</p><a class="button primary" href="#login">Torna all'accesso</a>`}catch(error){notify(error.message)}}}
function resetPasswordView(){if(!cloudMode)return loginView();const token=decodeURIComponent(location.hash.split('/')[1]||'');publicAuthShell('Scegli una nuova password','Il link di recupero può essere usato una sola volta.',`<form class="card auth-card" id="resetForm"><label>Nuova password<input name="password" type="password" autocomplete="new-password" minlength="10" required></label><label>Ripeti password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="10" required></label><button class="primary">Reimposta password</button><a class="button ghost" href="#login">Torna all'accesso</a></form>`);app.querySelector('#resetForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);if(!token)return notify('Link di recupero mancante');if(f.get('password')!==f.get('confirmPassword'))return notify('Le password non coincidono');try{await cloudApi('./api/auth/reset-password',{method:'POST',body:JSON.stringify({token,password:String(f.get('password'))})});history.replaceState({},'',location.pathname+'#login');notify('Password aggiornata. Ora puoi accedere');router()}catch(error){notify(error.message)}}}
function changePasswordView(){if(!cloudMode||!currentUser)return loginView();nav('home');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Sicurezza account</div><h1>${currentUser.mustChangePassword?'Cambia la password temporanea':'Cambia password'}</h1></div></div><form class="card auth-card cloud-narrow" id="changePasswordForm"><label>Password attuale<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>Nuova password<input name="newPassword" type="password" minlength="10" autocomplete="new-password" required></label><label>Ripeti nuova password<input name="confirmPassword" type="password" minlength="10" autocomplete="new-password" required></label><button class="primary">Salva nuova password</button>${currentUser.mustChangePassword?'':'<a class="button ghost" href="#account">Annulla</a>'}</form>`;app.querySelector('#changePasswordForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);if(f.get('newPassword')!==f.get('confirmPassword'))return notify('Le password non coincidono');try{await cloudApi('./api/auth/change-password',{method:'POST',body:JSON.stringify({current_password:String(f.get('currentPassword')),new_password:String(f.get('newPassword'))})});currentUser.mustChangePassword=false;const record=userRecord();if(record)record.mustChangePassword=false;notify('Password aggiornata');location.hash='home'}catch(error){notify(error.message)}}}
function profileAvatarUrl(user=currentUser){return user?.avatarUrl||`./api/users/${encodeURIComponent(user?.id||'')}/avatar`}

function profileAvatarMarkup(){return `<section class="profile-avatar-editor" aria-labelledby="profileAvatarTitle"><img data-profile-avatar src="${esc(profileAvatarUrl())}" alt="Foto profilo di ${esc(currentUser.name)}"><div><h2 id="profileAvatarTitle">Foto profilo</h2><p class="meta">Appare nella classifica della Sfida del giorno. L’immagine viene ottimizzata e ritagliata soltanto nella visualizzazione.</p><label class="button ghost compact profile-avatar-file">Scegli foto<input type="file" data-profile-avatar-file accept="image/jpeg,image/png,image/webp"></label><div class="quiz-actions"><button class="secondary compact" type="button" data-profile-avatar-save disabled>Salva foto</button><button class="ghost compact" type="button" data-profile-avatar-remove>Usa immagine predefinita</button></div><p class="meta" data-profile-avatar-status>JPEG, PNG o WebP; massimo 8 MB prima dell’ottimizzazione.</p></div></section>`}

function optimizedProfilePhoto(file){return new Promise((resolve,reject)=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type))return reject(Error('Scegli un’immagine JPEG, PNG o WebP.'));if(file.size>8*1024*1024)return reject(Error('La foto originale non può superare 8 MB.'));const reader=new FileReader();reader.onerror=()=>reject(Error('Non riesco a leggere questa immagine.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(Error('Il file selezionato non è un’immagine valida.'));image.onload=()=>{const scale=Math.min(1,900/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const context=canvas.getContext('2d');context.fillStyle='#d8d8d8';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);let dataUrl=canvas.toDataURL('image/jpeg',.88);if(dataUrl.length>1_400_000)dataUrl=canvas.toDataURL('image/jpeg',.72);if(dataUrl.length>1_400_000)return reject(Error('Non riesco a ridurre la foto sotto 1 MB. Scegli un’immagine più piccola.'));resolve(dataUrl)};image.src=String(reader.result)};reader.readAsDataURL(file)})}

function bindProfileAvatar(){const section=app.querySelector('.profile-avatar-editor');if(!section)return;const input=section.querySelector('[data-profile-avatar-file]'),preview=section.querySelector('[data-profile-avatar]'),save=section.querySelector('[data-profile-avatar-save]'),statusText=section.querySelector('[data-profile-avatar-status]');let selected=null;input.onchange=async()=>{selected=null;save.disabled=true;const file=input.files?.[0];if(!file)return;statusText.textContent='Ottimizzazione della foto…';try{selected=await optimizedProfilePhoto(file);preview.src=selected;save.disabled=false;statusText.textContent=`Pronta: ${file.name}` }catch(error){input.value='';preview.src=profileAvatarUrl();statusText.textContent=error.message}};save.onclick=async()=>{if(!selected)return;save.disabled=true;try{const result=await cloudApi('./api/auth/avatar',{method:'PUT',body:JSON.stringify({data_url:selected})});currentUser.avatarUrl=result.avatarUrl;preview.src=result.avatarUrl;selected=null;input.value='';statusText.textContent='Foto profilo salvata e visibile in classifica.';notify('Foto profilo aggiornata')}catch(error){save.disabled=false;statusText.textContent=error.message}};section.querySelector('[data-profile-avatar-remove]').onclick=async()=>{if(!confirm('Rimuovere la foto e usare l’immagine profilo predefinita?'))return;try{const result=await cloudApi('./api/auth/avatar',{method:'DELETE'});currentUser.avatarUrl=result.avatarUrl;preview.src=result.avatarUrl;selected=null;input.value='';save.disabled=true;statusText.textContent='Ora viene usata l’immagine profilo predefinita.';notify('Foto profilo rimossa')}catch(error){statusText.textContent=error.message}}}

function accountView(){if(!cloudMode||!currentUser)return home();nav('home');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Profilo personale</div><h1>Il tuo account</h1></div></div><form class="card auth-card cloud-narrow profile-account-card" id="profileForm">${profileAvatarMarkup()}<label>Nome visualizzato<input name="name" value="${esc(currentUser.name)}" minlength="2" required></label><label>Nome utente<input value="${esc(currentUser.username||'')}" disabled></label><label>Email per recupero password<input name="email" type="email" value="${esc(currentUser.email||'')}"></label><label>Tema dell’interfaccia<select name="theme"><option value="light" ${userState().theme==='light'?'selected':''}>Chiaro</option><option value="dark" ${userState().theme==='dark'?'selected':''}>Scuro</option><option value="system" ${userState().theme==='system'?'selected':''}>Come il dispositivo</option></select></label><p class="meta">Tema, configurazioni delle prove, rotazione delle domande, progressi e statistiche appartengono solo a questo account.</p><button class="primary">Salva profilo e preferenze</button><a class="button ghost" href="#change-password">Cambia password</a></form>`;bindProfileAvatar();app.querySelector('#profileForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);try{const result=await cloudApi('./api/auth/profile',{method:'PUT',body:JSON.stringify({name:String(f.get('name')).trim(),email:String(f.get('email')).trim()||null})});Object.assign(currentUser,result.user);Object.assign(userRecord(),result.user);userState().theme=String(f.get('theme'));applyTheme();await saveUsers();setHeader();notify('Profilo e tema aggiornati')}catch(error){notify(error.message)}}}

function cloudUserSettingsMarkup(){return `<section class="settings-users cloud-users"><div class="section-head"><div><div class="eyebrow">Controllo centralizzato</div><h1>Utenti e statistiche</h1></div><span class="review-count" data-cloud-user-count>…</span></div><div class="card user-privacy-note"><b>L'admin vede attività e risultati, non le password</b><p class="meta">Per ogni utente puoi consultare precisione, domande da ripetere, copertura per materia e risultati dei diversi tipi di quiz.</p></div><form class="card admin-form" id="settingsNewUser"><h2>Crea utente</h2><label>Nome visualizzato<input name="name" required></label><label>Nome utente<input name="username" required></label><label>Email<input name="email" type="email"></label><label>Password temporanea<input name="password" type="password" minlength="10" required></label><label>Ruolo<select name="role"><option value="user">Utente</option><option value="admin">Amministratore</option></select></label><button class="primary">Crea account</button></form><div class="cloud-totals" data-cloud-totals></div><div class="user-list settings-user-list" data-cloud-users><div class="card meta">Caricamento utenti…</div></div></section>`}
function cloudUserCard(user){const s=user.statistics||{};return `<article class="card cloud-user-card ${user.active?'':'inactive'}"><div class="cloud-user-head"><div><h3>${esc(user.name)} ${user.id===currentUser.id?'<small class="current-user-label">Account attuale</small>':''}</h3><p>@${esc(user.username)} · ${user.role==='admin'?'Amministratore':'Utente'} · ${user.active?'Attivo':'Disattivato'}</p><p class="meta">${user.email?`Email: ${esc(user.email)}`:'⚠ Email di recupero non impostata'} · Ultimo accesso: ${user.lastLoginAt?new Date(user.lastLoginAt).toLocaleString('it'):'mai'}</p></div><span class="cloud-user-role">${user.role==='admin'?'Admin':'Utente'}</span></div><div class="cloud-user-stats"><span><b>${s.answered||0}</b>Domande svolte</span><span><b>${s.fortyQuizzes||0}</b>Prove da 40</span><span><b>${fmtMetric(s.averageFortyScore)}</b>Media 40 /40</span><span><b>${s.subjectQuizzes||0}</b>Quiz argomenti</span><span><b>${s.averageSubjectAccuracy==null?'—':`${fmtMetric(s.averageSubjectAccuracy,1)}%`}</b>Media argomenti</span><span><b>${s.review||0}</b>Da ripetere</span></div><div class="cloud-user-actions"><button class="secondary compact" data-cloud-stats="${user.id}">Statistiche</button><button class="ghost compact" data-cloud-reset="${user.id}" ${user.id===currentUser.id?'disabled':''}>Reset password</button><button class="ghost compact" data-cloud-role="${user.id}" ${user.id===currentUser.id?'disabled':''}>${user.role==='admin'?'Rendi utente':'Rendi admin'}</button><button class="ghost compact" data-cloud-toggle="${user.id}" ${user.id===currentUser.id?'disabled':''}>${user.active?'Disattiva':'Riattiva'}</button><button class="ghost compact danger-text" data-cloud-delete="${user.id}" ${user.id===currentUser.id?'disabled':''}>Elimina</button></div></article>`}
async function loadCloudAdminUsers(){try{const result=await cloudApi('./api/admin/users');cloudAdminUsers=result.users;app.querySelector('[data-cloud-user-count]').textContent=result.totals.users;app.querySelector('[data-cloud-totals]').innerHTML=`<div class="cloud-admin-summary"><div class="card stat"><strong>${result.totals.users}</strong><span class="meta">Account</span></div><div class="card stat"><strong>${result.totals.active}</strong><span class="meta">Attivi</span></div><div class="card stat"><strong>${result.totals.fortyQuizzes||0}</strong><span class="meta">Prove da 40</span></div><div class="card stat"><strong>${fmtMetric(result.totals.averageFortyScore)}</strong><span class="meta">Media 40 /40</span></div><div class="card stat"><strong>${result.totals.subjectQuizzes||0}</strong><span class="meta">Quiz argomenti</span></div><div class="card stat"><strong>${result.totals.averageSubjectAccuracy==null?'—':`${fmtMetric(result.totals.averageSubjectAccuracy,1)}%`}</strong><span class="meta">Media argomenti</span></div></div>`;app.querySelector('[data-cloud-users]').innerHTML=result.users.map(cloudUserCard).join('')||'<div class="card meta">Nessun utente.</div>';bindCloudUserActions()}catch(error){app.querySelector('[data-cloud-users]').innerHTML=`<div class="notice">${esc(error.message)}</div>`}}
function bindCloudUserActions(){app.querySelectorAll('[data-cloud-stats]').forEach(button=>button.onclick=()=>showCloudStatistics(button.dataset.cloudStats));app.querySelectorAll('[data-cloud-toggle]').forEach(button=>button.onclick=async()=>{const user=cloudAdminUsers.find(item=>item.id===button.dataset.cloudToggle);if(!user)return;try{await cloudApi(`./api/admin/users/${user.id}`,{method:'PATCH',body:JSON.stringify({active:!user.active})});notify(user.active?'Utente disattivato':'Utente riattivato');loadCloudAdminUsers()}catch(error){notify(error.message)}});app.querySelectorAll('[data-cloud-role]').forEach(button=>button.onclick=async()=>{const user=cloudAdminUsers.find(item=>item.id===button.dataset.cloudRole);if(!user||!confirm(`${user.role==='admin'?'Rimuovere i permessi amministratore da':'Rendere amministratore'} ${user.name}?`))return;try{await cloudApi(`./api/admin/users/${user.id}`,{method:'PATCH',body:JSON.stringify({role:user.role==='admin'?'user':'admin'})});notify('Ruolo aggiornato');loadCloudAdminUsers()}catch(error){notify(error.message)}});app.querySelectorAll('[data-cloud-reset]').forEach(button=>button.onclick=async()=>{if(!confirm('Generare una nuova password temporanea e scollegare questo utente?'))return;try{const result=await cloudApi(`./api/admin/users/${button.dataset.cloudReset}/reset-password`,{method:'POST',body:'{}'});alert(`Password temporanea (visibile una sola volta):\n\n${result.temporaryPassword}\n\nComunicala all’utente in modo sicuro.`)}catch(error){notify(error.message)}});app.querySelectorAll('[data-cloud-delete]').forEach(button=>button.onclick=async()=>{const user=cloudAdminUsers.find(item=>item.id===button.dataset.cloudDelete);if(!user||!confirm(`Eliminare definitivamente ${user.name} e tutte le sue statistiche?`))return;if(prompt(`Scrivi ${user.username} per confermare`)!==user.username)return;try{await cloudApi(`./api/admin/users/${user.id}`,{method:'DELETE'});notify('Account eliminato');loadCloudAdminUsers()}catch(error){notify(error.message)}})}
async function showCloudStatistics(userId){try{const result=await cloudApi(`./api/admin/users/${userId}/statistics`),summary=result.summary,categoriesMarkup=Object.entries(result.categories).map(([id,s])=>`<div class="cloud-category-stat"><b>${esc(catName(id))}</b><span>${s.accuracy==null?'—':`${s.accuracy}%`} precisione complessiva · ${s.known} note · ${s.review} da ripetere · ${s.unknown} non note · ${s.toDo??s.unanswered} da fare</span><span class="quiz-average-line">${s.quizCount?`<strong>${s.quizCount}</strong> quiz completati · media <strong>${fmtMetric(s.averageQuizScore)} pt</strong> su ${fmtMetric(s.averageQuizQuestions,1)} domande · <strong>${fmtMetric(s.averageQuizAccuracy,1)}%</strong>`:'Nessun quiz completo registrato per questa materia.'}</span></div>`).join(''),sessions=result.recentSessions.slice(0,20).map(session=>`<div class="history"><b>${esc(sessionTypeLabel(session.type))} · ${session.at?new Date(session.at).toLocaleString('it'):''}</b><span>${session.accuracy==null?'—':`${session.accuracy}%`} · ${session.score??'—'} punti · ${session.correct||0} Giuste · ${session.wrong||0} Sbagliate · ${session.blank||0} Non risposte</span></div>`).join('');const overlay=document.createElement('div');overlay.className='update-dialog-backdrop';overlay.innerHTML=`<section class="card update-dialog cloud-stats-dialog"><div class="eyebrow">Statistiche complete</div><h2>${esc(result.user.name)} · @${esc(result.user.username)}</h2><h3>Medie dei quiz</h3><div class="cloud-average-grid"><div class="stat"><strong>${summary.fortyQuizzes||0}</strong><span>Prove da 40</span></div><div class="stat highlight"><strong>${fmtMetric(summary.averageFortyScore)}</strong><span>Media punti /40</span></div><div class="stat"><strong>${summary.averageFortyAccuracy==null?'—':`${fmtMetric(summary.averageFortyAccuracy,1)}%`}</strong><span>Precisione prove 40</span></div><div class="stat"><strong>${summary.subjectQuizzes||0}</strong><span>Quiz argomenti</span></div><div class="stat highlight"><strong>${summary.averageSubjectAccuracy==null?'—':`${fmtMetric(summary.averageSubjectAccuracy,1)}%`}</strong><span>Media argomenti</span></div><div class="stat"><strong>${fmtMetric(summary.averageSubjectScore)}</strong><span>Media punti argomenti</span></div></div><h3>Preparazione</h3><div class="stat-row four"><div class="stat"><strong>${summary.answered}</strong><span>Domande svolte</span></div><div class="stat"><strong>${summary.known}</strong><span>Conosciute</span></div><div class="stat"><strong>${summary.review}</strong><span>Da ripetere</span></div><div class="stat"><strong>${summary.unknown}</strong><span>Non note</span></div></div><h3>Per materia</h3><div class="cloud-category-list">${categoriesMarkup||'<p class="meta">Nessun progresso.</p>'}</div><h3>Ultime sessioni</h3><div>${sessions||'<p class="meta">Nessuna sessione completata.</p>'}</div><button class="primary" data-close-stats>Chiudi</button></section>`;document.body.append(overlay);overlay.querySelector('[data-close-stats]').onclick=()=>overlay.remove();overlay.onclick=event=>{if(event.target===overlay)overlay.remove()}}catch(error){notify(error.message)}}

function cloudSettingsMarkup(){return `<section class="cloud-settings"><div class="section-head"><div><div class="eyebrow">Server Linux e dominio pubblico</div><h2>Impostazioni Cloud</h2></div></div><form class="card cloud-settings-form" id="cloudSettingsForm"><fieldset><legend>Portale</legend><label>Nome portale<input name="siteName" required></label><label>URL pubblico<input name="publicUrl" type="url" placeholder="https://nome.duckdns.org"></label><label class="check-label"><input name="registrationEnabled" type="checkbox"> Consenti registrazione pubblica</label><label>Durata sessione (giorni)<input name="sessionDays" type="number" min="1" max="365"></label><label>Scadenza link recupero (minuti)<input name="resetTokenMinutes" type="number" min="10" max="1440"></label><label class="full">Informativa breve<textarea name="privacyNotice"></textarea></label></fieldset><fieldset class="network-settings"><legend>Porte e HTTPS</legend><div class="network-status full" data-network-status>Caricamento configurazione rete…</div><div class="port-control full hidden" data-port-control><label>Nuova porta backend<input name="deploymentAppPort" type="number" min="1024" max="65535"></label><button class="secondary" type="button" data-change-port>Controlla e applica porta</button><p class="meta" data-port-control-status></p></div><p class="meta full">Il pubblico continua a usare HTTPS sulla porta 443. Il controllo protetto sul server verifica che la nuova porta sia libera, aggiorna il backend e ricarica il reverse proxy; in caso di errore ripristina la configurazione precedente.</p></fieldset><fieldset><legend>DuckDNS</legend><label class="check-label"><input name="duckdnsEnabled" type="checkbox"> Aggiornamento DuckDNS attivo</label><label>Dominio<input name="duckdnsDomain" placeholder="mioquiz o mioquiz.duckdns.org"></label><label>Token DuckDNS<input name="duckdnsToken" type="password" placeholder="Lascia vuoto per mantenere quello salvato"></label><label>Intervallo (minuti)<input name="duckdnsIntervalMinutes" type="number" min="5" max="1440"></label><p class="meta full" data-duckdns-status></p><button class="ghost" type="button" data-test-duckdns>Prova DuckDNS</button></fieldset><fieldset><legend>Email e password dimenticata</legend><label class="check-label"><input name="smtpEnabled" type="checkbox"> Invio email attivo</label><label>Server SMTP<input name="smtpHost"></label><label>Porta<input name="smtpPort" type="number" min="1" max="65535"></label><label>Nome utente SMTP<input name="smtpUsername"></label><label>Password SMTP<input name="smtpPassword" type="password" placeholder="Lascia vuoto per mantenerla"></label><label>Email mittente<input name="smtpFromEmail" type="email"></label><label class="check-label"><input name="smtpUseTls" type="checkbox"> Usa STARTTLS</label><button class="ghost" type="button" data-test-email>Invia email di prova all'admin</button></fieldset><button class="primary" type="submit">Salva impostazioni cloud</button></form></section>`}
async function loadCloudSettings(){try{const s=await cloudApi('./api/admin/settings'),form=app.querySelector('#cloudSettingsForm');for(const [name,value] of Object.entries({siteName:s.siteName,publicUrl:s.publicUrl,sessionDays:s.sessionDays,resetTokenMinutes:s.resetTokenMinutes,privacyNotice:s.privacyNotice,duckdnsDomain:s.duckdnsDomain,duckdnsIntervalMinutes:s.duckdnsIntervalMinutes,smtpHost:s.smtpHost,smtpPort:s.smtpPort,smtpUsername:s.smtpUsername,smtpFromEmail:s.smtpFromEmail,deploymentAppPort:s.deploymentAppPort})){if(form.elements[name])form.elements[name].value=value??''}for(const [name,value] of Object.entries({registrationEnabled:s.registrationEnabled,duckdnsEnabled:s.duckdnsEnabled,smtpEnabled:s.smtpEnabled,smtpUseTls:s.smtpUseTls})){form.elements[name].checked=Boolean(value)}form.elements.duckdnsToken.placeholder=s.duckdnsTokenConfigured?'Token già salvato · lascia vuoto per mantenerlo':'Inserisci token DuckDNS';form.elements.smtpPassword.placeholder=s.smtpPasswordConfigured?'Password già salvata · lascia vuoto per mantenerla':'Inserisci password SMTP';const networkStatus=form.querySelector('[data-network-status]');networkStatus.innerHTML=s.deploymentProxyMode==='external'?`<b>Reverse proxy esistente</b><span>HTTPS pubblico: porta 443 → backend ${esc(s.deploymentBindAddress)}:${Number(s.deploymentAppPort)}</span>`:`<b>Proxy HTTPS incluso</b><span>HTTP ${Number(s.deploymentHttpPort)} · HTTPS ${Number(s.deploymentHttpsPort)} · backend locale ${Number(s.deploymentAppPort)}</span>`;const portControl=form.querySelector('[data-port-control]'),portStatus=form.querySelector('[data-port-control-status]');portControl?.classList.toggle('hidden',!s.portControl?.available);if(portStatus)portStatus.textContent=portControlStatusLabel(s.portControl);form.querySelector('[data-duckdns-status]').textContent=s.duckdnsLastStatus?.at?`Ultimo controllo: ${new Date(s.duckdnsLastStatus.at).toLocaleString('it')} · ${s.duckdnsLastStatus.ok?'OK':'Errore'} · ${s.duckdnsLastStatus.response||''}`:'Nessun aggiornamento DuckDNS eseguito.';form.onsubmit=saveCloudSettings;form.querySelector('[data-change-port]').onclick=()=>requestCloudPortChange(form,s);form.querySelector('[data-test-duckdns]').onclick=async()=>{try{const result=await cloudApi('./api/admin/settings/test-duckdns',{method:'POST'});notify(result.ok?'DuckDNS aggiornato correttamente':'DuckDNS non aggiornato');loadCloudSettings()}catch(error){notify(error.message)}};form.querySelector('[data-test-email]').onclick=async()=>{try{const result=await cloudApi('./api/admin/settings/test-email',{method:'POST'});notify(result.message)}catch(error){notify(error.message)}}}catch(error){notify(error.message)}}
function portControlStatusLabel(status){if(!status?.available)return'Il cambio diretto non è installato su questo server.';if(status.state==='applying'||status.state==='queued')return`Cambio porta in corso${status.port?` verso ${status.port}`:''}…`;if(status.state==='applied')return`Ultimo cambio completato${status.port?`: backend sulla porta ${status.port}`:''}.`;if(status.state==='error')return`Ultimo cambio non riuscito: ${status.message||'configurazione precedente ripristinata'}`;return'Controllo porte pronto.'}
async function requestCloudPortChange(form,current){const port=Number(form.elements.deploymentAppPort.value);if(!Number.isInteger(port)||port<1024||port>65535)return notify('Scegli una porta tra 1024 e 65535');if(port===Number(current.deploymentAppPort))return notify('Questa porta è già attiva');if(!confirm(`Cambiare la porta backend da ${current.deploymentAppPort} a ${port}?\n\nIl portale verrà riavviato per pochi secondi. La porta pubblica HTTPS resterà 443.`))return;const button=form.querySelector('[data-change-port]');button.disabled=true;button.textContent='Richiesta in corso…';try{await cloudApi('./api/admin/network/apply',{method:'POST',body:JSON.stringify({app_port:port})});const status=form.querySelector('[data-port-control-status]');status.textContent=`Riavvio del backend sulla porta ${port}…`;await waitForCloudPortChange(port,status)}catch(error){button.disabled=false;button.textContent='Controlla e applica porta';notify(error.message)}}
async function waitForCloudPortChange(port,status){const deadline=Date.now()+180000;while(Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,2200));try{const settings=await cloudApi(`./api/admin/settings?t=${Date.now()}`);if(Number(settings.deploymentAppPort)===port){status.textContent=`Porta ${port} attiva. Ricarico il pannello…`;setTimeout(()=>location.reload(),700);return}if(settings.portControl?.state==='error')throw Error(settings.portControl.message||'Cambio porta non riuscito')}catch(error){if(error.message&&error.message!=='Richiesta non riuscita')status.textContent=error.message}}status.textContent='Il riavvio richiede più tempo del previsto. Ricarica la pagina tra poco.'}
async function saveCloudSettings(event){event.preventDefault();const f=new FormData(event.currentTarget),payload={site_name:String(f.get('siteName')).trim(),registration_enabled:f.get('registrationEnabled')==='on',public_url:String(f.get('publicUrl')).trim(),session_days:Number(f.get('sessionDays')),reset_token_minutes:Number(f.get('resetTokenMinutes')),privacy_notice:String(f.get('privacyNotice')).trim(),duckdns_enabled:f.get('duckdnsEnabled')==='on',duckdns_domain:String(f.get('duckdnsDomain')).trim(),duckdns_token:String(f.get('duckdnsToken')),duckdns_interval_minutes:Number(f.get('duckdnsIntervalMinutes')),smtp_enabled:f.get('smtpEnabled')==='on',smtp_host:String(f.get('smtpHost')).trim(),smtp_port:Number(f.get('smtpPort')),smtp_username:String(f.get('smtpUsername')).trim(),smtp_password:String(f.get('smtpPassword')),smtp_from_email:String(f.get('smtpFromEmail')).trim()||null,smtp_use_tls:f.get('smtpUseTls')==='on'};try{await cloudApi('./api/admin/settings',{method:'PUT',body:JSON.stringify(payload)});runtimeConfig={...runtimeConfig,siteName:payload.site_name,registrationEnabled:payload.registration_enabled,privacyNotice:payload.privacy_notice,emailResetEnabled:payload.smtp_enabled};document.querySelector('.brand>span:last-child').textContent=payload.site_name;notify('Impostazioni cloud salvate');loadCloudSettings()}catch(error){notify(error.message)}}

function brandingSettingsMarkup(){return `<section class="branding-settings card"><div><div class="eyebrow">Aspetto globale</div><h2>Logo del portale</h2><p class="meta">Il logo viene applicato senza deformazioni nell’intestazione, nelle schermate di accesso e nell’icona installabile. Formati JPEG, PNG o WebP; massimo 1 MB.</p></div><div class="branding-editor"><img data-brand-preview src="${esc(currentLogoUrl())}" alt="Anteprima logo"><div><label>Scegli un nuovo logo<input type="file" data-brand-file accept="image/jpeg,image/png,image/webp"></label><div class="quiz-actions"><button class="secondary" type="button" data-brand-save disabled>Applica ovunque</button><button class="ghost" type="button" data-brand-reset>Ripristina predefinito</button></div><p class="meta" data-brand-status></p></div></div></section>`}
function bindBrandingSettings(){const section=app.querySelector('.branding-settings');if(!section)return;const input=section.querySelector('[data-brand-file]'),preview=section.querySelector('[data-brand-preview]'),save=section.querySelector('[data-brand-save]'),status=section.querySelector('[data-brand-status]');let selected=null;input.onchange=()=>{const file=input.files?.[0];selected=null;save.disabled=true;if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1024*1024){input.value='';status.textContent='Il file deve essere JPEG, PNG o WebP e pesare al massimo 1 MB.';return}const reader=new FileReader();reader.onload=()=>{selected=String(reader.result);preview.src=selected;save.disabled=false;status.textContent=`Pronto: ${file.name} · ${Math.ceil(file.size/1024)} KB`};reader.readAsDataURL(file)};save.onclick=async()=>{if(!selected)return;save.disabled=true;try{if(cloudMode){const result=await cloudApi('./api/admin/branding/logo',{method:'POST',body:JSON.stringify({data_url:selected})});runtimeConfig.logoCustomized=true;applyBranding(result.logoUrl)}else{examConfig.brandLogoDataUrl=selected;localStorage.setItem(CONFIG,JSON.stringify(examConfig));await portableSync();applyBranding(selected)}preview.src=currentLogoUrl();status.textContent='Logo applicato in tutto il portale.';notify('Logo aggiornato')}catch(error){save.disabled=false;status.textContent=error.message}};section.querySelector('[data-brand-reset]').onclick=async()=>{if(!confirm('Ripristinare il logo nero predefinito?'))return;try{if(cloudMode){const result=await cloudApi('./api/admin/branding/logo',{method:'DELETE'});runtimeConfig.logoCustomized=false;applyBranding(result.logoUrl)}else{delete examConfig.brandLogoDataUrl;localStorage.setItem(CONFIG,JSON.stringify(examConfig));await portableSync();applyBranding('logo-vvf.jpg')}selected=null;input.value='';save.disabled=true;preview.src=currentLogoUrl();status.textContent='Logo predefinito ripristinato.';notify('Logo ripristinato')}catch(error){status.textContent=error.message}}}

const loadCloudSettingsBase=loadCloudSettings;
loadCloudSettings=async function(){await loadCloudSettingsBase();const form=app.querySelector('#cloudSettingsForm');if(!form)return;let status=form.querySelector('[data-smtp-status]');if(!status){status=document.createElement('div');status.className='smtp-status full';status.dataset.smtpStatus='';form.querySelector('[data-test-email]')?.before(status)}try{const settings=await cloudApi('./api/admin/settings');if(!settings.smtpEnabled||!settings.smtpHost){status.className='smtp-status warning full';status.innerHTML='<b>Recupero password non attivo</b><span>Configura server SMTP, mittente e credenziali, poi attiva l’invio e usa il pulsante di prova.</span>'}else if(!currentUser.email){status.className='smtp-status warning full';status.innerHTML='<b>SMTP configurato, ma l’admin non ha un’email</b><span>Aggiungi il tuo indirizzo da Account prima di eseguire la prova.</span>'}else if(settings.smtpLastStatus?.at){status.className=`smtp-status ${settings.smtpLastStatus.ok?'success':'error'} full`;status.innerHTML=`<b>${settings.smtpLastStatus.ok?'Ultimo invio riuscito':'Ultimo invio non riuscito'}</b><span>${new Date(settings.smtpLastStatus.at).toLocaleString('it')} · ${esc(settings.smtpLastStatus.message||'')}</span>`}else{status.className='smtp-status success full';status.innerHTML='<b>Configurazione pronta per la prova</b><span>Invia un’email di test prima di affidarti al recupero password.</span>'}}catch(error){status.textContent=error.message}};

const saveCloudSettingsBase=saveCloudSettings;
saveCloudSettings=async function(event){await saveCloudSettingsBase(event);try{runtimeConfig={...runtimeConfig,...await cloudApi('./api/runtime')}}catch{}};

let portalUpdateSnapshot=null;
const formatFileSize=value=>{const bytes=Number(value)||0;if(bytes<1024)return`${bytes} B`;if(bytes<1024*1024)return`${Math.round(bytes/1024)} KB`;return`${(bytes/1024/1024).toLocaleString('it',{maximumFractionDigits:1})} MB`};
function portalUpdateCenterMarkup(){return `<section class="portal-update-center card"><div class="portal-update-head"><div><div class="eyebrow">Manutenzione del portale</div><h2>Aggiornamenti software</h2></div><span class="version-badge">Installata <b data-installed-version>${esc(runtimeConfig.version||'—')}</b></span></div><p class="meta">Il controllo legge le release ufficiali da GitHub. Prima di installare puoi vedere versione e changelog; il server crea automaticamente un backup PostgreSQL e una copia dei file.</p><div class="portal-update-actions"><button class="secondary" type="button" data-portal-update-check>Cerca aggiornamenti</button><label class="button ghost update-file-button">Carica file ZIP<input type="file" accept="application/zip,.zip" data-portal-update-file hidden></label></div><div class="update-source-card" data-update-source><div class="update-empty"><b>Nessun controllo eseguito</b><span>Premi “Cerca aggiornamenti” oppure carica un pacchetto server.</span></div></div><div class="portal-operation-status" data-portal-operation-status>Stato controllo server in caricamento…</div></section><section class="server-power-card card"><div><div class="eyebrow">Controllo server</div><h2>Riavvia o spegni il portale</h2><p>Questi comandi agiscono soltanto sul portale Quiz 400 VVF. La macchina e gli altri servizi del reverse proxy restano accesi.</p></div><div class="server-power-actions"><button class="ghost" type="button" data-portal-restart>Riavvia portale</button><button class="ghost danger-text" type="button" data-portal-stop>Spegni portale</button></div><p class="meta">Dopo lo spegnimento il portale può essere riacceso dal server con lo script di avvio Linux o Windows.</p></section>`}
function portalControlLabel(control){if(!control?.available)return'Controllo server non installato: esegui lo script di installazione del controllo.';const labels={ready:'Controllo server pronto.',completed:control.message||'Ultima operazione completata.',stopped:control.message||'Portale arrestato.',error:`Errore: ${control.message||'operazione non riuscita.'}`,'backing-up':'Backup in corso…',downloading:'Download e verifica del pacchetto…',installing:'Installazione e riavvio in corso…',restarting:'Riavvio in corso…',stopping:'Spegnimento in corso…'};return labels[control.state]||control.message||'Controllo server pronto.'}
function renderPortalUpdateStatus(status=portalUpdateSnapshot){if(!status)return;portalUpdateSnapshot=status;app.querySelector('[data-installed-version]')?.replaceChildren(document.createTextNode(status.currentVersion||runtimeConfig.version||'—'));const operation=app.querySelector('[data-portal-operation-status]');if(operation){operation.textContent=portalControlLabel(status.control);operation.className=`portal-operation-status ${status.control?.state||'ready'}`}const target=app.querySelector('[data-update-source]');if(!target)return;const candidate=status.upload?.updateAvailable?status.upload:status.github;if(!candidate){target.innerHTML='<div class="update-empty"><b>Nessun aggiornamento selezionato</b><span>Cerca su GitHub oppure carica manualmente il pacchetto ZIP server.</span></div>';return}const source=candidate.source==='upload'?'File caricato':'GitHub',available=Boolean(candidate.updateAvailable),canInstall=Boolean(candidate.canInstall);target.innerHTML=`<div class="update-version-line"><span>${esc(source)}</span><b>${available?`Nuova versione ${esc(candidate.latestVersion)}`:`Versione ${esc(candidate.latestVersion)}`}</b></div><div class="version-comparison"><span>Installata <b>${esc(candidate.currentVersion||status.currentVersion)}</b></span><span>Disponibile <b>${esc(candidate.latestVersion)}</b></span>${candidate.assetSize?`<span>Pacchetto <b>${formatFileSize(candidate.assetSize)}</b></span>`:''}</div><div class="update-changelog"><b>Changelog prima dell’installazione</b><pre>${esc(candidate.changelog||'Nessuna nota disponibile.')}</pre></div><div class="quiz-actions">${canInstall?`<button class="primary" type="button" data-install-portal-update="${esc(candidate.source)}">Installa ${esc(candidate.latestVersion)}</button>`:`<button class="ghost" type="button" disabled>${available?'Pacchetto server non disponibile':'Portale già aggiornato'}</button>`}${candidate.releaseUrl?`<a class="button ghost" href="${esc(candidate.releaseUrl)}" target="_blank" rel="noopener">Apri release GitHub</a>`:''}</div>`;target.querySelector('[data-install-portal-update]')?.addEventListener('click',()=>installPortalUpdate(candidate.source,candidate))}
async function loadPortalUpdateStatus(){try{const status=await cloudApi('./api/admin/update/status');renderPortalUpdateStatus(status);return status}catch(error){const node=app.querySelector('[data-portal-operation-status]');if(node){node.className='portal-operation-status error';node.textContent=error.message}return null}}
function showPortalUpdatePrompt(info){if(document.querySelector('[data-portal-update-prompt]'))return;const overlay=document.createElement('div');overlay.className='update-dialog-backdrop';overlay.dataset.portalUpdatePrompt='';overlay.innerHTML=`<section class="card update-dialog portal-update-prompt" role="dialog" aria-modal="true"><div class="eyebrow">Aggiornamento server disponibile</div><h2>Versione ${esc(info.latestVersion)}</h2><p>Nel portale è installata la ${esc(info.currentVersion)}. Puoi leggere il changelog completo prima di decidere.</p><div class="update-changelog"><b>Changelog</b><pre>${esc(info.changelog||'Nessuna nota disponibile.')}</pre></div><div class="quiz-actions"><button class="primary" type="button" data-open-update-center>Apri aggiornamenti</button><button class="ghost" type="button" data-close-update-prompt>Più tardi</button></div></section>`;document.body.append(overlay);const close=()=>overlay.remove();overlay.querySelector('[data-close-update-prompt]').onclick=close;overlay.querySelector('[data-open-update-center]').onclick=()=>{close();location.hash='settings';setTimeout(()=>app.querySelector('.portal-update-center')?.scrollIntoView({behavior:'smooth'}),250)};overlay.onclick=event=>{if(event.target===overlay)close()}}
async function checkPortalUpdate(manual=false,periodic=false){if(!currentUser||currentUser.role!=='admin')return;if(!manual&&!periodic&&updateCheckedFor===currentUser.id)return;if(periodic&&Date.now()-lastUpdateCheckAt<5*60*1000)return;if(!manual&&!periodic)updateCheckedFor=currentUser.id;lastUpdateCheckAt=Date.now();if(manual)notify('Controllo della release GitHub…');try{const info=await cloudApi('./api/admin/update/check',{method:'POST'}),status=await loadPortalUpdateStatus();if(info.updateAvailable){if(manual||updatePromptedVersion!==info.latestVersion){updatePromptedVersion=info.latestVersion;showPortalUpdatePrompt(info)}}else if(manual)notify(`Versione ${info.currentVersion}: portale aggiornato`);return status}catch(error){if(manual)notify(error.message)}}
function portalProgressDialog(title,copy){const overlay=document.createElement('div');overlay.className='update-dialog-backdrop';overlay.innerHTML=`<section class="card update-dialog portal-progress-dialog"><div class="update-spinner" aria-hidden="true"></div><div class="eyebrow">Manutenzione server</div><h2>${esc(title)}</h2><p>${esc(copy)}</p><p class="meta" data-portal-progress>Richiesta inviata al server…</p></section>`;document.body.append(overlay);return overlay}
async function waitForPortalOperation(overlay,expectedVersion=null){const progress=overlay.querySelector('[data-portal-progress]'),deadline=Date.now()+20*60*1000;while(Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,2200));try{const status=await cloudApi(`./api/admin/update/status?t=${Date.now()}`),control=status.control||{};if(progress)progress.textContent=portalControlLabel(control);if(control.state==='error')throw Error(control.message||'Operazione non riuscita');if(control.state==='completed'&&(!expectedVersion||control.version===expectedVersion)){overlay.querySelector('.portal-progress-dialog').innerHTML=`<div class="eyebrow">Operazione completata</div><h2>${expectedVersion?`Versione ${esc(expectedVersion)} installata`:'Portale riavviato'}</h2><p>Il portale è nuovamente disponibile. Account, statistiche e database PostgreSQL sono rimasti al loro posto.</p><div class="quiz-actions"><button class="primary" type="button" data-refresh-updated-app>Ricarica e aggiorna cache</button></div>`;overlay.querySelector('[data-refresh-updated-app]').onclick=()=>refreshApplicationCache(overlay);return}}catch(error){if(error.message&&error.message!=='Operazione non riuscita'){overlay.querySelector('.portal-progress-dialog').innerHTML=`<div class="eyebrow">Operazione non completata</div><h2>Controlla lo stato del server</h2><p>${esc(error.message)}</p><div class="quiz-actions"><button class="primary" type="button" data-close-operation>Chiudi</button></div>`;overlay.querySelector('[data-close-operation]').onclick=()=>overlay.remove();return}}}if(progress)progress.textContent='L’operazione richiede più tempo del previsto. Controlla nuovamente tra poco.'}
async function installPortalUpdate(source,info){if(!confirm(`Installare la versione ${info.latestVersion} da ${source==='github'?'GitHub':'file caricato'}?\n\nPrima verranno creati il backup PostgreSQL e la copia dei file correnti.`))return;const overlay=portalProgressDialog(`Installazione ${info.latestVersion}`,'Il portale farà backup, verifica, installazione e riavvio. Non chiudere questa pagina.');try{await cloudApi('./api/admin/update/install',{method:'POST',body:JSON.stringify({source})});await waitForPortalOperation(overlay,info.latestVersion)}catch(error){overlay.remove();notify(error.message)}}
async function uploadPortalUpdate(file){if(!file)return;const form=new FormData();form.append('file',file,file.name);notify('Controllo del pacchetto caricato…');try{const info=await cloudApi('./api/admin/update/upload',{method:'POST',body:form});await loadPortalUpdateStatus();notify(info.updateAvailable?`Pacchetto ${info.latestVersion} pronto`:'Il pacchetto non è più recente della versione installata')}catch(error){notify(error.message)}}
async function requestPortalPower(action){const restart=action==='restart',label=restart?'riavviare':'spegnere';if(!confirm(`${restart?'Riavviare':'Spegnere'} il portale adesso?\n\nLa macchina e gli altri servizi resteranno accesi.`))return;if(!restart&&prompt('Per confermare scrivi SPEGNI')!=='SPEGNI')return;const overlay=portalProgressDialog(restart?'Riavvio del portale':'Spegnimento del portale',restart?'Il sito non sarà raggiungibile per pochi secondi.':'Dopo lo spegnimento dovrai riaccenderlo dal server.');try{await cloudApi(`./api/admin/server/${action}`,{method:'POST',headers:{'X-Confirm-Portal-Action':restart?'RESTART':'STOP'}});if(restart)await waitForPortalOperation(overlay);else{overlay.querySelector('[data-portal-progress]').textContent='Richiesta accettata. Il portale sta per andare offline.';setTimeout(()=>{overlay.querySelector('.portal-progress-dialog').innerHTML='<div class="eyebrow">Portale spento</div><h2>Puoi chiudere questa pagina</h2><p>Il server e gli altri servizi sono rimasti accesi. Per riattivare il portale usa lo script di avvio sul server.</p>'},1800)}}catch(error){overlay.remove();notify(error.message)}}
function bindPortalUpdateCenter(){app.querySelector('[data-portal-update-check]')?.addEventListener('click',()=>checkPortalUpdate(true));app.querySelector('[data-portal-update-file]')?.addEventListener('change',event=>uploadPortalUpdate(event.target.files?.[0]));app.querySelector('[data-portal-restart]')?.addEventListener('click',()=>requestPortalPower('restart'));app.querySelector('[data-portal-stop]')?.addEventListener('click',()=>requestPortalPower('stop'));loadPortalUpdateStatus()}

const cloudSettingsViewBase=settingsView;
settingsView=function(){cloudSettingsViewBase();if(currentUser?.role!=='admin')return;const examForm=app.querySelector('#examSettings');examForm?.insertAdjacentHTML('beforebegin',brandingSettingsMarkup());bindBrandingSettings();if(!cloudMode)return;examForm?.insertAdjacentHTML('beforebegin',portalUpdateCenterMarkup());examForm?.insertAdjacentHTML('beforebegin',cloudSettingsMarkup());bindPortalUpdateCenter();loadCloudSettings()};

const renderGuidedBase=renderGuided;
renderGuided=function(){renderGuidedBase();const h=quiz?.pool?.[quiz.index]&&quiz.history[quiz.pool[quiz.index].id];if(!h)return;const bottomNav=app.querySelector('.nav-actions'),feedback=app.querySelector('.trainer-feedback');if(!bottomNav)return;const topNav=bottomNav.cloneNode(true);topNav.classList.add('explanation-nav','top');feedback?feedback.before(topNav):bottomNav.before(topNav);topNav.querySelector('[data-finish-now]')?.addEventListener('click',finishCurrentQuiz);topNav.querySelector('[data-guided-prev]')?.addEventListener('click',guidedPrevious);topNav.querySelector('[data-guided-skip]')?.addEventListener('click',guidedSkip);topNav.querySelector('[data-guided-next]')?.addEventListener('click',guidedNext)};
const scoreFor=(correct,wrong)=>Math.round((correct-wrong*.33)*100)/100;
function resultCard(title,correct,wrong,blank,actions){const score=scoreFor(correct,wrong);return `<div class="result-card card"><div class="eyebrow">${esc(title)}</div><div class="result-score-label">Punteggio finale</div><h1 class="result-score">${score.toLocaleString('it')} punti</h1><div class="stat-row"><div class="stat correct-stat"><strong>${correct}</strong><span>Giuste</span></div><div class="stat wrong-stat"><strong>${wrong}</strong><span>Sbagliate</span></div><div class="stat blank-stat"><strong>${blank}</strong><span>Non risposte</span></div></div><p class="score-formula">Calcolo: ${correct} - (${wrong} × 0,33) = <b>${score.toLocaleString('it')}</b></p><div class="quiz-actions">${actions}</div></div>`}
const resultCardBase=resultCard;
resultCard=function(title,correct,wrong,blank,actions){const safeActions=actions.replaceAll('href="#simulation"','href="#simulation/new"').replaceAll('href="#categories"','href="#categories/new"');return resultCardBase(title,correct,wrong,blank,safeActions)};
reviewReport=function(rows){if(!rows.length)return'';const counts={wrong:rows.filter(r=>!r.correct&&!r.blank).length,blank:rows.filter(r=>r.blank).length,correct:rows.filter(r=>r.correct).length},group=(type,label)=>{const list=rows.filter(r=>type==='correct'?r.correct:type==='wrong'?!r.correct&&!r.blank:r.blank);return `<section class="review-group" id="review-${type}"><div class="section-head"><h2>${label}</h2><span class="review-count">${list.length}</span></div>${list.length?list.map((r,i)=>{const q=r.q||allStoredQuestions().find(x=>x.id===r.id),chosen=r.blank?'Non data':r.choiceText??q.answers[r.choice],right=r.correctText??q.answers[q.correct];return `<details class="card review-item" ${type!=='correct'?'open':''}><summary><span class="review-badge ${type}">${type==='correct'?'✓':type==='wrong'?'✕':'—'}</span><span><small>${esc(catName(q.category))} · domanda ${i+1}</small>${esc(q.text)}</span></summary>${q.image?`<img class="question-image mini" src="${esc(q.image)}" alt="Diagramma del quesito">`:''}<div class="review-answer"><span>La tua risposta</span><b>${esc(chosen)}</b></div><div class="review-answer correct-text"><span>Risposta corretta</span><b>${esc(right)}</b></div>${explanationMarkup(q.explanation)}${questionReportButtonMarkup(q,'riepilogo')}</details>`}).join(''):'<div class="card meta">Nessuna domanda.</div>'}</section>`};return `<div class="review-report"><div class="section-head"><div><div class="eyebrow">Correzione completa</div><h1>Cosa hai sbagliato, saltato o risposto bene</h1></div></div><div class="review-tabs"><a href="#review-wrong" class="wrong">${counts.wrong} sbagliate</a><a href="#review-blank" class="blank">${counts.blank} non risposte</a><a href="#review-correct" class="correct">${counts.correct} giuste</a></div>${group('wrong','Risposte sbagliate')}${group('blank','Non risposte')}${group('correct','Risposte giuste')}</div>`};

function sessionReviewRows(session){const questions=new Map(allStoredQuestions().map(q=>[String(q.id),q]));return(Array.isArray(session?.review)?session.review:[]).map(item=>{const q=questions.get(String(item.id));return q?{id:String(item.id),category:item.category||q.category,q,choiceText:item.choiceText,correctText:item.correctText,blank:Boolean(item.blank),correct:Boolean(item.correct)}:null}).filter(Boolean)}
function sessionReviewView(value){if(!currentUser)return loginView();const id=decodeURIComponent(String(value||'')),session=userState().sessions.find(item=>item.id===id),rows=sessionReviewRows(session);if(!session||!rows.length){notify('I dettagli di questo quiz non sono disponibili');return statsView()}nav('stats');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Quiz del ${new Date(session.at).toLocaleString('it')}</div><h1>${esc(sessionTypeLabel(session.type))}</h1></div><a class="button ghost compact" href="#stats">Torna alle statistiche</a></div>${resultCard('Riepilogo del quiz',session.correct||0,session.wrong||0,session.blank||0,'<a class="button primary" href="#stats">Chiudi revisione</a>')}${reviewReport(rows)}`;window.scrollTo({top:0,behavior:'instant'})}
finishGuided=function(reason='completed'){clearInterval(timerHandle);if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.mode==='guided-exam'?guidedResultRows(quiz):quiz.pool.map(q=>quiz.history[q.id]||{choice:null,blank:true,correct:false,q}),timed=isTimedFortyQuiz();if(timed){for(const row of rows){const p=progressFor(row.q.id);if(row.blank){p.skipped++;if(!p.attempts)p.status='unanswered'}else{p.attempts++;if(row.correct){p.correct++;p.status=p.correct>=2&&p.wrong===0?'known':'review'}else{p.wrong++;p.status='review'}}p.lastAt=new Date().toISOString();userState().progress[row.q.id]=p}}const session=recordSession(quiz.mode==='guided-exam'?'guided-exam':'guided',rows,{timedOut:reason==='timeout',generatedAt:quiz.generatedAt});timed?clearActiveQuiz():persist();app.innerHTML=resultCard(reason==='timeout'?'Tempo scaduto · prova guidata conclusa':'Prova guidata completata',session.correct,session.wrong,session.blank,'<a class="button primary" href="#simulation">Nuova prova</a><a class="button ghost" href="#stats">Statistiche</a>')+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})};
finishStudy=function(){if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.pool.map(q=>quiz.history[q.id]||{choice:null,blank:true,correct:false,q}),session=recordSession('study',rows,{filter:quiz.filter||null});persist();app.innerHTML=resultCard('Quiz completato',session.correct,session.wrong,session.blank,'<a class="button primary" href="#categories">Materie</a><a class="button ghost" href="#stats">Progressi</a>')+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})};
finishExam=function(reason='completed'){clearInterval(timerHandle);if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.pool.map((q,i)=>({id:q.id,category:q.category,q,choice:quiz.answers[i],correct:quiz.answers[i]===q.correct,blank:quiz.answers[i]===null}));for(const row of rows){const p=progressFor(row.id);if(row.blank){p.skipped++;if(!p.attempts)p.status='unanswered'}else{p.attempts++;if(row.correct){p.correct++;p.status=p.correct>=2&&p.wrong===0?'known':'review'}else{p.wrong++;p.status='review'}}p.lastAt=new Date().toISOString();userState().progress[row.id]=p}const session=recordSession('exam',rows,{timedOut:reason==='timeout',generatedAt:quiz.generatedAt});clearActiveQuiz();app.innerHTML=resultCard(reason==='timeout'?'Tempo scaduto · simulazione conclusa':'Simulazione completata',session.correct,session.wrong,session.blank,'<a class="button primary" href="#simulation">Nuova prova</a><a class="button ghost" href="#stats">Statistiche</a>')+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})};
finishGuided=function(reason='completed'){clearInterval(timerHandle);if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.mode==='guided-exam'?guidedResultRows(quiz):quiz.pool.map(q=>quiz.history[q.id]||{choice:null,blank:true,correct:false,q}),timed=isTimedFortyQuiz();if(timed){for(const row of rows)userState().progress[row.q.id]=applyLearningOutcome(progressFor(row.q.id),row);updateDeepLearningFromRows(rows,'guided-exam')}const session=recordSession(quiz.mode==='guided-exam'?'guided-exam':'guided',rows,{timedOut:reason==='timeout',generatedAt:quiz.generatedAt,deepLearning:Boolean(quiz.deepLearning)}),deepResult=deepLearningResultMarkup(rows,'guided-exam');timed?clearActiveQuiz():persist();app.innerHTML=resultCard(reason==='timeout'?'Tempo scaduto · prova guidata conclusa':'Prova guidata completata',session.correct,session.wrong,session.blank,'<a class="button primary" href="#simulation">Nuova prova</a><a class="button ghost" href="#stats">Statistiche</a>')+deepResult+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})};
finishExam=function(reason='completed'){clearInterval(timerHandle);if(!quiz||quiz.finished)return;if(quiz.selected!==null)quiz.answers[quiz.index]=quiz.selected;quiz.finished=true;const rows=quiz.pool.map((q,i)=>({id:q.id,category:q.category,q,choice:quiz.answers[i],correct:quiz.answers[i]===q.correct,blank:quiz.answers[i]===null}));for(const row of rows)userState().progress[row.id]=applyLearningOutcome(progressFor(row.id),row);updateDeepLearningFromRows(rows,'exam');const session=recordSession('exam',rows,{timedOut:reason==='timeout',generatedAt:quiz.generatedAt,deepLearning:Boolean(quiz.deepLearning)}),deepResult=deepLearningResultMarkup(rows,'exam');clearActiveQuiz();app.innerHTML=resultCard(reason==='timeout'?'Tempo scaduto · simulazione conclusa':'Simulazione completata',session.correct,session.wrong,session.blank,'<a class="button primary" href="#simulation">Nuova prova</a><a class="button ghost" href="#stats">Statistiche</a>')+deepResult+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})};

function privacyLinkMarkup(){return cloudMode?'<a class="privacy-link" href="#privacy">Informativa privacy completa</a>':''}
const loginViewBeforePrivacy=loginView;
loginView=function(){loginViewBeforePrivacy();if(!cloudMode)return;const form=app.querySelector('#authForm');if(form&&!form.querySelector('.privacy-link'))form.insertAdjacentHTML('beforeend',`<div class="auth-privacy-links">${privacyLinkMarkup()}</div>`) };

registerView=function(){if(!cloudMode||!runtimeConfig.registrationEnabled)return loginView();const policy=runtimeConfig.privacy||{},version=String(policy.policyVersion||'');publicAuthShell('Crea il tuo account','Registrati per mantenere progressi e statistiche sincronizzati nel cloud.',`<form class="card auth-card" id="registerForm"><label>Nome visualizzato<input name="name" autocomplete="name" minlength="2" required></label><label>Nome utente<input name="username" autocomplete="username" minlength="3" pattern="[a-zA-Z0-9._-]+" required></label><label>Email per recupero password<input name="email" type="email" autocomplete="email" required></label><p class="meta">Serve per ricevere il link se dimentichi la password.</p><label>Password<input name="password" type="password" autocomplete="new-password" minlength="10" required></label><label>Ripeti password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="10" required></label><label class="privacy-ack"><input name="privacyAcknowledged" type="checkbox" required><span>Ho letto l’<a href="#privacy" target="_blank" rel="noopener">informativa privacy</a> (versione ${esc(version||'corrente')}). Questa conferma registra la presa visione, non un consenso pubblicitario.</span></label><button class="primary">Registrati</button><a class="button ghost" href="#login">Hai già un account? Accedi</a><p class="meta">${esc(runtimeConfig.privacyNotice||'')}</p></form>`);app.querySelector('#registerForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);if(f.get('password')!==f.get('confirmPassword'))return notify('Le password non coincidono');try{const result=await cloudApi('./api/auth/register',{method:'POST',body:JSON.stringify({name:String(f.get('name')).trim(),username:String(f.get('username')).trim(),email:String(f.get('email')).trim(),password:String(f.get('password')),privacy_acknowledged:f.get('privacyAcknowledged')==='on',privacy_policy_version:version})});notify(result.message);location.hash='login'}catch(error){notify(error.message)}}};

function privacyView(){const p=runtimeConfig.privacy||{},site=runtimeConfig.siteName||'Quiz 400 VVF 2026',email=String(p.contactEmail||''),pec=String(p.pecEmail||''),effective=p.effectiveDate?new Date(`${p.effectiveDate}T00:00:00`).toLocaleDateString('it-IT'):'non indicata',back=currentUser?'#account':'#login';nav('home');document.querySelector('.bottom-nav').classList.add('hidden');app.innerHTML=`<article class="privacy-page"><header class="privacy-hero"><div><div class="eyebrow">Articoli 12 e 13 GDPR</div><h1>Informativa sul trattamento dei dati personali</h1><p>${esc(site)} · versione ${esc(p.policyVersion||'—')} · efficace dal ${esc(effective)}</p></div><div class="privacy-actions"><button class="ghost compact" type="button" data-print-privacy>Stampa / salva PDF</button><a class="button primary compact" href="${back}">Torna ${currentUser?'all’account':'al login'}</a></div></header>${p.complete?'':`<aside class="privacy-warning"><b>Configurazione da completare</b><span>L’amministratore deve indicare almeno identità e email del titolare prima di aprire le registrazioni.</span></aside>`}<section class="privacy-summary card"><h2>In breve</h2><div class="privacy-summary-grid"><span><b>Dati</b>Account, progressi, preferenze e log tecnici</span><span><b>Finalità</b>Servizio quiz, sincronizzazione e sicurezza</span><span><b>Pubblicità</b>Nessuna pubblicità o profilazione commerciale</span><span><b>Controllo</b>Puoi accedere, esportare, correggere o chiedere la cancellazione</span></div></section><section class="privacy-section card"><h2>1. Titolare del trattamento</h2><p>Il titolare è <b>${esc(p.controllerName||'non ancora configurato')}</b>.</p>${p.controllerAddress?`<p>Recapito: ${esc(p.controllerAddress)}</p>`:''}<ul>${email?`<li>Email: <a href="mailto:${esc(email)}">${esc(email)}</a></li>`:''}${pec?`<li>PEC: <a href="mailto:${esc(pec)}">${esc(pec)}</a></li>`:''}${p.dpoContact?`<li>Responsabile della protezione dati, se nominato: ${esc(p.dpoContact)}</li>`:''}</ul></section><section class="privacy-section card"><h2>2. Quali dati trattiamo</h2><ul><li><b>Dati di account:</b> nome visualizzato, nome utente, email, ruolo, stato dell’account e date di creazione/ultimo accesso.</li><li><b>Credenziali:</b> la password è conservata soltanto come hash Argon2; non è leggibile dagli amministratori. I token di sessione e recupero sono memorizzati in forma non reversibile.</li><li><b>Percorso di studio:</b> risposte, errori, domande non risposte, punteggi, statistiche per materia, preferenze, tema, configurazioni delle prove e stato del ripasso adattivo.</li><li><b>Dati tecnici e di sicurezza:</b> indirizzo IP, browser/user agent, accessi ed eventi amministrativi o di sicurezza.</li><li><b>Email di servizio:</b> indirizzo e informazioni strettamente necessarie a inviare recupero password e comunicazioni tecniche.</li></ul><p>Non chiediamo categorie particolari di dati, documenti d’identità o dati di pagamento. Non inserire informazioni sensibili nei campi liberi.</p></section><section class="privacy-section card"><h2>3. Finalità e basi giuridiche</h2><div class="privacy-table"><div><b>Creazione e gestione dell’account, sincronizzazione, quiz, statistiche e preferenze</b><span>Esecuzione del servizio richiesto, art. 6(1)(b) GDPR.</span></div><div><b>Recupero password e comunicazioni tecniche</b><span>Esecuzione del servizio e sicurezza dell’account, art. 6(1)(b) e 6(1)(f).</span></div><div><b>Prevenzione abusi, protezione del portale, diagnosi e log amministrativi</b><span>Legittimo interesse alla sicurezza e continuità del servizio, art. 6(1)(f).</span></div><div><b>Adempimento di richieste dell’autorità o obblighi di legge</b><span>Obbligo legale, art. 6(1)(c), quando applicabile.</span></div></div><p>I dati contrassegnati come obbligatori sono necessari per creare e proteggere l’account. Senza nome utente, email e password il servizio cloud non può essere erogato. Non chiediamo consenso per pubblicità: non svolgiamo marketing.</p></section><section class="privacy-section card"><h2>4. Come funzionano analisi e “Deep learning”</h2><p>Le statistiche e i suggerimenti di esercitazione sono calcoli automatici basati sulle risposte dell’utente. La modalità chiamata “Deep learning” è un algoritmo locale di rotazione e ripasso: non usa modelli di intelligenza artificiale esterni e non invia le risposte a terzi.</p><p>Queste funzioni hanno esclusivamente scopo didattico e non producono decisioni con effetti giuridici o analogamente significativi ai sensi dell’art. 22 GDPR.</p></section><section class="privacy-section card"><h2>5. Destinatari e infrastruttura</h2><ul><li>amministratori autorizzati del portale, limitatamente alla gestione di account, assistenza, sicurezza e statistiche dichiarate;</li><li>infrastruttura PostgreSQL e server del portale, ubicati in ${esc(p.hostingLocation||'ubicazione da configurare')};</li><li>${esc(p.emailProvider||'fornitore SMTP da configurare')}, per le sole email di servizio;</li><li>fornitore DNS dinamico, che gestisce dominio e indirizzo IP pubblico ma non riceve la banca dati degli utenti;</li><li>autorità o soggetti legittimati, solo quando previsto dalla legge.</li></ul><p>I dati non vengono venduti, diffusi pubblicamente o usati per pubblicità.</p></section><section class="privacy-section card"><h2>6. Trasferimenti fuori dallo SEE</h2><p>${esc(p.transferNote||'Non sono previsti trasferimenti diretti; verificare le condizioni dei fornitori eventualmente configurati.')}</p></section><section class="privacy-section card"><h2>7. Conservazione</h2><ul><li><b>Account, progressi e preferenze:</b> fino alla cancellazione dell’account o alla chiusura del servizio.</li><li><b>Sessioni:</b> fino a ${Number(p.sessionDays||30)} giorni, salvo logout o revoca anticipata.</li><li><b>Link di recupero:</b> fino a ${Number(p.resetTokenMinutes||30)} minuti e comunque non oltre l’uso o la scadenza.</li><li><b>Log di sicurezza e amministrazione:</b> massimo ${Number(p.auditLogDays||180)} giorni; la pulizia è automatica.</li><li><b>Backup tecnici sul server:</b> rotazione fino a ${Number(p.backupDays||30)} giorni. Eventuali copie esportate e scaricate dall’amministratore restano sotto la sua responsabilità fino alla cancellazione.</li><li><b>Dati sul dispositivo:</b> cache PWA, preferenze e prova in corso restano nel browser finché l’utente cancella i dati del sito o disinstalla l’app.</li></ul></section><section class="privacy-section card"><h2>8. Cookie e memoria del dispositivo</h2><p>Il portale usa un solo cookie tecnico di autenticazione (<code>q400_session</code>), HttpOnly, SameSite=Lax e Secure quando il sito è in HTTPS. È indispensabile per mantenere l’accesso e non viene usato per tracciare l’utente.</p><p>La PWA usa cache e memoria locale per installazione, tema, continuità della prova e sincronizzazione. Non sono presenti cookie pubblicitari, analytics di terze parti o fingerprinting. Per gli strumenti strettamente tecnici non è richiesto consenso preventivo; resta sempre dovuta questa informativa.</p></section><section class="privacy-section card"><h2>9. Diritti dell’interessato</h2><p>Puoi chiedere accesso, rettifica, cancellazione, limitazione, portabilità e, quando la base è il legittimo interesse, opporti al trattamento. Puoi aggiornare nome ed email da Account e scaricare una copia strutturata dei dati con “Esporta i miei dati”.</p><p>Per le altre richieste scrivi a ${email?`<a href="mailto:${esc(email)}?subject=Richiesta%20privacy%20Quiz%20400%20VVF">${esc(email)}</a>`:'all’indirizzo privacy configurato'}${pec?` o alla PEC <a href="mailto:${esc(pec)}">${esc(pec)}</a>`:''}. La richiesta sarà gestita nei termini previsti dal GDPR. Hai inoltre diritto di proporre reclamo al <a href="https://www.garanteprivacy.it/home" target="_blank" rel="noopener">Garante per la protezione dei dati personali</a>.</p></section><section class="privacy-section card"><h2>10. Sicurezza e aggiornamenti</h2><p>Il portale applica HTTPS tramite reverse proxy, password con hash Argon2, cookie protetti, separazione degli account, controlli di autorizzazione, limiti ai tentativi e backup. Nessuna misura elimina ogni rischio: eventuali incidenti saranno valutati e gestiti secondo gli articoli 33 e 34 GDPR.</p><p>Le modifiche sostanziali a questa informativa comportano una nuova versione e data di efficacia. La presa visione registrata in fase di iscrizione indica soltanto quale testo è stato mostrato.</p></section><footer class="privacy-footer">${amateurDisclaimerMarkup()}<p>Ultimo aggiornamento: ${esc(effective)} · versione ${esc(p.policyVersion||'—')}</p></footer></article>`;app.querySelector('[data-print-privacy]').onclick=()=>window.print();window.scrollTo({top:0,behavior:'instant'})}

const accountViewBeforePrivacy=accountView;
accountView=function(){accountViewBeforePrivacy();if(!cloudMode||!currentUser)return;const form=app.querySelector('#profileForm');form?.insertAdjacentHTML('afterend',`<section class="card account-privacy-card"><div><div class="eyebrow">Controllo dei tuoi dati</div><h2>Privacy e portabilità</h2><p class="meta">Consulta l’informativa, scarica account, statistiche e log che ti riguardano oppure usa i contatti del titolare per una richiesta di rettifica o cancellazione.</p></div><div class="quiz-actions"><a class="button primary" href="./api/account/data-export" download>Esporta i miei dati</a><a class="button ghost" href="#privacy">Informativa privacy</a></div></section>`) };

const cloudSettingsMarkupBeforePrivacy=cloudSettingsMarkup;
cloudSettingsMarkup=function(){return cloudSettingsMarkupBeforePrivacy().replace('</fieldset><fieldset class="network-settings">',`</fieldset><fieldset class="privacy-admin-settings"><legend>Privacy e GDPR</legend><div class="privacy-admin-status full" data-privacy-admin-status></div><label>Nome e cognome del titolare<input name="privacyControllerName" autocomplete="name" required></label><label>Email privacy<input name="privacyContactEmail" type="email" autocomplete="email" required></label><label>PEC del titolare<input name="privacyPecEmail" type="email"></label><label>Recapito postale (facoltativo)<input name="privacyControllerAddress"></label><label class="full">DPO/RPD, solo se formalmente nominato<input name="privacyDpoContact" placeholder="Lascia vuoto se non nominato"></label><label>Ubicazione del server<input name="privacyHostingLocation" required></label><label>Fornitore email<input name="privacyEmailProvider" required></label><label>Versione informativa<input name="privacyPolicyVersion" maxlength="40" required></label><label>Data di efficacia<input name="privacyEffectiveDate" type="date" required></label><label>Conservazione log (giorni)<input name="privacyAuditLogDays" type="number" min="30" max="730" required></label><label>Rotazione backup server (giorni)<input name="privacyBackupDays" type="number" min="1" max="365" required></label><label class="full">Nota sui trasferimenti fuori dallo SEE<textarea name="privacyTransferNote" required></textarea></label><p class="meta full">Se cambi sostanzialmente finalità, destinatari o tempi, assegna una nuova versione e aggiorna la data. Il testo pubblico viene generato automaticamente da questi dati.</p><a class="button ghost full" href="#privacy" target="_blank" rel="noopener">Anteprima informativa pubblica</a></fieldset><fieldset class="network-settings">`)};

const loadCloudSettingsBeforePrivacy=loadCloudSettings;
loadCloudSettings=async function(){await loadCloudSettingsBeforePrivacy();const form=app.querySelector('#cloudSettingsForm');if(!form)return;try{const s=await cloudApi('./api/admin/settings');for(const [name,value] of Object.entries({privacyControllerName:s.privacyControllerName,privacyControllerAddress:s.privacyControllerAddress,privacyContactEmail:s.privacyContactEmail,privacyPecEmail:s.privacyPecEmail,privacyDpoContact:s.privacyDpoContact,privacyHostingLocation:s.privacyHostingLocation,privacyEmailProvider:s.privacyEmailProvider,privacyTransferNote:s.privacyTransferNote,privacyPolicyVersion:s.privacyPolicyVersion,privacyEffectiveDate:s.privacyEffectiveDate,privacyAuditLogDays:s.privacyAuditLogDays,privacyBackupDays:s.privacyBackupDays})){if(form.elements[name])form.elements[name].value=value??''}const status=form.querySelector('[data-privacy-admin-status]');status.className=`privacy-admin-status ${s.privacyComplete?'success':'warning'} full`;status.innerHTML=s.privacyComplete?'<b>Informativa pubblica completa</b><span>Identità e contatto del titolare sono configurati.</span>':'<b>Informativa da completare</b><span>Inserisci nome e email del titolare prima di aprire le registrazioni.</span>'}catch(error){const status=form.querySelector('[data-privacy-admin-status]');if(status)status.textContent=error.message}};

