const logicTopicFor=question=>classifyLogicQuestion(question||{});
const activeLogicPlan=()=>{const preset=activeExamPreset(),rawPlan=preset?.plan||examConfig.examPlan||DEFAULT_EXAM_PLAN;return normalizeExamLogicPlan(preset?.logicPlan||examConfig.logicPlan||DEFAULT_LOGIC_PLAN,rawPlan)};
const logicQuestionPool=topicId=>allQuestions().filter(question=>isLogicQuestion(question)&&logicTopicFor(question)===topicId);
const logicTopicName=topicId=>logicTopics.find(topic=>topic.id===topicId)?.name||'Logica mista';
const logicPlanSummary=plan=>logicTopics.filter(topic=>(plan?.[topic.id]||0)>0).map(topic=>`${plan[topic.id]} ${topic.shortName}`).join(' · ');

function logicTopicMetrics(topicId){
 const questions=logicQuestionPool(topicId),counts={known:0,review:0,unknown:0,unanswered:0};let attempts=0,correctAttempts=0,wrongAttempts=0,skipped=0;
 for(const question of questions){const progress=progressFor(question.id),status=['known','review','unknown'].includes(progress.status)?progress.status:'unanswered';counts[status]++;attempts+=Number(progress.attempts)||0;correctAttempts+=Number(progress.correct)||0;wrongAttempts+=Number(progress.wrong)||0;skipped+=Number(progress.skipped)||0}
 const answered=counts.known+counts.review+counts.unknown,graded=correctAttempts+wrongAttempts;
 return{category:'logica',logicTopic:topicId,total:questions.length,...counts,answered,toDo:counts.unanswered,attempts,correctAttempts,wrongAttempts,skipped,coverage:questions.length?Math.round(answered/questions.length*100):0,accuracy:graded?Math.round(correctAttempts/graded*100):null};
}

function logicTopicsMarkup(){
 return `<section class="logic-topic-section"><div class="section-head"><div><div class="eyebrow">Allenamento mirato</div><h2>Tipi di quiz di Logica</h2></div></div><p class="meta logic-topic-help">Logica raccoglie tutti i quesiti logici in un’unica materia. Scegli il tipo da allenare, controlla le statistiche e riprendi dalle domande non ancora fatte.</p><div class="logic-topic-grid">${logicTopics.map(topic=>{const metrics=logicTopicMetrics(topic.id);return `<article class="card logic-topic-card"><div class="logic-topic-card-head"><div><h3>${esc(topic.name)}</h3><p>${esc(topic.description)}</p></div><span>${metrics.total.toLocaleString('it')} quiz</span></div><div class="logic-topic-mini"><span class="known"><b>${metrics.known}</b> le so</span><span class="review"><b>${metrics.review}</b> ripeti</span><span class="unknown"><b>${metrics.unknown}</b> non so</span><span class="unanswered"><b>${metrics.toDo}</b> da fare</span></div><div class="progress"><span style="width:${metrics.coverage}%"></span></div><div class="logic-topic-footer"><small>${metrics.accuracy===null?'Precisione da calcolare':`${metrics.accuracy}% precisione`}</small><a class="button ghost compact" href="#logic-topic/${topic.id}">Apri</a></div></article>`}).join('')}</div></section>`;
}

const categoryViewBeforeLogicTopics=categoryView;
categoryView=function(id){
 if(id!=='logica')return categoryViewBeforeLogicTopics(id);
 nav('categories');const category=categories.find(item=>item.id==='logica'),metrics=categoryMetrics('logica'),sessions=categorySessions('logica');
 app.innerHTML=`<div class="section-head"><div><div class="eyebrow">${metrics.answered}/${metrics.total} classificate</div><h1>${esc(category.name)}</h1></div></div>${pieChartMarkup(metrics,'Statistiche Logica')}${logicTopicsMarkup()}<div class="card"><h2>Percorso completo di logica</h2><p>Segue l’ordine della banca e comprende tutte le sottosezioni. Puoi interrompere e riprendere dalla prima domanda non fatta.</p><div class="quiz-actions"><button class="primary" data-resume>${metrics.toDo<metrics.total?'Riprendi dalla prima non fatta':'Inizia dalla domanda 1'}</button><button class="ghost" data-start>Ricomincia dalla n. 1</button></div></div><div class="card guided-card"><div class="mode-title"><span class="mode-icon">✓</span><div><h2>Quiz guidato di logica</h2><p>Esito, risposta corretta e spiegazione subito dopo la conferma.</p></div></div><div class="guided-options"><button class="secondary" data-guided="15">15 domande</button><button class="secondary" data-guided="30">30 domande</button><button class="secondary" data-guided="50">50 domande</button></div></div><div class="filter-row"><button class="status-chip known" data-filter="known">Le so (${metrics.known})</button><button class="status-chip review" data-filter="review">Da ripetere (${metrics.review})</button><button class="status-chip unknown" data-filter="unknown">Non le so (${metrics.unknown})</button><button class="status-chip unanswered" data-filter="unanswered">Da fare (${metrics.toDo})</button></div><div class="section-head"><h2>Risultati dei quiz di Logica</h2></div>${sessionHistoryMarkup(sessions,'Non hai ancora completato quiz di logica.')}`;
 app.querySelector('[data-resume]').onclick=()=>startCategory('logica','resume');app.querySelector('[data-start]').onclick=()=>startCategory('logica','start');app.querySelectorAll('[data-guided]').forEach(button=>button.onclick=()=>startGuided('logica',+button.dataset.guided));app.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>startFiltered('logica',button.dataset.filter));
};

function logicTopicView(topicId){
 const topic=logicTopics.find(item=>item.id===topicId);if(!topic)return categoryView('logica');nav('categories');const metrics=logicTopicMetrics(topic.id),sessions=userState().sessions.filter(session=>session.logicTopic===topic.id);
 app.innerHTML=`<a class="back-link" href="#category/logica">← Tutte le sottosezioni</a><div class="section-head"><div><div class="eyebrow">Logica · ${metrics.total.toLocaleString('it')} domande</div><h1>${esc(topic.name)}</h1></div></div><p class="logic-topic-description">${esc(topic.description)}</p>${pieChartMarkup(metrics,`Statistiche ${topic.name}`)}<div class="card"><h2>Percorso ordinato</h2><p>Le domande restano nell’ordine della banca. Riprendi dalla prima non fatta oppure ricomincia dall’inizio.</p><div class="quiz-actions"><button class="primary" data-topic-resume>Riprendi dalle non fatte</button><button class="ghost" data-topic-start>Ricomincia dalla n. 1</button></div></div><div class="card guided-card"><div class="mode-title"><span class="mode-icon">✓</span><div><h2>Quiz guidato</h2><p>Risposta, soluzione e spiegazione dopo la conferma.</p></div></div><div class="guided-options"><button class="secondary" data-topic-guided="15">15 domande</button><button class="secondary" data-topic-guided="30">30 domande</button><button class="secondary" data-topic-guided="50">50 domande</button></div></div><div class="filter-row"><button class="status-chip known" data-topic-filter="known">Le so (${metrics.known})</button><button class="status-chip review" data-topic-filter="review">Da ripetere (${metrics.review})</button><button class="status-chip unknown" data-topic-filter="unknown">Non le so (${metrics.unknown})</button><button class="status-chip unanswered" data-topic-filter="unanswered">Da fare (${metrics.toDo})</button></div><div class="section-head"><h2>Risultati di ${esc(topic.name)}</h2></div>${sessionHistoryMarkup(sessions,'Non hai ancora completato quiz in questa sottosezione.')}`;
 app.querySelector('[data-topic-resume]').onclick=()=>startLogicTopic(topic.id,'resume');app.querySelector('[data-topic-start]').onclick=()=>startLogicTopic(topic.id,'start');app.querySelectorAll('[data-topic-guided]').forEach(button=>button.onclick=()=>startLogicGuided(topic.id,+button.dataset.topicGuided));app.querySelectorAll('[data-topic-filter]').forEach(button=>button.onclick=()=>startLogicFiltered(topic.id,button.dataset.topicFilter));
}

function startLogicTopic(topicId,mode){const pool=logicQuestionPool(topicId);let index=0;if(mode==='resume'){const found=pool.findIndex(question=>progressFor(question.id).status==='unanswered');index=found<0?0:found}if(!pool.length)return notify('Nessuna domanda in questa sottosezione');quiz={kind:'study',pool,index,history:{},selected:null,sourceCategory:'logica',sourceLogicTopic:topicId};renderQuestion()}
function startLogicGuided(topicId,count){const seed=createQuizSeed(`guided-logic-${topicId}`),source=logicQuestionPool(topicId),selected=takeRotating(source,count,'guided-logic-topic',topicId,seed),pool=shuffleWithSeed(selected,`${seed}|questions`).map(question=>shuffleGuidedAnswers(question,`${seed}|answers|${question.id}`));if(!pool.length)return notify('Nessuna domanda in questa sottosezione');persist();quiz={kind:'guided',pool,index:0,history:{},selected:null,sourceCategory:'logica',sourceLogicTopic:topicId,generatedAt:new Date().toISOString()};renderGuided()}
function startLogicFiltered(topicId,status){const bank=logicQuestionPool(topicId),cursorCategory=`logica:${topicId}`,{key,cursor}=subjectFilterCursor(cursorCategory,status,bank),pool=selectOrderedQuestions(bank,cursor,question=>progressFor(question.id).status===status);if(!pool.length)return notify('Nessuna domanda in questo gruppo');quiz={kind:'study',pool,index:0,history:{},selected:null,filter:status,sourceCategory:'logica',sourceLogicTopic:topicId,subjectCursorKey:key};persist();renderQuestion()}

rememberSubjectCursor=function(question){if(!quiz?.subjectCursorKey)return;const bank=allQuestions().filter(item=>(!quiz.sourceCategory||macroCategoryId(item.category)===quiz.sourceCategory)&&(!quiz.sourceLogicTopic||logicTopicFor(item)===quiz.sourceLogicTopic)),position=bank.findIndex(item=>String(item.id)===String(question.id));if(position<0)return;userState().categoryCursor[quiz.subjectCursorKey]={version:2,lastId:String(question.id),position,size:bank.length,updatedAt:new Date().toISOString()}};

recordSession=function(type,rows,extra={}){const correct=rows.filter(row=>row.correct).length,wrong=rows.filter(row=>!row.correct&&!row.blank).length,blank=rows.filter(row=>row.blank).length,answered=correct+wrong,perCategory=rowsByCategory(rows),category=Object.keys(perCategory).length===1?Object.keys(perCategory)[0]:null,topicValues=[...new Set(rows.map(row=>{const question=row.q||row;return isLogicQuestion(question)?logicTopicFor(question):null}).filter(Boolean))],logicTopic=category==='logica'&&topicValues.length===1?topicValues[0]:null,review=rows.map(row=>{const question=row.q||row,isLogic=isLogicQuestion(question);return{id:String(question.id),category:macroCategoryId(question.category||row.category)||null,logicTopic:isLogic?logicTopicFor(question):null,choiceText:row.blank?null:String(question.answers?.[row.choice]??''),correctText:String(question.answers?.[question.correct]??''),blank:Boolean(row.blank),correct:Boolean(row.correct)}}),session={id:crypto.randomUUID(),type,at:new Date().toISOString(),correct,wrong,blank,score:scoreFor(correct,wrong),accuracy:answered?Math.round(correct/answered*100):null,questionCount:rows.length,category,logicTopic,perCategory,review,...extra},sessions=userState().sessions;sessions.push(session);sessions.filter(item=>Array.isArray(item.review)).slice(0,-5).forEach(item=>delete item.review);return session};

finishStudy=function(){if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.pool.map(question=>quiz.history[question.id]||{choice:null,blank:true,correct:false,q:question}),session=recordSession('study',rows,{filter:quiz.filter||null,logicTopic:quiz.sourceLogicTopic||null});persist();app.innerHTML=resultCard('Quiz completato',session.correct,session.wrong,session.blank,'<a class="button primary" href="#categories">Materie</a><a class="button ghost" href="#stats">Progressi</a>')+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})};

finishGuided=function(reason='completed'){clearInterval(timerHandle);if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.mode==='guided-exam'?guidedResultRows(quiz):quiz.pool.map(question=>quiz.history[question.id]||{choice:null,blank:true,correct:false,q:question}),timed=isTimedFortyQuiz();if(timed){for(const row of rows)userState().progress[row.q.id]=applyLearningOutcome(progressFor(row.q.id),row);updateDeepLearningFromRows(rows,'guided-exam')}const session=recordSession(quiz.mode==='guided-exam'?'guided-exam':'guided',rows,{timedOut:reason==='timeout',generatedAt:quiz.generatedAt,deepLearning:Boolean(quiz.deepLearning),logicTopic:quiz.sourceLogicTopic||null}),deepResult=deepLearningResultMarkup(rows,'guided-exam');timed?clearActiveQuiz():persist();app.innerHTML=resultCard(reason==='timeout'?'Tempo scaduto · prova guidata conclusa':'Prova guidata completata',session.correct,session.wrong,session.blank,'<a class="button primary" href="#simulation">Nuova prova</a><a class="button ghost" href="#stats">Statistiche</a>')+deepResult+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})};

function selectFortyQuestionSet(seed,mode){
 const selected=[];
 for(const [category,count] of examPlan()){
  if(category!=='logica'){selected.push(...takePersonalizedForty(allQuestions().filter(question=>question.category===category),count,category,seed,mode));continue}
  const distribution=activeLogicPlan(),logicQuestions=allQuestions().filter(isLogicQuestion);
  selected.push(...selectLogicQuestionsByPlan(logicQuestions,distribution,(source,topicCount,topic)=>takePersonalizedForty(source,topicCount,`logica:${topic.id}`,seed,mode)))
 }
 if(selected.length!==40)throw Error(`La configurazione ha prodotto ${selected.length} domande invece di 40`);
 return selected;
}

startGuidedExam=function(){try{const exposureBefore=fortyExposureSnapshot(),seed=createQuizSeed('guided-exam'),deepLearning=deepLearningSettings().enabled,selected=selectFortyQuestionSet(seed,'guided'),pool=shuffleWithSeed(selected,`${seed}|questions`).map(question=>shuffleGuidedAnswers(question,`${seed}|answers|${question.id}`));userState().examCount++;persist();quiz={kind:'guided',mode:'guided-exam',deepLearning,pool,index:0,history:{},pendingAnswers:Array(pool.length).fill(null),selected:null,exposureBefore,remaining:EXAM_SECONDS,startedAt:Date.now(),generatedAt:new Date().toISOString()};saveActiveQuiz();renderGuided();startFortyMinuteTimer()}catch(error){notify(error.message)}};
startExam=function(){try{const exposureBefore=fortyExposureSnapshot(),seed=createQuizSeed('exam'),deepLearning=deepLearningSettings().enabled,selected=selectFortyQuestionSet(seed,'official'),pool=shuffleWithSeed(selected,`${seed}|questions`);userState().examCount++;persist();quiz={kind:'exam',deepLearning,pool,index:0,answers:Array(pool.length).fill(null),selected:null,exposureBefore,remaining:EXAM_SECONDS,startedAt:Date.now(),generatedAt:new Date().toISOString()};saveActiveQuiz();renderQuestion();startFortyMinuteTimer()}catch(error){notify(error.message)}};

deepLearningTrackSummary=function(){let mastered=0,total=0,cycles=[];for(const [category,count] of examPlan()){if(category==='logica'){const distribution=activeLogicPlan();for(const topic of logicTopics){if(!(distribution[topic.id]||0))continue;const source=logicQuestionPool(topic.id),bucket=fortyExposureBucket(`logica:${topic.id}`,source);mastered+=source.filter(question=>progressFor(question.id).status==='known').length;total+=source.length;cycles.push(Number(bucket.cycle)||1)}continue}const source=allQuestions().filter(question=>question.category===category),bucket=fortyExposureBucket(category,source);mastered+=source.filter(question=>progressFor(question.id).status==='known').length;total+=source.length;cycles.push(Number(bucket.cycle)||1)}return{mastered,total,cycle:cycles.length?Math.min(...cycles):1}};

function logicDistributionFields(plan,prefix){return `<fieldset class="logic-distribution"><legend>Distribuzione delle domande di Logica</legend><p>Decidi esattamente da quali sottosezioni pescare. La somma deve coincidere con il numero di domande impostato nella voce Logica.</p><div class="logic-distribution-grid">${logicTopics.map(topic=>`<label>${esc(topic.shortName)}<input type="number" min="0" max="40" step="1" name="${prefix}${topic.id}" value="${plan[topic.id]||0}"></label>`).join('')}</div><div class="logic-distribution-total">Sottosezioni: <strong data-logic-total>${logicPlanTotal(plan)}</strong> / <strong data-logic-target></strong> Logica</div><button class="ghost compact" type="button" data-balance-logic>Distribuisci automaticamente</button></fieldset>`}

presetManagerMarkup=function(){const state=userState(),active=activeExamPreset(),rawPlan=active?.plan||examConfig.examPlan||DEFAULT_EXAM_PLAN,plan=normalizePlan(rawPlan),logicPlan=normalizeExamLogicPlan(active?.logicPlan||examConfig.logicPlan||DEFAULT_LOGIC_PLAN,rawPlan);return `<section class="card preset-manager"><div class="preset-title"><div><div class="eyebrow">Preferenze del tuo account</div><h2>Configurazioni quiz salvate</h2></div><span class="preset-active-badge">${active?esc(active.name):'Predefinita'}</span></div><p class="meta">Salva più composizioni da 40 domande. Logica è una sola materia: al suo interno scegli quanti quesiti prendere da ciascun tipo.</p><form id="personalExamPreset" class="personal-preset-form"><input type="hidden" name="presetId" value="${active?esc(active.id):''}"><label class="preset-name-field">Nome configurazione<input name="presetName" maxlength="40" placeholder="Es. Prova ufficiale" value="${active?esc(active.name):''}" required></label><div class="preset-fields">${categories.map(category=>`<label>${esc(category.name)}<input data-plan-category type="number" min="0" max="40" step="1" name="${category.id}" value="${plan[category.id]||0}"></label>`).join('')}</div><div class="settings-total">Totale: <strong data-preset-total>${planTotal(plan)}</strong>/40</div>${logicDistributionFields(logicPlan,'logicTopic-')}<div class="quiz-actions"><button class="primary" type="submit">${active?'Aggiorna e usa':'Salva e usa'}</button><button class="ghost" type="button" data-new-preset>Nuova configurazione</button><button class="ghost" type="button" data-use-default ${active?'':'disabled'}>Usa predefinita</button></div></form>${state.examPresets.length?`<div class="saved-presets"><h3>Le tue configurazioni</h3>${state.examPresets.map(item=>{const itemPlan=normalizePlan(item.plan),itemLogic=normalizeExamLogicPlan(item.logicPlan,item.plan);return `<div class="preset-row ${item.id===state.activeExamPresetId?'active':''}"><div><b>${esc(item.name)}</b><span>${esc(planSummary(item.plan))}</span><small>Logica: ${esc(logicPlanSummary(itemLogic))}</small></div><div class="preset-row-actions"><button class="ghost compact" data-use-preset="${item.id}" ${item.id===state.activeExamPresetId?'disabled':''}>${item.id===state.activeExamPresetId?'In uso':'Usa'}</button><button class="ghost compact danger-text" data-delete-preset="${item.id}">Elimina</button></div></div>`}).join('')}</div>`:''}</section>`};

bindPresetManager=function(){const form=app.querySelector('#personalExamPreset');if(!form)return;const planInputs=[...form.querySelectorAll('[data-plan-category]')],logicInputs=[...form.querySelectorAll('.logic-distribution-grid input')],mainTotal=()=>planInputs.reduce((sum,input)=>sum+(Number(input.value)||0),0),logicTotal=()=>logicInputs.reduce((sum,input)=>sum+(Number(input.value)||0),0),logicTarget=()=>Number(form.elements.logica.value)||0,refresh=()=>{app.querySelector('[data-preset-total]').textContent=mainTotal();form.querySelector('[data-logic-total]').textContent=logicTotal();form.querySelector('[data-logic-target]').textContent=logicTarget();form.querySelector('.logic-distribution').classList.toggle('invalid',logicTotal()!==logicTarget())};[...planInputs,...logicInputs].forEach(input=>input.addEventListener('input',refresh));form.querySelector('[data-balance-logic]').onclick=()=>{const balanced=defaultLogicPlan(logicTarget());logicInputs.forEach(input=>input.value=balanced[input.name.replace('logicTopic-','')]||0);refresh()};refresh();form.onsubmit=event=>{event.preventDefault();const data=new FormData(form),name=String(data.get('presetName')).trim(),id=String(data.get('presetId')||''),plan=normalizePlan(Object.fromEntries(categories.map(category=>[category.id,data.get(category.id)]))),logicPlan=Object.fromEntries(logicTopics.map(topic=>[topic.id,Math.max(0,Math.floor(Number(data.get(`logicTopic-${topic.id}`))||0))])),state=userState();if(!name)return notify('Inserisci un nome per la configurazione');if(planTotal(plan)!==40)return notify(`Il totale deve essere 40: ora è ${planTotal(plan)}`);if(logicPlanTotal(logicPlan)!==plan.logica)return notify(`Distribuisci esattamente ${plan.logica} domande tra le sottosezioni di Logica`);if(state.examPresets.some(item=>item.id!==id&&item.name.toLowerCase()===name.toLowerCase()))return notify('Esiste già una configurazione con questo nome');const existing=state.examPresets.find(item=>item.id===id);if(existing){existing.name=name;existing.plan=plan;existing.logicPlan=logicPlan;existing.updatedAt=new Date().toISOString();state.activeExamPresetId=existing.id}else{const created={id:crypto.randomUUID(),name,plan,logicPlan,createdAt:new Date().toISOString()};state.examPresets.push(created);state.activeExamPresetId=created.id}saveUsers();notify('Configurazione salvata');simulationView()};app.querySelector('[data-new-preset]').onclick=()=>{form.elements.presetId.value='';form.elements.presetName.value='';form.querySelector('[type="submit"]').textContent='Salva e usa';form.elements.presetName.focus()};app.querySelector('[data-use-default]').onclick=()=>{userState().activeExamPresetId=null;saveUsers();notify('Configurazione predefinita attivata');simulationView()};app.querySelectorAll('[data-use-preset]').forEach(button=>button.onclick=()=>{userState().activeExamPresetId=button.dataset.usePreset;saveUsers();notify('Configurazione attivata');simulationView()});app.querySelectorAll('[data-delete-preset]').forEach(button=>button.onclick=()=>{const state=userState(),item=state.examPresets.find(entry=>entry.id===button.dataset.deletePreset);if(!item||!confirm(`Eliminare la configurazione “${item.name}”?`))return;state.examPresets=state.examPresets.filter(entry=>entry.id!==item.id);if(state.activeExamPresetId===item.id)state.activeExamPresetId=null;saveUsers();notify('Configurazione eliminata');simulationView()})};

const settingsViewBeforeLogicDistribution=settingsView;
