const SCIENCE_TOPIC_CATEGORIES=new Set(Object.keys(subjectTopics));
const subjectTopicFor=question=>classifySubjectQuestion(question||{});
const subjectQuestionPool=(categoryId,topicId)=>allQuestions().filter(question=>question.category===categoryId&&subjectTopicFor(question)===topicId);
const subjectTopicName=(categoryId,topicId)=>topicDefinition(categoryId,topicId)?.name||`${catName(categoryId)} generale`;

function subjectTopicMetrics(categoryId,topicId){
 const questions=subjectQuestionPool(categoryId,topicId),counts={known:0,review:0,unknown:0,unanswered:0};let attempts=0,correctAttempts=0,wrongAttempts=0,skipped=0;
 for(const question of questions){const progress=progressFor(question.id),status=['known','review','unknown'].includes(progress.status)?progress.status:'unanswered';counts[status]++;attempts+=Number(progress.attempts)||0;correctAttempts+=Number(progress.correct)||0;wrongAttempts+=Number(progress.wrong)||0;skipped+=Number(progress.skipped)||0}
 const answered=counts.known+counts.review+counts.unknown,graded=correctAttempts+wrongAttempts;
 return{category:categoryId,subjectTopic:topicId,total:questions.length,...counts,answered,toDo:counts.unanswered,attempts,correctAttempts,wrongAttempts,skipped,coverage:questions.length?Math.round(answered/questions.length*100):0,accuracy:graded?Math.round(correctAttempts/graded*100):null};
}

function subjectTopicsMarkup(categoryId){
 const category=categories.find(item=>item.id===categoryId),topics=subjectTopics[categoryId]||[];
 return `<section class="logic-topic-section subject-topic-section"><div class="section-head"><div><div class="eyebrow">Allenamento mirato</div><h2>Settori di ${esc(category.name)}</h2></div></div><p class="meta logic-topic-help">Scegli il settore che vuoi approfondire. Ogni scheda mostra i tuoi progressi e ti permette di riprendere dalle domande ancora da fare.</p><div class="logic-topic-grid">${topics.map(topic=>{const metrics=subjectTopicMetrics(categoryId,topic.id);return `<article class="card logic-topic-card"><div class="logic-topic-card-head"><div><h3>${esc(topic.name)}</h3><p>${esc(topic.description)}</p></div><span>${metrics.total.toLocaleString('it')} quiz</span></div><div class="logic-topic-mini"><span class="known"><b>${metrics.known}</b> le so</span><span class="review"><b>${metrics.review}</b> ripeti</span><span class="unknown"><b>${metrics.unknown}</b> non so</span><span class="unanswered"><b>${metrics.toDo}</b> da fare</span></div><div class="progress"><span style="width:${metrics.coverage}%"></span></div><div class="logic-topic-footer"><small>${metrics.accuracy===null?'Precisione da calcolare':`${metrics.accuracy}% precisione`}</small><a class="button ghost compact" href="#subject-topic/${categoryId}:${topic.id}">Apri</a></div></article>`}).join('')}</div></section>`;
}

const categoryViewBeforeSubjectTopics=categoryView;
categoryView=function(id){
 if(!SCIENCE_TOPIC_CATEGORIES.has(id))return categoryViewBeforeSubjectTopics(id);
 nav('categories');const category=categories.find(item=>item.id===id),metrics=categoryMetrics(id),sessions=categorySessions(id);
 app.innerHTML=`<div class="section-head"><div><div class="eyebrow">${metrics.answered}/${metrics.total} classificate</div><h1>${esc(category.name)}</h1></div></div>${pieChartMarkup(metrics,`Statistiche ${category.name}`)}${subjectTopicsMarkup(id)}<div class="card"><h2>Percorso completo di ${esc(category.name)}</h2><p>Segue l’ordine originale della banca e comprende tutti i settori. Puoi interrompere e riprendere dalla prima domanda non fatta.</p><div class="quiz-actions"><button class="primary" data-resume>${metrics.toDo<metrics.total?'Riprendi dalla prima non fatta':'Inizia dalla domanda 1'}</button><button class="ghost" data-start>Ricomincia dalla n. 1</button></div></div><div class="card guided-card"><div class="mode-title"><span class="mode-icon">✓</span><div><h2>Quiz guidato di ${esc(category.name)}</h2><p>Esito, risposta corretta e spiegazione subito dopo ogni risposta.</p></div></div><div class="guided-options"><button class="secondary" data-guided="15">15 domande</button><button class="secondary" data-guided="30">30 domande</button><button class="secondary" data-guided="50">50 domande</button></div></div><div class="filter-row"><button class="status-chip known" data-filter="known">Le so (${metrics.known})</button><button class="status-chip review" data-filter="review">Da ripetere (${metrics.review})</button><button class="status-chip unknown" data-filter="unknown">Non le so (${metrics.unknown})</button><button class="status-chip unanswered" data-filter="unanswered">Da fare (${metrics.toDo})</button></div><div class="section-head"><h2>Risultati dei quiz di ${esc(category.name)}</h2></div>${sessionHistoryMarkup(sessions,`Non hai ancora completato quiz di ${category.name}.`)}`;
 app.querySelector('[data-resume]').onclick=()=>startCategory(id,'resume');app.querySelector('[data-start]').onclick=()=>startCategory(id,'start');app.querySelectorAll('[data-guided]').forEach(button=>button.onclick=()=>startGuided(id,+button.dataset.guided));app.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>startFiltered(id,button.dataset.filter));
};

function topicGuidedCounts(total){return[...new Set([15,Math.min(30,total),Math.min(50,total)].filter(count=>count>0&&count<=total))]}

function subjectTopicView(param){
 const [categoryId,topicId]=decodeURIComponent(String(param||'')).split(':'),topic=topicDefinition(categoryId,topicId),category=categories.find(item=>item.id===categoryId);if(!category||!topic)return categoryView(categoryId);
 nav('categories');const metrics=subjectTopicMetrics(categoryId,topicId),sessions=userState().sessions.filter(session=>session.category===categoryId&&session.subjectTopic===topicId),guidedCounts=topicGuidedCounts(metrics.total);
 app.innerHTML=`<a class="back-link" href="#category/${categoryId}">← Tutti i settori</a><div class="section-head"><div><div class="eyebrow">${esc(category.name)} · ${metrics.total.toLocaleString('it')} domande</div><h1>${esc(topic.name)}</h1></div></div><p class="logic-topic-description">${esc(topic.description)}</p>${pieChartMarkup(metrics,`Statistiche ${topic.name}`)}<div class="card"><h2>Percorso ordinato</h2><p>Le domande restano nell’ordine della banca. Riprendi dalla prima non fatta oppure ricomincia dall’inizio.</p><div class="quiz-actions"><button class="primary" data-subject-topic-resume>Riprendi dalle non fatte</button><button class="ghost" data-subject-topic-start>Ricomincia dalla n. 1</button></div></div><div class="card guided-card"><div class="mode-title"><span class="mode-icon">✓</span><div><h2>Quiz guidato</h2><p>Risposta, soluzione e spiegazione dopo la conferma.</p></div></div><div class="guided-options">${guidedCounts.map(count=>`<button class="secondary" data-subject-topic-guided="${count}">${count===metrics.total?'Tutte le':count} ${count===metrics.total?'domande':'domande'}</button>`).join('')}</div></div><div class="filter-row"><button class="status-chip known" data-subject-topic-filter="known">Le so (${metrics.known})</button><button class="status-chip review" data-subject-topic-filter="review">Da ripetere (${metrics.review})</button><button class="status-chip unknown" data-subject-topic-filter="unknown">Non le so (${metrics.unknown})</button><button class="status-chip unanswered" data-subject-topic-filter="unanswered">Da fare (${metrics.toDo})</button></div><div class="section-head"><h2>Risultati di ${esc(topic.name)}</h2></div>${sessionHistoryMarkup(sessions,'Non hai ancora completato quiz in questo settore.')}`;
 app.querySelector('[data-subject-topic-resume]').onclick=()=>startSubjectTopic(categoryId,topicId,'resume');app.querySelector('[data-subject-topic-start]').onclick=()=>startSubjectTopic(categoryId,topicId,'start');app.querySelectorAll('[data-subject-topic-guided]').forEach(button=>button.onclick=()=>startSubjectTopicGuided(categoryId,topicId,+button.dataset.subjectTopicGuided));app.querySelectorAll('[data-subject-topic-filter]').forEach(button=>button.onclick=()=>startSubjectTopicFiltered(categoryId,topicId,button.dataset.subjectTopicFilter));
}

function startSubjectTopic(categoryId,topicId,mode){const pool=subjectQuestionPool(categoryId,topicId);let index=0;if(mode==='resume'){const found=pool.findIndex(question=>progressFor(question.id).status==='unanswered');index=found<0?0:found}if(!pool.length)return notify('Nessuna domanda in questo settore');quiz={kind:'study',pool,index,history:{},selected:null,sourceCategory:categoryId,sourceSubjectTopic:topicId};renderQuestion()}
function startSubjectTopicGuided(categoryId,topicId,count){const seed=createQuizSeed(`guided-${categoryId}-${topicId}`),source=subjectQuestionPool(categoryId,topicId),selected=takeRotating(source,Math.min(count,source.length),'guided-subject-topic',`${categoryId}:${topicId}`,seed),pool=shuffleWithSeed(selected,`${seed}|questions`).map(question=>shuffleGuidedAnswers(question,`${seed}|answers|${question.id}`));if(!pool.length)return notify('Nessuna domanda in questo settore');persist();quiz={kind:'guided',pool,index:0,history:{},selected:null,sourceCategory:categoryId,sourceSubjectTopic:topicId,generatedAt:new Date().toISOString()};renderGuided()}
