 app.querySelectorAll('[data-tutor-duration]').forEach(button=>button.onclick=()=>{state.tutorDuration=Number(button.dataset.tutorDuration);saveUsers();tutorView()});app.querySelector('[data-start-tutor]')?.addEventListener('click',()=>startTutorTraining());app.querySelectorAll('[data-tutor-track]').forEach(button=>button.onclick=()=>startTutorTraining(button.dataset.tutorTrack));
