home=function(){homeBeforeStudyPaths();const quick=app.querySelector('.quick-grid');if(quick&&!quick.querySelector('[href="#paths"]'))quick.insertAdjacentHTML('afterbegin','<a class="card quick accent" href="#paths"><b>Percorsi di studio</b><span>Lezioni, immagini e verifiche per argomento</span></a>');const actions=app.querySelector('.hero-actions');if(actions&&!actions.querySelector('[href="#paths"]'))actions.insertAdjacentHTML('beforeend','<a class="button ghost light" href="#paths">Percorsi di studio</a>')};
const statsViewBeforeStudyPaths=statsView;
statsView=function(){statsViewBeforeStudyPaths();const summary=studyProgressSummary(userState(),studyPathVisibility()),target=app.querySelector('.mastery-summary');target?.insertAdjacentHTML('beforebegin',`<section class="card study-stat-card"><div><div class="eyebrow">Percorsi di studio</div><h2>${summary.percent}% completato</h2><p>${summary.completed} lezioni completate, ${summary.started} in corso, ${summary.total-summary.completed-summary.started} da iniziare.</p></div><a class="button ghost" href="#paths">Apri i percorsi</a></section>`)};
const settingsViewBeforeStudyPaths=settingsView;
settingsView=function(){settingsViewBeforeStudyPaths();if(currentUser?.role!=='admin')return;const visibility=studyPathVisibility(),section=document.createElement('form');section.className='card study-path-settings';section.innerHTML=`<div class="eyebrow">Contenuti didattici</div><h2>Percorsi di studio</h2><p class="meta">Scegli quali percorsi rendere visibili agli utenti. Il pacchetto contiene ${allStudyResources.length} lezioni con documenti e schede visuali; i progressi restano separati per account.</p><div class="study-path-settings-list">${studyPaths.map(path=>`<label class="study-path-setting"><input type="checkbox" name="${path.id}" ${visibility[path.id]?'checked':''}><span>${esc(path.title)}</span></label>`).join('')}</div><div class="quiz-actions"><button class="primary" type="submit">Salva percorsi visibili</button><a class="button ghost" href="#paths">Anteprima</a></div>`;app.append(section);section.onsubmit=event=>{event.preventDefault();examConfig={...examConfig,studyPathVisibility:Object.fromEntries(studyPaths.map(path=>[path.id,Boolean(section.elements[path.id]?.checked)]))};localStorage.setItem(CONFIG,JSON.stringify(examConfig));saveUsers();notify('Visibilità dei percorsi aggiornata')}};
let dailyChallengeDraftTimer=null,dailyChallengeReminderTimer=null,dailyChallengeReminderCheckBusy=false;

const formatChallengeDate=value=>{const [year,month,day]=String(value||'').split('-').map(Number);return year&&month&&day?new Date(year,month-1,day).toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'}):String(value||'')};
const formatChallengeDuration=seconds=>`${Math.floor((Number(seconds)||0)/60)} min ${String((Number(seconds)||0)%60).padStart(2,'0')} s`;

function challengeCompositionMarkup(composition){const plan=composition?.examPlan||DEFAULT_EXAM_PLAN;return EXAM_ORDER.filter(id=>Number(plan[id])>0).map(id=>`<span><b>${Number(plan[id])}</b> ${esc(catName(id))}</span>`).join('')}

function openDailyChallengeReminder(data,moment){document.querySelector('[data-daily-challenge-reminder]')?.remove();const active=data.status==='active',participants=Number(data.leaderboard?.participants||0),overlay=document.createElement('div');overlay.className='install-dialog-backdrop daily-challenge-reminder-backdrop';overlay.dataset.dailyChallengeReminder='';overlay.innerHTML=`<section class="card install-dialog daily-challenge-reminder" role="dialog" aria-modal="true" aria-labelledby="dailyReminderTitle"><div class="daily-reminder-icon" aria-hidden="true">★</div><div class="eyebrow">Promemoria della ${esc(moment.label)}</div><h2 id="dailyReminderTitle">${active?'La tua Sfida del giorno è ancora in corso':'Hai provato la Sfida del giorno?'}</h2><p class="install-lead">${active?'Riprendi le domande già salvate e consegna entro il tempo rimasto.':'Metti alla prova la tua preparazione e confrontati con gli altri candidati: 40 domande uguali per tutti e risultato soltanto alla fine.'}</p>${participants?`<p class="daily-reminder-participants"><b>${participants}</b> ${participants===1?'candidato è già entrato':'candidati sono già entrati'} in classifica oggi.</p>`:''}<div class="quiz-actions"><button class="ghost" type="button" data-daily-reminder-later>Più tardi</button><button class="primary" type="button" data-daily-reminder-open>${active?'Riprendi la Sfida':'Vai alla Sfida'}</button></div></section>`;document.body.append(overlay);const close=()=>overlay.remove();overlay.querySelector('[data-daily-reminder-later]').onclick=close;overlay.querySelector('[data-daily-reminder-open]').onclick=()=>{close();location.hash='challenge'};overlay.onclick=event=>{if(event.target===overlay)close()};overlay.querySelector('[data-daily-reminder-open]').focus()}

async function maybeShowDailyChallengeReminder(){if(dailyChallengeReminderCheckBusy||!cloudMode||!currentUser||currentUser.mustChangePassword||runtimeConfig.dailyChallengeEnabled===false||document.visibilityState==='hidden'||quiz||location.hash==='#challenge'||document.querySelector('[role="dialog"]'))return;const moment=italyChallengeReminderMoment();if(!moment)return;const state=userState();state.dailyChallengeReminders=normalizeChallengeReminderHistory(state.dailyChallengeReminders,moment.date);const seenSlots=state.dailyChallengeReminders[moment.date]||[],completedDates=state.dailyChallengeRecordedDates||[];if(seenSlots.includes(moment.slot)||completedDates.includes(moment.date))return;dailyChallengeReminderCheckBusy=true;try{const data=await cloudApi('./api/challenges/today');if(data.status==='completed'){await refreshUserAfterChallenge();return}if(!shouldShowChallengeReminder({status:data.status,date:data.date,moment,seenSlots,completedDates})||quiz||location.hash==='#challenge'||document.querySelector('[role="dialog"]'))return;state.dailyChallengeReminders[moment.date]=[...new Set([...seenSlots,moment.slot])];await saveUsers();if(!quiz&&location.hash!=='#challenge'&&!document.querySelector('[role="dialog"]'))openDailyChallengeReminder(data,moment)}catch{}finally{dailyChallengeReminderCheckBusy=false}}

function startDailyChallengeReminderChecks(){clearInterval(dailyChallengeReminderTimer);if(!cloudMode||!currentUser||runtimeConfig.dailyChallengeEnabled===false)return;setTimeout(maybeShowDailyChallengeReminder,2500);dailyChallengeReminderTimer=setInterval(maybeShowDailyChallengeReminder,60000)}

function challengeLeaderboardMarkup(board){const entries=Array.isArray(board?.entries)?board.entries:[],current=board?.currentUser;return `<section class="card daily-leaderboard"><div class="challenge-card-head"><div><div class="eyebrow">Classifica del giorno</div><h2>${Number(board?.participants||0)} ${Number(board?.participants||0)===1?'partecipante':'partecipanti'}</h2></div><button class="ghost compact" type="button" data-refresh-challenge>Ricarica</button></div>${current&&!entries.some(entry=>entry.isCurrentUser)?`<div class="daily-current-rank"><img class="daily-avatar" src="${esc(current.avatarUrl)}" alt=""><b>La tua posizione: ${current.rank}ª</b><span>${fmtMetric(current.score)} punti</span></div>`:''}${entries.length?`<div class="daily-ranking" role="table" aria-label="Classifica Sfida del giorno"><div class="daily-ranking-head" role="row"><span>Pos.</span><span>Partecipante</span><span>Punti</span><span>Risultato</span><span>Tempo</span></div>${entries.map(entry=>`<div class="daily-ranking-row ${entry.isCurrentUser?'current':''}" role="row"><strong>${entry.rank}</strong><span class="daily-participant"><img class="daily-avatar" src="${esc(entry.avatarUrl)}" alt="" loading="lazy" decoding="async"><span>${esc(entry.displayName)}${entry.isCurrentUser?' <small>Tu</small>':''}</span></span><b>${fmtMetric(entry.score)}</b><span>${entry.correct}✓ ${entry.wrong}✕ ${entry.blank}—</span><span>${formatChallengeDuration(entry.durationSeconds)}</span></div>`).join('')}</div>`:'<div class="challenge-empty-ranking"><b>La classifica è ancora vuota</b><span>Completa la sfida e inaugura la graduatoria di oggi.</span></div>'}<p class="meta">A parità di punteggio contano prima le risposte corrette, poi gli errori e infine il tempo impiegato.</p></section>`}

function challengeRulesMarkup(data){return `<section class="card daily-challenge-rules"><div class="daily-challenge-emblem" aria-hidden="true">★</div><div><div class="eyebrow">Uguale per tutti · ${esc(formatChallengeDate(data.date))}</div><h1>Sfida del giorno</h1><p>Una prova ufficiale da 40 domande e 40 minuti. Tutti ricevono gli stessi quesiti nello stesso ordine; soluzione, spiegazioni e punteggio appaiono soltanto dopo la consegna.</p><div class="daily-composition">${challengeCompositionMarkup(data.composition)}</div><div class="daily-rule-row"><span><b>+1</b> corretta</span><span><b>−0,33</b> errata</span><span><b>0</b> non risposta</span><span><b>1</b> risultato valido al giorno</span></div></div></section>`}

async function challengeView(){nav('challenge');clearInterval(timerHandle);clearTimeout(dailyChallengeDraftTimer);if(!cloudMode){app.innerHTML='<div class="notice">La Sfida del giorno è disponibile nel portale cloud.</div>';return}app.innerHTML='<div class="card challenge-loading"><b>Preparazione della Sfida del giorno…</b></div>';try{const data=await cloudApi('./api/challenges/today');renderChallengeLanding(data)}catch(error){app.innerHTML=`<div class="notice"><b>Sfida non disponibile</b><span>${esc(error.message)}</span></div>`}}

function renderChallengeLanding(data){quiz=null;clearInterval(timerHandle);const controls=data.status==='not_started'?`<section class="card daily-challenge-action"><div><h2>Pronto a entrare in classifica?</h2><p>Il cronometro parte quando premi il pulsante. Dopo l’avvio non potrai ricominciare la sfida di oggi.</p></div><button class="primary" type="button" data-start-daily-challenge>Avvia la sfida</button></section>`:`<section class="card daily-challenge-action active"><div><h2>Sfida in corso</h2><p>Hai ancora <b>${formatTime(data.remainingSeconds||0)}</b>. Il tempo continua a scorrere anche se chiudi questa schermata.</p></div><button class="primary" type="button" data-resume-daily-challenge>Riprendi la sfida</button></section>`;app.innerHTML=`${challengeRulesMarkup(data)}${challengeLeaderboardMarkup(data.leaderboard)}${data.status==='completed'?challengeCompletedMarkup(data):controls}`;app.querySelector('[data-start-daily-challenge]')?.addEventListener('click',startDailyChallenge);app.querySelector('[data-resume-daily-challenge]')?.addEventListener('click',()=>beginDailyChallenge(data));bindChallengeRefresh();if(data.status==='completed')window.scrollTo({top:0,behavior:'instant'})}

function challengeCompletedMarkup(data){const result=data.result||{},rank=data.leaderboard?.currentUser?.rank;return `<section class="daily-completed-summary">${resultCard('Sfida del giorno completata',result.correct||0,result.wrong||0,result.blank||0,'<a class="button primary" href="#stats">Apri le statistiche</a>')}${rank?`<div class="card daily-rank-highlight"><span>Posizione di oggi</span><strong>${rank}ª</strong><small>su ${data.leaderboard.participants} partecipanti</small></div>`:''}</section>${challengeReviewMarkup(data)}`}

function challengeReviewMarkup(data){const questions=data.result?.questions;if(!Array.isArray(questions)||!questions.length)return'';const rows=questions.map(question=>({q:question,choice:question.choice,blank:Boolean(question.blank),correct:Boolean(question.isCorrect)}));return `<details class="card daily-test-details"><summary><span><b>Il tuo test</b><small>Rivedi le 40 domande, le risposte e le spiegazioni</small></span><strong><i class="daily-test-open-label">Apri riepilogo</i><i class="daily-test-close-label">Chiudi riepilogo</i></strong></summary><div class="daily-test-review-body">${reviewReport(rows)}</div></details>`}

function bindChallengeRefresh(){app.querySelector('[data-refresh-challenge]')?.addEventListener('click',challengeView)}

async function startDailyChallenge(){const button=app.querySelector('[data-start-daily-challenge]');if(button){button.disabled=true;button.textContent='Avvio…'}try{beginDailyChallenge(await cloudApi('./api/challenges/today/start',{method:'POST',body:'{}'}))}catch(error){notify(error.message);challengeView()}}

function beginDailyChallenge(data){if(data.status==='completed'){renderChallengeLanding(data);return}if(!Array.isArray(data.questions)||data.questions.length!==40)return notify('La sfida ricevuta non contiene 40 domande');const answers=Array.isArray(data.answers)&&data.answers.length===40?data.answers:Array(40).fill(null),firstMissing=answers.findIndex(answer=>answer===null),index=firstMissing<0?0:firstMissing,remaining=Math.max(0,Number(data.remainingSeconds)||0);quiz={kind:'daily-challenge',mode:'daily-challenge',challengeDate:data.date,pool:data.questions,answers,index,selected:answers[index],remaining,deadlineAt:Date.now()+remaining*1000,finished:false,submitting:false};renderDailyChallengeQuestion();startDailyChallengeTimer()}

function dailyQuestionState(index){const answered=quiz.answers[index]!==null||(index===quiz.index&&quiz.selected!==null);return{className:answered?'answered':'unanswered',label:answered?'risposta data':'non fatta'}}

function dailyOverviewMarkup(){return `<section class="question-overview daily-question-overview" aria-label="Panoramica delle 40 domande"><div class="question-overview-head"><b>Panoramica domande</b><span>Tocca un numero per aprirlo</span></div><div class="question-dots">${quiz.pool.map((question,index)=>{const state=dailyQuestionState(index);return `<button type="button" class="question-dot ${state.className} ${index===quiz.index?'current':''}" data-daily-question-jump="${index}" aria-label="Domanda ${index+1}: ${state.label}" aria-current="${index===quiz.index?'step':'false'}">${index+1}</button>`}).join('')}</div><div class="question-legend"><span><i class="answered"></i>Risposta data</span><span><i class="unanswered"></i>Non fatta</span><span><i class="current"></i>Attuale</span></div></section>`}

function renderDailyChallengeQuestion(){if(!quiz||quiz.kind!=='daily-challenge')return;const question=quiz.pool[quiz.index],last=quiz.index===quiz.pool.length-1;app.innerHTML=`${timerMarkup()}${dailyOverviewMarkup()}<div class="quiz-head daily-quiz-head"><div><span class="meta">Sfida del giorno · correzione solo alla fine</span><br><strong>${esc(catName(question.category))}</strong></div><strong>${quiz.index+1}/${quiz.pool.length}</strong></div><div class="progress"><span style="width:${(quiz.index+1)/quiz.pool.length*100}%"></span></div><h1 class="question">${esc(question.text)}</h1>${question.image?`<img class="question-image" src="${esc(question.image)}" alt="Diagramma del quesito">`:''}<div class="answers">${question.answers.map((answer,index)=>`<button class="answer ${quiz.selected===index?'picked':''}" data-daily-answer="${index}"><span class="letter">${String.fromCharCode(65+index)}</span><span>${esc(answer)}</span></button>`).join('')}</div><div class="quiz-actions nav-actions"><button class="ghost danger-text" type="button" data-daily-finish>Termina e consegna</button>${quiz.index>0?'<button class="ghost" type="button" data-daily-prev>← Indietro</button>':''}<button class="ghost" type="button" data-daily-skip>Lascia in bianco</button><button class="primary" type="button" data-daily-next>${last?'Consegna prova':'Conferma e avanti →'}</button></div><p class="meta daily-answer-note">Puoi cambiare la scelta finché non premi “${last?'Consegna prova':'Conferma e avanti'}”. Le risposte corrette saranno mostrate solo alla fine.</p>`;app.querySelectorAll('[data-daily-answer]').forEach(button=>button.onclick=()=>dailySelectAnswer(Number(button.dataset.dailyAnswer)));app.querySelector('[data-daily-prev]')?.addEventListener('click',dailyPrevious);app.querySelector('[data-daily-skip]')?.addEventListener('click',dailySkip);app.querySelector('[data-daily-next]')?.addEventListener('click',dailyNext);app.querySelector('[data-daily-finish]')?.addEventListener('click',dailyRequestDelivery);app.querySelectorAll('[data-daily-question-jump]').forEach(button=>button.onclick=()=>dailyJump(Number(button.dataset.dailyQuestionJump)));const track=app.querySelector('.question-dots'),current=track?.querySelector('.current');if(track&&current)requestAnimationFrame(()=>track.scrollTo({left:Math.max(0,current.offsetLeft-track.clientWidth/2+current.clientWidth/2),behavior:'smooth'}));updateTimerDisplay()}

function dailySelectAnswer(choice){quiz.selected=choice;app.querySelectorAll('[data-daily-answer]').forEach((button,index)=>button.classList.toggle('picked',index===choice));app.querySelectorAll('[data-daily-question-jump]').forEach((button,index)=>{button.classList.toggle('answered',dailyQuestionState(index).className==='answered');button.classList.toggle('unanswered',dailyQuestionState(index).className==='unanswered')})}
function dailyCommitCurrent(){if(quiz?.kind==='daily-challenge')quiz.answers[quiz.index]=quiz.selected}
function dailyPrevious(){if(quiz.index<=0)return;dailyCommitCurrent();saveDailyChallengeDraft();quiz.index--;quiz.selected=quiz.answers[quiz.index];renderDailyChallengeQuestion()}
function dailyJump(target){if(!Number.isInteger(target)||target<0||target>=quiz.pool.length||target===quiz.index)return;dailyCommitCurrent();saveDailyChallengeDraft();quiz.index=target;quiz.selected=quiz.answers[target];renderDailyChallengeQuestion()}
function dailySkip(){quiz.selected=null;quiz.answers[quiz.index]=null;saveDailyChallengeDraft();if(quiz.index===quiz.pool.length-1)return dailyRequestDelivery();quiz.index++;quiz.selected=quiz.answers[quiz.index];renderDailyChallengeQuestion()}
function dailyNext(){dailyCommitCurrent();saveDailyChallengeDraft();if(quiz.index===quiz.pool.length-1)return dailyRequestDelivery();quiz.index++;quiz.selected=quiz.answers[quiz.index];renderDailyChallengeQuestion()}

function saveDailyChallengeDraft(immediate=false){if(!quiz||quiz.kind!=='daily-challenge'||quiz.finished)return Promise.resolve();clearTimeout(dailyChallengeDraftTimer);const challengeDate=quiz.challengeDate,answers=[...quiz.answers],send=()=>cloudApi(`./api/challenges/${encodeURIComponent(challengeDate)}/answers`,{method:'PUT',body:JSON.stringify({answers})}).then(async result=>{if(result.status==='completed'&&quiz?.kind==='daily-challenge'){await refreshUserAfterChallenge();quiz.finished=true;renderChallengeLanding(result)}}).catch(()=>{});if(immediate)return send();dailyChallengeDraftTimer=setTimeout(send,180);return Promise.resolve()}

function dailyMissingCount(){dailyCommitCurrent();return quiz.answers.filter(answer=>answer===null).length}
function dailyRequestDelivery(){const missing=dailyMissingCount();saveDailyChallengeDraft();document.querySelector('.delivery-confirm')?.remove();const overlay=document.createElement('div');overlay.className='delivery-confirm';overlay.innerHTML=`<div class="delivery-confirm-card" role="dialog" aria-modal="true" aria-labelledby="dailyDeliveryTitle"><div class="eyebrow">Consegna Sfida del giorno</div><h2 id="dailyDeliveryTitle">Confermi il risultato?</h2><p>${missing?`Hai ancora <strong>${missing}</strong> ${missing===1?'domanda non risposta':'domande non risposte'}.`:'Hai risposto a tutte le 40 domande.'} Dopo la consegna vedrai soluzioni, spiegazioni e posizione in classifica; non potrai ripetere la sfida di oggi.</p><div class="quiz-actions"><button class="ghost" type="button" data-cancel-daily-delivery>Continua la prova</button><button class="primary" type="button" data-confirm-daily-delivery>Consegna e vai in classifica</button></div></div>`;document.body.append(overlay);const close=()=>overlay.remove();overlay.querySelector('[data-cancel-daily-delivery]').onclick=close;overlay.querySelector('[data-confirm-daily-delivery]').onclick=()=>{close();submitDailyChallenge('completed')};overlay.onclick=event=>{if(event.target===overlay)close()}}

function startDailyChallengeTimer(){clearInterval(timerHandle);tickDailyChallengeTimer();if(quiz&&!quiz.finished&&quiz.remaining>0)timerHandle=setInterval(tickDailyChallengeTimer,1000)}
function tickDailyChallengeTimer(){if(!quiz||quiz.kind!=='daily-challenge'||quiz.finished){clearInterval(timerHandle);return}quiz.remaining=Math.max(0,Math.ceil((quiz.deadlineAt-Date.now())/1000));updateTimerDisplay();if(quiz.remaining===0){clearInterval(timerHandle);submitDailyChallenge('timeout')}}

async function refreshUserAfterChallenge(){try{const session=await cloudApi('./api/auth/me');users=[session.user];currentUser={...currentUser,name:session.user.name,email:session.user.email,role:session.user.role,mustChangePassword:Boolean(session.user.mustChangePassword)}}catch{}}
async function submitDailyChallenge(reason){if(!quiz||quiz.kind!=='daily-challenge'||quiz.submitting)return;dailyCommitCurrent();quiz.submitting=true;clearInterval(timerHandle);clearTimeout(dailyChallengeDraftTimer);const challengeDate=quiz.challengeDate,answers=[...quiz.answers];app.querySelectorAll('button').forEach(button=>button.disabled=true);notify(reason==='timeout'?'Tempo scaduto: calcolo del risultato…':'Calcolo del risultato…');try{const result=await cloudApi(`./api/challenges/${encodeURIComponent(challengeDate)}/submit`,{method:'POST',body:JSON.stringify({answers})});await refreshUserAfterChallenge();quiz.finished=true;renderChallengeLanding(result)}catch(error){quiz.submitting=false;notify(error.message);challengeView()}}

function requestLeaveDailyChallenge(target){document.querySelector('.delivery-confirm')?.remove();const overlay=document.createElement('div');overlay.className='delivery-confirm';overlay.innerHTML=`<div class="delivery-confirm-card" role="dialog" aria-modal="true"><div class="eyebrow">Sfida in corso</div><h2>Vuoi cambiare menu?</h2><p>Le risposte confermate restano salvate, ma <strong>il cronometro continuerà a scorrere</strong>. Potrai riprendere la stessa sfida entro il tempo rimasto.</p><div class="quiz-actions"><button class="primary" type="button" data-stay-daily>Resta nella sfida</button><button class="ghost" type="button" data-leave-daily>Esci e continua il timer</button></div></div>`;document.body.append(overlay);const close=()=>overlay.remove();overlay.querySelector('[data-stay-daily]').onclick=close;overlay.querySelector('[data-leave-daily]').onclick=async()=>{dailyCommitCurrent();await saveDailyChallengeDraft(true);clearInterval(timerHandle);quiz=null;close();if(location.hash===target)router();else location.hash=target};overlay.onclick=event=>{if(event.target===overlay)close()}}

const guardQuizMenuNavigationBeforeChallenge=guardQuizMenuNavigation;
guardQuizMenuNavigation=function(event){if(quiz?.kind!=='daily-challenge')return guardQuizMenuNavigationBeforeChallenge(event);const link=event.target.closest('.bottom-nav a,.brand');if(!link||quiz.finished)return;const target=link.getAttribute('href');if(!target?.startsWith('#')||target===location.hash)return;event.preventDefault();event.stopImmediatePropagation();requestLeaveDailyChallenge(target)};

const logoutBeforeChallenge=logout;
logout=async function(){clearInterval(dailyChallengeReminderTimer);document.querySelector('[data-daily-challenge-reminder]')?.remove();if(quiz?.kind==='daily-challenge'){dailyCommitCurrent();await saveDailyChallengeDraft(true)}return logoutBeforeChallenge()};

const setHeaderBeforeChallenge=setHeader;
setHeader=function(){setHeaderBeforeChallenge();document.querySelector('.daily-challenge-nav')?.classList.toggle('hidden',!cloudMode||runtimeConfig.dailyChallengeEnabled===false)};

const homeBeforeChallenge=home;
home=function(){homeBeforeChallenge();if(!cloudMode||runtimeConfig.dailyChallengeEnabled===false)return;const quick=app.querySelector('.quick-grid');if(quick&&!quick.querySelector('[href="#challenge"]'))quick.insertAdjacentHTML('afterbegin','<a class="card quick daily-challenge-quick" href="#challenge"><b>★ Sfida del giorno</b><span>Stesse 40 domande per tutti · entra in classifica</span></a>');const actions=app.querySelector('.hero-actions');if(actions&&!actions.querySelector('[href="#challenge"]'))actions.insertAdjacentHTML('beforeend','<a class="button ghost light" href="#challenge">Sfida del giorno</a>')};

const cloudSettingsMarkupBeforeChallenge=cloudSettingsMarkup;
const dailyChallengeLogicTopics=logicTopics.filter(topic=>topic.id!=='brani');
function dailyChallengeAdminMarkup(){return `<fieldset class="daily-challenge-admin-settings"><legend>Sfida del giorno</legend><label class="check-label full"><input name="dailyChallengeEnabled" type="checkbox"> Attiva Sfida del giorno e classifica</label><p class="meta full">Questa composizione è uguale per tutti. Una sfida già creata oggi, i tentativi e la classifica in corso non vengono mai rigenerati quando salvi.</p><div class="daily-admin-plan full">${categories.map(category=>`<label>${esc(category.name)}<input data-daily-plan type="number" min="0" max="40" step="1" name="dailyPlan-${category.id}"></label>`).join('')}</div><div class="daily-admin-total full">Totale prova: <strong data-daily-plan-total>0</strong>/40</div><div class="daily-admin-logic full"><div><h3>Sottosezioni di Logica</h3><p class="meta">La somma deve coincidere con il numero impostato in Logica.</p></div><div class="daily-admin-logic-grid">${dailyChallengeLogicTopics.map(topic=>`<label>${esc(topic.shortName)}<input data-daily-logic type="number" min="0" max="40" step="1" name="dailyLogic-${topic.id}"></label>`).join('')}</div><div class="daily-admin-logic-total">Logica: <strong data-daily-logic-total>0</strong>/<strong data-daily-logic-target>0</strong></div><div class="daily-no-passages"><b>Brani esclusi</b><span>I quesiti di comprensione dei brani non possono entrare nella Sfida del giorno.</span></div><button class="ghost compact" type="button" data-balance-daily-logic>Distribuisci Logica</button></div><div class="quiz-actions full"><button class="secondary" type="button" data-save-daily-settings>Salva composizione Sfida</button></div></fieldset>`}
cloudSettingsMarkup=function(){return cloudSettingsMarkupBeforeChallenge().replace('</fieldset><fieldset class="privacy-admin-settings">',`</fieldset>${dailyChallengeAdminMarkup()}<fieldset class="privacy-admin-settings">`)};

function dailyChallengeConfigFromForm(form){const examPlan=Object.fromEntries(categories.map(category=>[category.id,Math.max(0,Math.floor(Number(form.elements.namedItem(`dailyPlan-${category.id}`)?.value)||0))])),logicPlan=Object.fromEntries(dailyChallengeLogicTopics.map(topic=>[topic.id,Math.max(0,Math.floor(Number(form.elements.namedItem(`dailyLogic-${topic.id}`)?.value)||0))]));logicPlan.brani=0;return{examPlan,logicPlan}}

function refreshDailyChallengeAdminTotals(form){const config=dailyChallengeConfigFromForm(form),planTotalValue=Object.values(config.examPlan).reduce((sum,value)=>sum+value,0),logicTotalValue=dailyChallengeLogicTopics.reduce((sum,topic)=>sum+(config.logicPlan[topic.id]||0),0),logicTarget=config.examPlan.logica||0;form.querySelector('[data-daily-plan-total]').textContent=planTotalValue;form.querySelector('[data-daily-logic-total]').textContent=logicTotalValue;form.querySelector('[data-daily-logic-target]').textContent=logicTarget;form.querySelector('.daily-admin-total')?.classList.toggle('invalid',planTotalValue!==40);form.querySelector('.daily-admin-logic')?.classList.toggle('invalid',logicTotalValue!==logicTarget);return{config,valid:planTotalValue===40&&logicTotalValue===logicTarget}}

async function saveDailyChallengeAdminSettings(form,showSuccess=true){const state=refreshDailyChallengeAdminTotals(form);if(!state.valid){notify('La prova deve avere 40 domande e la distribuzione di Logica deve coincidere');return false}const button=form.querySelector('[data-save-daily-settings]');if(button){button.disabled=true;button.textContent='Salvataggio…'}try{const result=await cloudApi('./api/admin/challenge-settings',{method:'PUT',body:JSON.stringify({enabled:form.elements.dailyChallengeEnabled.checked,config:state.config})});runtimeConfig={...runtimeConfig,dailyChallengeEnabled:result.enabled};setHeader();if(showSuccess)notify(result.currentChallengePreserved?'Configurazione salvata: sfida e classifica di oggi restano invariate':'Configurazione della Sfida salvata');return true}catch(error){notify(error.message);return false}finally{if(button){button.disabled=false;button.textContent='Salva composizione Sfida'}}}

function bindDailyChallengeAdminSettings(form){const inputs=[...form.querySelectorAll('[data-daily-plan],[data-daily-logic]')];inputs.forEach(input=>input.oninput=()=>refreshDailyChallengeAdminTotals(form));const balanceButton=form.querySelector('[data-balance-daily-logic]');if(balanceButton)balanceButton.onclick=()=>{const target=Math.max(0,Math.floor(Number(form.elements.namedItem('dailyPlan-logica')?.value)||0)),logicInputs=[...form.querySelectorAll('[data-daily-logic]')];logicInputs.forEach(input=>input.value=0);for(let index=0;index<target;index++)logicInputs[index%logicInputs.length].value=Number(logicInputs[index%logicInputs.length].value)+1;refreshDailyChallengeAdminTotals(form)};const saveButton=form.querySelector('[data-save-daily-settings]');if(saveButton)saveButton.onclick=()=>saveDailyChallengeAdminSettings(form);refreshDailyChallengeAdminTotals(form)}

const loadCloudSettingsBeforeChallenge=loadCloudSettings;
loadCloudSettings=async function(){await loadCloudSettingsBeforeChallenge();const form=app.querySelector('#cloudSettingsForm');if(!form)return;try{const settings=await cloudApi('./api/admin/settings'),config=settings.dailyChallengeConfig||{examPlan:DEFAULT_EXAM_PLAN,logicPlan:DEFAULT_LOGIC_PLAN};form.elements.dailyChallengeEnabled.checked=Boolean(settings.dailyChallengeEnabled);for(const category of categories){const input=form.elements.namedItem(`dailyPlan-${category.id}`);if(input)input.value=Number(config.examPlan?.[category.id])||0}for(const topic of dailyChallengeLogicTopics){const input=form.elements.namedItem(`dailyLogic-${topic.id}`);if(input)input.value=Number(config.logicPlan?.[topic.id])||0}bindDailyChallengeAdminSettings(form);const generalSubmit=form.onsubmit;form.onsubmit=async event=>{event.preventDefault();if(!await saveDailyChallengeAdminSettings(form,false))return;if(typeof generalSubmit==='function')await generalSubmit({preventDefault(){},currentTarget:form})}}catch(error){notify(error.message)}};

const privacyViewBeforeChallenge=privacyView;
privacyView=function(){privacyViewBeforeChallenge();const sections=[...app.querySelectorAll('.privacy-section')],dataSection=sections.find(section=>section.querySelector('h2')?.textContent.startsWith('2.')),recipientSection=sections.find(section=>section.querySelector('h2')?.textContent.startsWith('5.'));dataSection?.querySelector('ul')?.insertAdjacentHTML('beforeend','<li><b>Foto profilo facoltativa:</b> l’utente può caricarla, sostituirla o rimuoverla dalla schermata Account. Se presente appare nella classifica interna; in sua assenza viene usata l’immagine profilo predefinita.</li><li><b>Sfida del giorno:</b> risposte, punteggio, tempo impiegato e posizione. Nella classifica visibile ai soli utenti autenticati compaiono nome visualizzato e foto profilo scelti per l’account.</li><li><b>Segnalazioni quesiti:</b> quesito indicato, motivo, nota facoltativa, nome visualizzato e data della segnalazione, accessibili soltanto agli amministratori per correggere la banca dati.</li>');recipientSection?.insertAdjacentHTML('beforeend','<p><b>Classifica interna:</b> gli utenti autenticati possono vedere nome visualizzato, foto profilo e risultato dei partecipanti alla Sfida del giorno. Email, nome utente e dettagli delle singole risposte non vengono mostrati in classifica.</p>')};

/* Segnalazione e moderazione dei quesiti */
function questionReportButtonMarkup(question,source='quiz'){if(!cloudMode||!currentUser||!question?.id||disabledQuestionIds.has(String(question.id)))return'';return `<div class="question-report-action"><button class="ghost compact" type="button" data-report-question="${esc(question.id)}" data-report-source="${esc(source)}">⚑ Segnala quesito errato</button></div>`}
function appendCurrentQuestionReportButton(question,source){const actions=app.querySelector('.nav-actions');if(actions&&!app.querySelector('.current-question-report'))actions.insertAdjacentHTML('beforebegin',`<div class="current-question-report">${questionReportButtonMarkup(question,source)}</div>`)}
const renderQuestionBeforeReporting=renderQuestion;
renderQuestion=function(){renderQuestionBeforeReporting();appendCurrentQuestionReportButton(quiz?.pool?.[quiz.index],'quiz')};
const renderGuidedBeforeReporting=renderGuided;
renderGuided=function(){renderGuidedBeforeReporting();appendCurrentQuestionReportButton(quiz?.pool?.[quiz.index],'quiz guidato')};
const renderDailyChallengeQuestionBeforeReporting=renderDailyChallengeQuestion;
renderDailyChallengeQuestion=function(){renderDailyChallengeQuestionBeforeReporting();appendCurrentQuestionReportButton(quiz?.pool?.[quiz.index],'sfida del giorno')};

function openQuestionReportDialog(questionId,source){const question=official.find(item=>String(item.id)===String(questionId))||imported.find(item=>String(item.id)===String(questionId))||quiz?.pool?.find(item=>String(item.id)===String(questionId));if(!question)return notify('Quesito non trovato');document.querySelector('[data-question-report-dialog]')?.remove();const overlay=document.createElement('div');overlay.className='install-dialog-backdrop question-report-backdrop';overlay.dataset.questionReportDialog='';overlay.innerHTML=`<section class="card install-dialog question-report-dialog" role="dialog" aria-modal="true" aria-labelledby="questionReportTitle"><div class="eyebrow">Segnalazione all’amministratore</div><h2 id="questionReportTitle">Cosa non va in questo quesito?</h2><p class="question-report-preview"><b>${esc(catName(question.category))} · ID ${esc(question.id)}</b><span>${esc(question.text)}</span></p><form data-question-report-form><label>Tipo di problema<select name="reason" required><option value="question">Testo o domanda errata</option><option value="answer">Risposta corretta errata</option><option value="explanation">Spiegazione errata o illeggibile</option><option value="image">Immagine mancante o errata</option><option value="other">Altro</option></select></label><label>Nota facoltativa<textarea name="note" maxlength="1500" placeholder="Descrivi brevemente cosa hai notato…"></textarea></label><p class="meta">La segnalazione include soltanto il quesito e il tuo nome visualizzato. La prova in corso non viene interrotta.</p><div class="quiz-actions"><button class="ghost" type="button" data-question-report-close>Annulla</button><button class="primary" type="submit">Invia segnalazione</button></div></form></section>`;document.body.append(overlay);const close=()=>overlay.remove();overlay.querySelector('[data-question-report-close]').onclick=close;overlay.onclick=event=>{if(event.target===overlay)close()};overlay.querySelector('[data-question-report-form]').onsubmit=async event=>{event.preventDefault();const button=event.submitter,form=new FormData(event.currentTarget);button.disabled=true;button.textContent='Invio…';try{const result=await cloudApi('./api/question-reports',{method:'POST',body:JSON.stringify({question_id:String(question.id),reason:String(form.get('reason')),note:String(form.get('note')||'').trim(),source})});close();notify(result.message)}catch(error){button.disabled=false;button.textContent='Invia segnalazione';notify(error.message)}};overlay.querySelector('select')?.focus()}

function updateAdminReportBadge(count=adminQuestionReports.pendingCount||0){const link=document.querySelector('[data-route="settings"]');if(!link)return;let badge=link.querySelector('[data-admin-report-badge]');if(count>0){if(!badge){badge=document.createElement('em');badge.dataset.adminReportBadge='';link.append(badge)}badge.textContent=count>99?'99+':String(count);badge.setAttribute('aria-label',`${count} segnalazioni quesiti da revisionare`)}else badge?.remove()}
function updateAdminUserBadge(count=adminPendingApprovalCount){const link=document.querySelector('[data-route="users"]');if(!link)return;let badge=link.querySelector('[data-admin-user-badge]');if(count>0){if(!badge){badge=document.createElement('em');badge.dataset.adminUserBadge='';link.append(badge)}badge.textContent=count>99?'99+':String(count);badge.setAttribute('aria-label',`${count} utenti in attesa di approvazione`)}else badge?.remove()}
function questionAnswerListMarkup(question){const correct=Number(question.correct);return `<ol class="moderation-answers">${(question.answers||[]).map((answer,index)=>`<li class="${index===correct?'correct':''}">${esc(answer)}${index===correct?' <b>✓ indicata come corretta</b>':''}</li>`).join('')}</ol>`}

let questionReplyTimer=null,questionReplyLoading=false,questionReplySnooze=0;
function stopQuestionReplyChecks(){clearInterval(questionReplyTimer);questionReplyTimer=null;questionReplySnooze=0;document.querySelector('[data-report-reply-popup]')?.remove()}
function startQuestionReplyChecks(){stopQuestionReplyChecks();if(!cloudMode||!currentUser)return;questionReplyTimer=setInterval(checkQuestionReplies,30000);checkQuestionReplies()}
function canShowQuestionReply(){return cloudMode&&currentUser&&!currentUser.mustChangePassword&&document.visibilityState==='visible'&&!(quiz&&!quiz.finished)&&Date.now()>=questionReplySnooze&&!document.querySelector('[role="dialog"],.delivery-confirm')}
async function checkQuestionReplies(){
  if(questionReplyLoading||!canShowQuestionReply())return;
  const viewer=currentUser.id;
  questionReplyLoading=true;
  try{
    const data=await cloudApi('./api/question-reports/replies');
    if(currentUser?.id!==viewer||!canShowQuestionReply()||!data.replies?.length)return;
    const report=data.replies[0],question=report.question||{},accepted=report.status==='resolved',overlay=document.createElement('div'),previousFocus=document.activeElement;
    overlay.className='install-dialog-backdrop question-report-backdrop';overlay.dataset.reportReplyPopup='';
    overlay.innerHTML=`<section class="card install-dialog question-report-dialog" role="dialog" aria-modal="true" aria-labelledby="reportReplyTitle"><div class="eyebrow">Risposta alla tua segnalazione</div><h2 id="reportReplyTitle">${accepted?'Segnalazione accolta':'Quesito verificato: è corretto'}</h2><p>${accepted?'Il quesito è stato escluso dalle nuove esercitazioni. La soluzione indicata nella banca dati potrebbe essere errata.':'L’amministratore ha verificato il quesito: resta disponibile per lo studio.'}</p><p class="question-report-preview"><b>${esc(catName(question.category))} · #${esc(report.questionId)}</b><span>${esc(question.text)}</span></p>${question.image?`<img class="question-image mini" src="${esc(question.image)}" alt="Figura del quesito segnalato">`:''}${questionAnswerListMarkup(question)}<h3>Risposta dell’amministratore</h3><p class="report-admin-reply" style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(report.reply)}</p>${question.explanation?`<details><summary>Spiegazione presente nella banca dati${accepted?' (in revisione)':''}</summary><p style="white-space:pre-wrap">${esc(question.explanation)}</p></details>`:''}<div class="quiz-actions"><button class="ghost" data-reply-later>Più tardi</button><button class="primary" data-reply-read>Ho letto</button></div><p class="meta" data-reply-error role="status"></p></section>`;
    const close=()=>{overlay.remove();if(previousFocus?.isConnected)previousFocus.focus()};
    overlay.querySelector('[data-reply-later]').onclick=()=>{questionReplySnooze=Date.now()+5*60000;close()};
    overlay.querySelector('[data-reply-read]').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{await cloudApi(`./api/question-reports/${encodeURIComponent(report.id)}/read`,{method:'POST'});close();checkQuestionReplies()}catch(error){button.disabled=false;overlay.querySelector('[data-reply-error]').textContent=error.message}};
    overlay.onkeydown=event=>{if(event.key==='Escape'){event.preventDefault();overlay.querySelector('[data-reply-later]').click()}if(event.key==='Tab'){const items=[...overlay.querySelectorAll('button:not(:disabled),summary')],first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}};
    document.body.append(overlay);overlay.querySelector('[data-reply-read]').focus();
  }catch{/* Ritenta al prossimo controllo senza disturbare lo studio. */}finally{questionReplyLoading=false}
}
function moderationReportCardMarkup(report){const question=report.question||{};return `<article class="card moderation-report-card"><div class="moderation-card-head"><div><div class="eyebrow">${esc(report.reasonLabel)} · ${esc(catName(question.category))}</div><h3>${esc(question.text)}</h3></div><span>#${esc(question.id)}</span></div>${question.image?`<img class="question-image mini" src="${esc(question.image)}" alt="Immagine del quesito segnalato">`:''}${questionAnswerListMarkup(question)}${question.explanation?`<details class="moderation-explanation"><summary>Spiegazione attuale</summary><p>${esc(question.explanation)}</p></details>`:''}<div class="moderation-report-note"><b>Segnalato da ${esc(report.reporter)}</b><span>${new Date(report.createdAt).toLocaleString('it-IT')}</span><p>${report.note?esc(report.note):'Nessuna nota aggiuntiva.'}</p></div><label>Risposta all’utente<textarea data-moderation-reply maxlength="4000" rows="4" placeholder="Spiega l’esito della revisione e aiuta l’utente a capire la soluzione…"></textarea></label><p class="meta">La risposta arriverà con un popup personale. Disabilitando il quesito risponderai a tutte le segnalazioni in attesa per questa domanda.</p><div class="quiz-actions"><button class="ghost" type="button" data-dismiss-question-report="${esc(report.id)}">Quesito corretto: invia spiegazione</button><button class="primary danger-action" type="button" data-disable-reported-question="${esc(question.id)}" data-report-id="${esc(report.id)}">Accogli e disabilita quesito</button></div></article>`}
function disabledQuestionCardMarkup(item){const question=item.question||{};return `<article class="disabled-question-row"><div><b>${esc(catName(question.category))} · #${esc(item.questionId)}</b><span>${esc(question.text)}</span><small>${esc(item.reason||'Disattivato dopo revisione')}</small></div><button class="ghost compact" type="button" data-enable-question="${esc(item.questionId)}">Riattiva</button></article>`}
function questionModerationPanelMarkup(){return `<section class="question-moderation-panel" data-question-moderation-panel><div class="section-head"><div><div class="eyebrow">Controllo qualità banca dati</div><h1>Segnalazioni quesiti</h1></div><button class="ghost compact" type="button" data-refresh-question-reports>Ricarica</button></div><div class="card moderation-loading">Caricamento segnalazioni…</div></section>`}
function renderQuestionModerationPanel(){const panel=app.querySelector('[data-question-moderation-panel]');if(!panel)return;const pending=adminQuestionReports.pending||[],disabled=adminQuestionReports.disabled||[];panel.innerHTML=`<div class="section-head"><div><div class="eyebrow">Controllo qualità banca dati</div><h1>Segnalazioni quesiti</h1></div><button class="ghost compact" type="button" data-refresh-question-reports>Ricarica</button></div><div class="moderation-summary"><span><b>${pending.length}</b> da revisionare</span><span><b>${disabled.length}</b> non disponibili</span><span>Le prove e le classifiche già create non vengono modificate.</span></div>${pending.length?`<div class="moderation-report-list">${pending.map(moderationReportCardMarkup).join('')}</div>`:'<div class="card moderation-empty"><b>Nessuna segnalazione in attesa</b><span>I nuovi avvisi compariranno qui e nel contatore del menu Admin.</span></div>'}<details class="card disabled-question-list" ${disabled.length?'':'open'}><summary>Quesiti non disponibili (${disabled.length})</summary><div>${disabled.length?disabled.map(disabledQuestionCardMarkup).join(''):'<p class="meta">Nessun quesito è stato disattivato.</p>'}</div></details>`;bindQuestionModerationPanel()}
function bindQuestionModerationPanel(){app.querySelector('[data-refresh-question-reports]')?.addEventListener('click',()=>loadAdminQuestionReports(false));app.querySelectorAll('[data-dismiss-question-report]').forEach(button=>button.onclick=async()=>{const field=button.closest('.moderation-report-card').querySelector('[data-moderation-reply]'),reply=field.value.trim();if(!reply){notify('Scrivi una spiegazione per l’utente prima di chiudere la segnalazione.');field.focus();return}button.disabled=true;try{const result=await cloudApi(`./api/admin/question-reports/${encodeURIComponent(button.dataset.dismissQuestionReport)}/dismiss`,{method:'POST',body:JSON.stringify({reply})});notify(result.message);await loadAdminQuestionReports(false)}catch(error){button.disabled=false;notify(error.message)}});app.querySelectorAll('[data-disable-reported-question]').forEach(button=>button.onclick=async()=>{if(!confirm('Rendere questo quesito non disponibile nelle nuove esercitazioni?\n\nLe prove e le classifiche già create resteranno invariate.'))return;button.disabled=true;try{const report=adminQuestionReports.pending.find(item=>item.id===button.dataset.reportId),reason=[report?.reasonLabel,report?.note].filter(Boolean).join(' — ');const result=await cloudApi(`./api/admin/questions/${encodeURIComponent(button.dataset.disableReportedQuestion)}/disable`,{method:'POST',body:JSON.stringify({reason,reply:button.closest('.moderation-report-card').querySelector('[data-moderation-reply]').value.trim()})});notify(result.message);await Promise.all([loadAdminQuestionReports(false),loadQuestionAvailability()])}catch(error){button.disabled=false;notify(error.message)}});app.querySelectorAll('[data-enable-question]').forEach(button=>button.onclick=async()=>{if(!confirm('Riattivare questo quesito nelle nuove esercitazioni?'))return;button.disabled=true;try{const result=await cloudApi(`./api/admin/questions/${encodeURIComponent(button.dataset.enableQuestion)}/disable`,{method:'DELETE'});notify(result.message);await Promise.all([loadAdminQuestionReports(false),loadQuestionAvailability()])}catch(error){button.disabled=false;notify(error.message)}})}
async function loadAdminQuestionReports(showNotice=true){if(!cloudMode||currentUser?.role!=='admin')return;try{const previous=Number(adminQuestionReports.pendingCount||0),data=await cloudApi('./api/admin/question-reports');adminQuestionReports=data;updateAdminReportBadge(data.pendingCount);if(!showNotice||![...app.querySelectorAll('[data-moderation-reply]')].some(field=>field.value.trim()))renderQuestionModerationPanel();if(showNotice&&data.pendingCount>0&&(!adminReportNoticeShown||data.pendingCount>previous)){notify(`${data.pendingCount} ${data.pendingCount===1?'segnalazione quesito da revisionare':'segnalazioni quesiti da revisionare'} nel pannello Admin`);adminReportNoticeShown=true}}catch{}}
async function loadAdminPendingApprovals(showNotice=true){if(!cloudMode||currentUser?.role!=='admin')return;try{const previous=adminPendingApprovalCount,data=await cloudApi('./api/admin/users/pending-count');adminPendingApprovalCount=Number(data.pendingCount||0);updateAdminUserBadge(adminPendingApprovalCount);if(showNotice&&adminPendingApprovalCount>0&&(!adminPendingApprovalNoticeShown||adminPendingApprovalCount>previous)){notify(`${adminPendingApprovalCount} ${adminPendingApprovalCount===1?'utente in attesa':'utenti in attesa'} di approvazione`);adminPendingApprovalNoticeShown=true}}catch{}}
function loadAdminNotifications(showNotice=true){return Promise.all([loadAdminQuestionReports(showNotice),loadAdminPendingApprovals(showNotice)])}
function startAdminReportChecks(){startQuestionReplyChecks();clearInterval(adminReportCheckTimer);if(!cloudMode||currentUser?.role!=='admin'){updateAdminReportBadge(0);updateAdminUserBadge(0);return}loadAdminNotifications(true);adminReportCheckTimer=setInterval(()=>loadAdminNotifications(true),90000)}

const settingsViewBeforeQuestionModeration=settingsView;
settingsView=function(){settingsViewBeforeQuestionModeration();if(!cloudMode||currentUser?.role!=='admin')return;app.insertAdjacentHTML('afterbegin',questionModerationPanelMarkup());loadAdminQuestionReports(false)};
const setHeaderBeforeQuestionModeration=setHeader;
setHeader=function(){setHeaderBeforeQuestionModeration();updateAdminReportBadge(currentUser?.role==='admin'?adminQuestionReports.pendingCount:0);updateAdminUserBadge(currentUser?.role==='admin'?adminPendingApprovalCount:0)};
const signInBeforeQuestionModeration=signIn;
signIn=function(user){adminReportNoticeShown=false;adminPendingApprovalNoticeShown=false;signInBeforeQuestionModeration(user);if(cloudMode){loadQuestionAvailability().then(()=>{if(!quiz)router()});startAdminReportChecks();startDailyChallengeReminderChecks()}};
const logoutBeforeQuestionModeration=logout;
logout=async function(){stopQuestionReplyChecks();clearInterval(adminReportCheckTimer);adminQuestionReports={pendingCount:0,pending:[],disabled:[]};adminPendingApprovalCount=0;disabledQuestionIds=new Set();questionAvailabilityRevision='';adminReportNoticeShown=false;adminPendingApprovalNoticeShown=false;return logoutBeforeQuestionModeration()};

window.addEventListener('hashchange',router);document.addEventListener('click',guardQuizMenuNavigation,true);document.addEventListener('click',event=>{const button=event.target.closest('[data-report-question]');if(button)openQuestionReportDialog(button.dataset.reportQuestion,button.dataset.reportSource||'quiz')});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&currentUser){checkForUpdates(false,true);loadQuestionAvailability();maybeShowDailyChallengeReminder();if(currentUser.role==='admin')loadAdminNotifications(true)}});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;document.querySelector('#installBtn').classList.remove('hidden')});document.querySelector('#installBtn').onclick=openInstallHelp;applyDeviceLayout();
if('serviceWorker'in navigator){const hadController=Boolean(navigator.serviceWorker.controller);navigator.serviceWorker.register('./sw.js').then(()=>{let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController&&!refreshing){refreshing=true;location.reload()}})}).catch(()=>{})}
app.innerHTML='<div class="card">Caricamento banca dati…</div>';
async function bootstrapApplication(){try{try{const response=await fetch('./api/runtime',{cache:'no-store'});if(response.ok){runtimeConfig=await response.json();cloudMode=runtimeConfig.mode==='cloud'}}catch{}if(cloudMode){document.documentElement.classList.add('cloud-mode');document.title=runtimeConfig.siteName||document.title;document.querySelector('.brand>span:last-child').textContent=runtimeConfig.siteName||'Quiz 400 VVF 2026';examConfig=normalizeExamConfigValue(runtimeConfig.examConfig||examConfig);localStorage.removeItem(USERS);try{const session=await cloudApi('./api/auth/me');examConfig=normalizeExamConfigValue(session.config||examConfig);users=[session.user];currentUser={id:session.user.id,name:session.user.name,username:session.user.username,email:session.user.email,role:session.user.role,mustChangePassword:Boolean(session.user.mustChangePassword)}}catch{users=[];currentUser=null}}else{try{const response=await fetch('./api/state');if(response.ok){const state=await response.json();if(Array.isArray(state.users)){users=state.users;localStorage.setItem(USERS,JSON.stringify(users))}if(Array.isArray(state.imported)){imported=state.imported;localStorage.setItem(DATA,JSON.stringify(imported))}if(state.config?.examPlan){examConfig=normalizeExamConfigValue(state.config);localStorage.setItem(CONFIG,JSON.stringify(examConfig))}}}catch{}}const dataset=await fetch('./quiz-dataset.json');if(!dataset.ok)throw Error();official=await dataset.json();if(!cloudMode){const id=sessionStorage.getItem(SESSION),u=users.find(x=>x.id===id&&x.active);if(u)currentUser={id:u.id,name:u.name,role:u.role}}else if(currentUser)await loadQuestionAvailability();applyBranding();applyTheme();router();if(currentUser){startAutomaticUpdateChecks();startAdminReportChecks();startDailyChallengeReminderChecks()}}catch{app.innerHTML='<div class="notice">Impossibile caricare la banca dati.</div>'}}
bootstrapApplication().then(()=>{if(currentUser)setTimeout(maybeShowReleaseNotes,500)});
